-- ======================================================================
-- 0001_core.sql
-- ======================================================================
-- 0001_core.sql
-- Tenancy, plans and modules, staff, locations, audit log and the helpers every
-- later file leans on. Nothing here knows what kind of shop it is running.

set check_function_bodies = off;

-- ---------------------------------------------------------------------------
-- Enums
-- ---------------------------------------------------------------------------

-- Every capability beyond the catalogue and the stock ledger is a module. Plans
-- switch groups of them on; vertical add-ons (serial numbers, batches and
-- expiry, warranty) are switched on per client regardless of plan.
create type public.module_key as enum (
  'storefront', 'pos', 'multi_location', 'purchasing', 'transfers', 'returns',
  'promotions', 'loyalty', 'wholesale', 'reviews', 'mobile_app',
  'serial_tracking', 'batch_tracking', 'warranty'
);

create type public.staff_role as enum ('owner', 'admin', 'manager', 'cashier', 'stock_keeper', 'viewer');
create type public.location_kind as enum ('store', 'warehouse');

-- ---------------------------------------------------------------------------
-- Organisations, plans, modules
-- ---------------------------------------------------------------------------

create table public.organizations (
  id            uuid primary key default gen_random_uuid(),
  name          text not null check (length(btrim(name)) > 0),
  slug          text not null unique check (slug ~ '^[a-z0-9][a-z0-9-]{1,62}$'),
  currency_code char(3) not null default 'LKR' check (currency_code ~ '^[A-Z]{3}$'),
  timezone      text not null default 'Asia/Colombo',
  settings      jsonb not null default '{}'::jsonb,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

create table public.plans (
  code     text primary key,
  name     text not null,
  modules  public.module_key[] not null,
  position int not null default 0
);

-- Reference data, not demo content: these are the packages NWS sells.
insert into public.plans (code, name, modules, position) values
  ('ecommerce',     'E-Commerce',     array['storefront','reviews','promotions']::public.module_key[], 1),
  ('ecommerce_pro', 'E-Commerce Pro', array['storefront','reviews','promotions','purchasing','returns']::public.module_key[], 2),
  ('retail',        'Retail',         array['storefront','reviews','promotions','purchasing','returns','pos']::public.module_key[], 3),
  ('omnichannel',   'Omnichannel',    array['storefront','reviews','promotions','purchasing','returns','pos',
                                              'multi_location','transfers','loyalty']::public.module_key[], 4),
  ('enterprise',    'Enterprise',     array['storefront','reviews','promotions','purchasing','returns','pos',
                                              'multi_location','transfers','loyalty','wholesale','mobile_app']::public.module_key[], 5);

create table public.organization_modules (
  organization_id uuid not null references public.organizations(id) on delete cascade,
  module          public.module_key not null,
  enabled         boolean not null default true,
  changed_at      timestamptz not null default now(),
  primary key (organization_id, module)
);

-- ---------------------------------------------------------------------------
-- Staff and locations
-- ---------------------------------------------------------------------------

create table public.memberships (
  organization_id uuid not null references public.organizations(id) on delete cascade,
  user_id         uuid not null references auth.users(id) on delete cascade,
  role            public.staff_role not null,
  -- null means every location; otherwise the member may only act at these.
  location_ids    uuid[],
  is_active       boolean not null default true,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  primary key (organization_id, user_id)
);
create index memberships_user_idx on public.memberships (user_id);

create table public.locations (
  id                  uuid primary key default gen_random_uuid(),
  organization_id     uuid not null references public.organizations(id) on delete cascade,
  code                text not null check (code ~ '^[A-Z0-9][A-Z0-9_-]{0,15}$'),
  name                text not null check (length(btrim(name)) > 0),
  kind                public.location_kind not null default 'store',
  -- Stock at this location counts towards what the storefront can sell.
  sells_online        boolean not null default false,
  -- Lower is tried first when an online order picks where to fulfil from.
  fulfilment_priority int not null default 100,
  is_active           boolean not null default true,
  address             jsonb not null default '{}'::jsonb,
  phone               text,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  unique (organization_id, code),
  unique (organization_id, id)
);

-- ---------------------------------------------------------------------------
-- Audit log (append-only)
-- ---------------------------------------------------------------------------

create table public.audit_log (
  id              bigint generated always as identity primary key,
  organization_id uuid,
  table_name      text not null,
  row_id          text,
  action          text not null,
  old_data        jsonb,
  new_data        jsonb,
  actor_id        uuid default auth.uid(),
  created_at      timestamptz not null default now()
);
create index audit_log_org_idx on public.audit_log (organization_id, created_at desc);

-- ---------------------------------------------------------------------------
-- Generic trigger functions
-- ---------------------------------------------------------------------------

create or replace function public.touch_updated_at() returns trigger
language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end $$;

create or replace function public.prevent_mutation() returns trigger
language plpgsql as $$
begin
  raise exception using errcode = 'NC006', message = 'APPEND_ONLY',
    detail = format('%s rows can only be inserted', tg_table_name);
end $$;

create or replace function public.audit_row() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_old jsonb := case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) end;
  v_new jsonb := case when tg_op in ('INSERT','UPDATE') then to_jsonb(new) end;
  v_row jsonb := coalesce(v_new, v_old);
begin
  if tg_op = 'UPDATE' and v_old = v_new then
    return new;
  end if;
  insert into public.audit_log (organization_id, table_name, row_id, action, old_data, new_data)
  values (
    coalesce((v_row->>'organization_id')::uuid,
             case when tg_table_name = 'organizations' then (v_row->>'id')::uuid end),
    tg_table_name,
    coalesce(v_row->>'id', v_row->>'user_id', v_row->>'module'),
    lower(tg_op), v_old, v_new);
  return coalesce(new, old);
end $$;

create trigger audit_log_append_only before update or delete on public.audit_log
  for each row execute function public.prevent_mutation();

create trigger organizations_touch before update on public.organizations
  for each row execute function public.touch_updated_at();
create trigger memberships_touch before update on public.memberships
  for each row execute function public.touch_updated_at();
create trigger locations_touch before update on public.locations
  for each row execute function public.touch_updated_at();

create trigger organizations_audit after insert or update on public.organizations
  for each row execute function public.audit_row();
create trigger organization_modules_audit after insert or update or delete on public.organization_modules
  for each row execute function public.audit_row();
create trigger memberships_audit after insert or update or delete on public.memberships
  for each row execute function public.audit_row();
create trigger locations_audit after insert or update on public.locations
  for each row execute function public.audit_row();

-- ---------------------------------------------------------------------------
-- Identity, permission and module helpers
-- ---------------------------------------------------------------------------
-- Error codes raised by this schema (clients switch on these):
--   NC001 OUT_OF_STOCK        NC004 SERIAL_UNAVAILABLE
--   NC002 MODULE_DISABLED     NC005 NOT_FOUND
--   NC003 INVALID_INPUT       NC006 INVALID_STATE / APPEND_ONLY
--   42501 PERMISSION_DENIED

-- NWS itself: the service role (Edge Functions, provisioning scripts) or a
-- direct database session such as the Supabase SQL editor. A direct session
-- only counts while it carries no JWT role: every API request has one (anon at
-- least) and arrives as `authenticator`, so it can never pass as a direct session.
create or replace function public.is_platform_admin() returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce(auth.role() = 'service_role', false)
      or (auth.role() is null
          and (session_user = 'postgres'
               or coalesce((select r.rolsuper from pg_roles r where r.rolname = session_user), false)))
$$;

create or replace function public.role_permissions(p_role public.staff_role) returns text[]
language sql immutable as $$
  select case p_role
    when 'owner'        then array['*']
    when 'admin'        then array['*']
    when 'manager'      then array['catalog.view','catalog.manage','inventory.view','inventory.receive',
                                   'inventory.adjust','orders.view','orders.manage','pos.sell','pos.override',
                                   'customers.view','customers.manage','reports.view','locations.manage',
                                   'purchasing.manage','transfers.request','transfers.approve']
    when 'cashier'      then array['catalog.view','inventory.view','orders.view','pos.sell',
                                   'customers.view','customers.manage']
    when 'stock_keeper' then array['catalog.view','inventory.view','inventory.receive','inventory.adjust',
                                   'transfers.request']
    when 'viewer'       then array['catalog.view','inventory.view','orders.view','customers.view','reports.view']
  end
$$;

create or replace function public.is_member(p_org uuid) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select exists (
    select 1 from public.memberships m
     where m.organization_id = p_org and m.user_id = auth.uid() and m.is_active)
$$;

create or replace function public.has_permission(p_org uuid, p_permission text) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select public.is_platform_admin() or exists (
    select 1 from public.memberships m
     where m.organization_id = p_org and m.user_id = auth.uid() and m.is_active
       and public.role_permissions(m.role) && array['*', p_permission])
$$;

create or replace function public.has_location_access(p_org uuid, p_location uuid) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select public.is_platform_admin() or exists (
    select 1 from public.memberships m
     where m.organization_id = p_org and m.user_id = auth.uid() and m.is_active
       and (m.location_ids is null or p_location = any (m.location_ids)))
$$;

create or replace function public.assert_permission(p_org uuid, p_permission text) returns void
language plpgsql stable security definer set search_path = public, pg_temp as $$
begin
  if not public.has_permission(p_org, p_permission) then
    raise exception using errcode = '42501', message = 'PERMISSION_DENIED', detail = p_permission;
  end if;
end $$;

create or replace function public.assert_location_access(p_org uuid, p_location uuid) returns void
language plpgsql stable security definer set search_path = public, pg_temp as $$
begin
  if not public.has_location_access(p_org, p_location) then
    raise exception using errcode = '42501', message = 'PERMISSION_DENIED',
      detail = 'no access to this location';
  end if;
end $$;

create or replace function public.module_enabled(p_org uuid, p_module public.module_key) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select exists (
    select 1 from public.organization_modules om
     where om.organization_id = p_org and om.module = p_module and om.enabled)
$$;

create or replace function public.assert_module(p_org uuid, p_module public.module_key) returns void
language plpgsql stable security definer set search_path = public, pg_temp as $$
begin
  if not public.module_enabled(p_org, p_module) then
    raise exception using errcode = 'NC002', message = 'MODULE_DISABLED', detail = p_module::text;
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- Location rules: a second active location needs multi_location
-- ---------------------------------------------------------------------------

create or replace function public.locations_enforce_module() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if new.is_active and (tg_op = 'INSERT' or not old.is_active)
     and not public.module_enabled(new.organization_id, 'multi_location')
     and exists (select 1 from public.locations l
                  where l.organization_id = new.organization_id and l.is_active and l.id <> new.id) then
    raise exception using errcode = 'NC002', message = 'MODULE_DISABLED', detail = 'multi_location';
  end if;
  return new;
end $$;

create trigger locations_module_guard before insert or update of is_active on public.locations
  for each row execute function public.locations_enforce_module();

-- ---------------------------------------------------------------------------
-- Provisioning (NWS only)
-- ---------------------------------------------------------------------------

create or replace function public.apply_plan(p_organization_id uuid, p_plan text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_modules public.module_key[];
  v_addons  constant public.module_key[] := array['serial_tracking','batch_tracking','warranty']::public.module_key[];
begin
  if not public.is_platform_admin() then
    raise exception using errcode = '42501', message = 'PERMISSION_DENIED', detail = 'platform admin only';
  end if;
  select modules into v_modules from public.plans where code = p_plan;
  if v_modules is null then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = format('plan %s', p_plan);
  end if;

  insert into public.organization_modules (organization_id, module, enabled)
  select p_organization_id, m, true from unnest(v_modules) m
  on conflict (organization_id, module) do update set enabled = true, changed_at = now()
    where not public.organization_modules.enabled;

  -- Plan modules outside the new plan go off; vertical add-ons are left alone.
  update public.organization_modules
     set enabled = false, changed_at = now()
   where organization_id = p_organization_id and enabled
     and not (module = any (v_modules)) and not (module = any (v_addons));

  update public.organizations
     set settings = settings || jsonb_build_object('plan', p_plan)
   where id = p_organization_id;
end $$;

create or replace function public.set_organization_module(
  p_organization_id uuid, p_module public.module_key, p_enabled boolean) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if not public.is_platform_admin() then
    raise exception using errcode = '42501', message = 'PERMISSION_DENIED', detail = 'platform admin only';
  end if;
  insert into public.organization_modules (organization_id, module, enabled)
  values (p_organization_id, p_module, p_enabled)
  on conflict (organization_id, module) do update set enabled = excluded.enabled, changed_at = now();
end $$;

create or replace function public.create_organization(
  p_name          text,
  p_slug          text,
  p_owner_user_id uuid,
  p_plan          text default 'retail',
  p_currency_code text default 'LKR',
  p_location_name text default 'Main Store') returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_org uuid;
begin
  if not public.is_platform_admin() then
    raise exception using errcode = '42501', message = 'PERMISSION_DENIED', detail = 'platform admin only';
  end if;

  insert into public.organizations (name, slug, currency_code)
  values (p_name, p_slug, upper(p_currency_code))
  returning id into v_org;

  perform public.apply_plan(v_org, p_plan);

  if p_owner_user_id is not null then
    insert into public.memberships (organization_id, user_id, role)
    values (v_org, p_owner_user_id, 'owner');
  end if;

  insert into public.locations (organization_id, code, name, kind, sells_online, fulfilment_priority)
  values (v_org, 'MAIN', p_location_name, 'store', true, 10);

  return v_org;
end $$;

-- Owners and admins manage their own staff; nobody can grant 'owner' except NWS.
create or replace function public.upsert_staff_member(
  p_organization_id uuid,
  p_user_id         uuid,
  p_role            public.staff_role,
  p_location_ids    uuid[] default null,
  p_is_active       boolean default true) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  perform public.assert_permission(p_organization_id, 'staff.manage');
  if p_role = 'owner' and not public.is_platform_admin() then
    raise exception using errcode = '42501', message = 'PERMISSION_DENIED', detail = 'only NWS assigns owners';
  end if;
  if p_user_id = auth.uid() then
    raise exception using errcode = 'NC006', message = 'INVALID_STATE', detail = 'you cannot change your own membership';
  end if;
  if p_location_ids is not null and exists (
       select 1 from unnest(p_location_ids) l(id)
        where not exists (select 1 from public.locations x
                           where x.id = l.id and x.organization_id = p_organization_id)) then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'unknown location';
  end if;

  insert into public.memberships (organization_id, user_id, role, location_ids, is_active)
  values (p_organization_id, p_user_id, p_role, p_location_ids, p_is_active)
  on conflict (organization_id, user_id) do update
     set role = excluded.role, location_ids = excluded.location_ids, is_active = excluded.is_active;
end $$;

-- Public storefront identity for an organisation, without its settings.
create or replace function public.storefront_organization(p_slug text)
returns table (id uuid, name text, slug text, currency_code char(3), timezone text)
language sql stable security definer set search_path = public, pg_temp as $$
  select o.id, o.name, o.slug, o.currency_code, o.timezone
    from public.organizations o
   where o.slug = p_slug and (public.module_enabled(o.id, 'storefront') or public.module_enabled(o.id, 'mobile_app'))
$$;

-- ======================================================================
-- 0002_catalog.sql
-- ======================================================================
-- 0002_catalog.sql
-- Brands, categories, attribute definitions, products, options, variants, media.
-- The catalogue is vertical-neutral: a T-shirt (size x colour), a phone
-- (storage x colour, serial-tracked), a medicine (batch-tracked) and loose rice
-- (sold by the kg) are all the same shapes with different settings.

set check_function_bodies = off;

-- none   : counted stock only
-- serial : every unit has its own identifier (IMEI, serial, chassis no.) - module serial_tracking
-- batch  : stock is held in lots with optional expiry, sold first-expiry-first-out - module batch_tracking
create type public.tracking_mode as enum ('none', 'serial', 'batch');
create type public.product_status as enum ('draft', 'active', 'archived');
create type public.attribute_type as enum ('text', 'number', 'boolean', 'option');

create table public.brands (
  id              uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete cascade,
  name            text not null check (length(btrim(name)) > 0),
  slug            text not null check (slug ~ '^[a-z0-9][a-z0-9-]*$'),
  logo_path       text,
  is_active       boolean not null default true,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  unique (organization_id, slug),
  unique (organization_id, id)
);

create table public.categories (
  id              uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete cascade,
  parent_id       uuid,
  name            text not null check (length(btrim(name)) > 0),
  slug            text not null check (slug ~ '^[a-z0-9][a-z0-9-]*$'),
  description     text,
  position        int not null default 0,
  is_active       boolean not null default true,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  unique (organization_id, slug),
  unique (organization_id, id),
  foreign key (organization_id, parent_id) references public.categories (organization_id, id)
);

-- Structured specifications. A category lists which attributes apply to it,
-- which is what makes filtering and side-by-side comparison possible.
create table public.attribute_definitions (
  id              uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete cascade,
  code            text not null check (code ~ '^[a-z][a-z0-9_]*$'),
  label           text not null,
  data_type       public.attribute_type not null,
  unit            text,
  options         text[],
  is_filterable   boolean not null default false,
  created_at      timestamptz not null default now(),
  unique (organization_id, code),
  unique (organization_id, id),
  check ((data_type = 'option') = (options is not null and cardinality(options) > 0))
);

create table public.category_attributes (
  organization_id uuid not null,
  category_id     uuid not null,
  attribute_id    uuid not null,
  position        int not null default 0,
  is_required     boolean not null default false,
  primary key (category_id, attribute_id),
  foreign key (organization_id, category_id) references public.categories (organization_id, id) on delete cascade,
  foreign key (organization_id, attribute_id) references public.attribute_definitions (organization_id, id) on delete cascade
);

create table public.products (
  id               uuid primary key default gen_random_uuid(),
  organization_id  uuid not null references public.organizations(id) on delete cascade,
  name             text not null check (length(btrim(name)) > 0),
  slug             text not null check (slug ~ '^[a-z0-9][a-z0-9-]*$'),
  brand_id         uuid,
  category_id      uuid,
  summary          text,
  description      text,
  status           public.product_status not null default 'draft',
  tracking_mode    public.tracking_mode not null default 'none',
  -- The unit stock is counted and sold in: 'each', 'kg', 'm', 'l'...
  unit_of_measure  text not null default 'each',
  allow_fractional boolean not null default false,
  seo              jsonb not null default '{}'::jsonb,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (organization_id, slug),
  unique (organization_id, id),
  foreign key (organization_id, brand_id) references public.brands (organization_id, id),
  foreign key (organization_id, category_id) references public.categories (organization_id, id),
  check (not (tracking_mode = 'serial' and allow_fractional))
);
create index products_org_status_idx on public.products (organization_id, status);
create index products_category_idx on public.products (category_id);
create index products_brand_idx on public.products (brand_id);

create table public.product_options (
  id              uuid primary key default gen_random_uuid(),
  organization_id uuid not null,
  product_id      uuid not null,
  name            text not null check (length(btrim(name)) > 0),
  position        int not null default 0,
  unique (product_id, name),
  unique (organization_id, id),
  foreign key (organization_id, product_id) references public.products (organization_id, id) on delete cascade
);

create table public.product_option_values (
  id              uuid primary key default gen_random_uuid(),
  organization_id uuid not null,
  option_id       uuid not null,
  value           text not null check (length(btrim(value)) > 0),
  position        int not null default 0,
  unique (option_id, value),
  unique (organization_id, id),
  foreign key (organization_id, option_id) references public.product_options (organization_id, id) on delete cascade
);

create table public.product_variants (
  id               uuid primary key default gen_random_uuid(),
  organization_id  uuid not null,
  product_id       uuid not null,
  title            text not null default 'Default',
  sku              text,
  barcode          text,
  price            numeric(14,2) not null check (price >= 0),
  compare_at_price numeric(14,2) check (compare_at_price is null or compare_at_price > price),
  position         int not null default 0,
  is_active        boolean not null default true,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (organization_id, id),
  foreign key (organization_id, product_id) references public.products (organization_id, id) on delete cascade
);
create unique index product_variants_sku_uq on public.product_variants (organization_id, lower(sku)) where sku is not null;
create unique index product_variants_barcode_uq on public.product_variants (organization_id, barcode) where barcode is not null;
create index product_variants_product_idx on public.product_variants (product_id);

create table public.variant_option_values (
  organization_id uuid not null,
  variant_id      uuid not null,
  option_value_id uuid not null,
  primary key (variant_id, option_value_id),
  foreign key (organization_id, variant_id) references public.product_variants (organization_id, id) on delete cascade,
  foreign key (organization_id, option_value_id) references public.product_option_values (organization_id, id) on delete cascade
);

create table public.product_attribute_values (
  organization_id uuid not null,
  product_id      uuid not null,
  attribute_id    uuid not null,
  value           jsonb not null,
  primary key (product_id, attribute_id),
  foreign key (organization_id, product_id) references public.products (organization_id, id) on delete cascade,
  foreign key (organization_id, attribute_id) references public.attribute_definitions (organization_id, id) on delete cascade
);
create index product_attribute_values_filter_idx on public.product_attribute_values (attribute_id, value);

create table public.product_media (
  id              uuid primary key default gen_random_uuid(),
  organization_id uuid not null,
  product_id      uuid not null,
  variant_id      uuid,
  storage_path    text not null,
  alt_text        text,
  position        int not null default 0,
  created_at      timestamptz not null default now(),
  foreign key (organization_id, product_id) references public.products (organization_id, id) on delete cascade,
  foreign key (organization_id, variant_id) references public.product_variants (organization_id, id) on delete cascade
);
create index product_media_product_idx on public.product_media (product_id, position);

-- ---------------------------------------------------------------------------
-- Catalogue rules
-- ---------------------------------------------------------------------------

create or replace function public.categories_prevent_cycle() returns trigger
language plpgsql as $$
begin
  if new.parent_id is not null and exists (
    with recursive up(id, parent_id) as (
      select c.id, c.parent_id from public.categories c where c.id = new.parent_id
      union all
      select c.id, c.parent_id from public.categories c join up on c.id = up.parent_id)
    select 1 from up where up.id = new.id) then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'category cannot be its own ancestor';
  end if;
  return new;
end $$;

create trigger categories_cycle_guard before insert or update of parent_id on public.categories
  for each row execute function public.categories_prevent_cycle();

-- Serial and batch tracking are modules; and once stock has moved, the way a
-- product is counted is fixed, because the ledger was written in that shape.
create or replace function public.products_tracking_guard() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if new.tracking_mode = 'serial' then
    perform public.assert_module(new.organization_id, 'serial_tracking');
  elsif new.tracking_mode = 'batch' then
    perform public.assert_module(new.organization_id, 'batch_tracking');
  end if;

  if tg_op = 'UPDATE'
     and (new.tracking_mode is distinct from old.tracking_mode
          or new.allow_fractional is distinct from old.allow_fractional
          or new.unit_of_measure is distinct from old.unit_of_measure)
     and exists (select 1 from public.inventory_movements m
                   join public.product_variants v on v.id = m.variant_id
                  where v.product_id = new.id) then
    raise exception using errcode = 'NC006', message = 'INVALID_STATE',
      detail = 'tracking mode and unit cannot change after stock has moved';
  end if;
  return new;
end $$;

create trigger products_tracking_guard
  before insert or update of tracking_mode, allow_fractional, unit_of_measure on public.products
  for each row execute function public.products_tracking_guard();

create trigger brands_touch before update on public.brands for each row execute function public.touch_updated_at();
create trigger categories_touch before update on public.categories for each row execute function public.touch_updated_at();
create trigger products_touch before update on public.products for each row execute function public.touch_updated_at();
create trigger product_variants_touch before update on public.product_variants for each row execute function public.touch_updated_at();

-- Price and status changes are part of the audit trail.
create trigger products_audit after insert or update or delete on public.products
  for each row execute function public.audit_row();
create trigger product_variants_audit after insert or update or delete on public.product_variants
  for each row execute function public.audit_row();

-- ======================================================================
-- 0003_inventory.sql
-- ======================================================================
-- 0003_inventory.sql
-- One stock ledger for every channel and every location.
--
-- inventory_movements is the source of truth and is append-only. stock_levels
-- (and batch_stock) are the current position, changed ONLY by the trigger that
-- applies each movement, under a row lock, inside the same transaction. The
-- CHECK constraints make overselling impossible even for a buggy caller:
--   on_hand >= 0, reserved >= 0, reserved <= on_hand.

set check_function_bodies = off;

create type public.movement_type as enum (
  'receipt',          -- goods received (with or without a purchase order)
  'sale',             -- issued against an order, any channel
  'sale_return',      -- a customer return put back into stock
  'adjustment_in',    -- stock count found more
  'adjustment_out',   -- stock count found less / written off
  'damage',           -- damaged, expired, destroyed
  'transfer_out',
  'transfer_in'
);

create type public.reservation_status as enum ('active', 'consumed', 'released', 'expired');

create type public.serial_status as enum (
  'available', 'reserved', 'sold', 'in_transit', 'inspection',
  'damaged', 'written_off', 'returned_to_supplier'
);

-- ---------------------------------------------------------------------------
-- Current position
-- ---------------------------------------------------------------------------

create table public.stock_levels (
  organization_id     uuid not null,
  location_id         uuid not null,
  variant_id          uuid not null,
  on_hand             numeric(14,3) not null default 0,
  reserved            numeric(14,3) not null default 0,
  -- Weighted average cost of what is on hand; the cost of goods sold is taken
  -- from here at the moment of sale (serialised units carry their own cost).
  avg_unit_cost       numeric(14,4) not null default 0,
  low_stock_threshold numeric(14,3),
  updated_at          timestamptz not null default now(),
  primary key (location_id, variant_id),
  foreign key (organization_id, location_id) references public.locations (organization_id, id),
  foreign key (organization_id, variant_id) references public.product_variants (organization_id, id),
  constraint stock_levels_on_hand_nonneg check (on_hand >= 0),
  constraint stock_levels_reserved_valid check (reserved >= 0 and reserved <= on_hand)
);
create index stock_levels_variant_idx on public.stock_levels (variant_id);
create index stock_levels_org_idx on public.stock_levels (organization_id);

-- ---------------------------------------------------------------------------
-- Batch / lot module
-- ---------------------------------------------------------------------------

create table public.batches (
  id              uuid primary key default gen_random_uuid(),
  organization_id uuid not null,
  variant_id      uuid not null,
  lot_code        text not null check (length(btrim(lot_code)) > 0),
  expires_on      date,
  manufactured_on date,
  created_at      timestamptz not null default now(),
  unique (organization_id, variant_id, lot_code),
  unique (organization_id, id),
  foreign key (organization_id, variant_id) references public.product_variants (organization_id, id)
);

create table public.batch_stock (
  organization_id uuid not null,
  location_id     uuid not null,
  batch_id        uuid not null,
  on_hand         numeric(14,3) not null default 0,
  reserved        numeric(14,3) not null default 0,
  primary key (location_id, batch_id),
  foreign key (organization_id, location_id) references public.locations (organization_id, id),
  foreign key (organization_id, batch_id) references public.batches (organization_id, id),
  constraint batch_stock_on_hand_nonneg check (on_hand >= 0),
  constraint batch_stock_reserved_valid check (reserved >= 0 and reserved <= on_hand)
);

-- ---------------------------------------------------------------------------
-- Serial module (IMEI, serial number, chassis number...)
-- ---------------------------------------------------------------------------

create table public.serial_units (
  id              uuid primary key default gen_random_uuid(),
  organization_id uuid not null,
  variant_id      uuid not null,
  serial          text not null check (serial = btrim(serial) and length(serial) > 0),
  status          public.serial_status not null default 'available',
  location_id     uuid,
  unit_cost       numeric(14,4),
  -- clock_timestamp, not now(): units received in one delivery keep their scan
  -- order, so "oldest unit first" is deterministic.
  received_at     timestamptz not null default clock_timestamp(),
  updated_at      timestamptz not null default now(),
  unique (organization_id, variant_id, serial),
  unique (organization_id, id),
  foreign key (organization_id, variant_id) references public.product_variants (organization_id, id),
  foreign key (organization_id, location_id) references public.locations (organization_id, id)
);
create index serial_units_lookup_idx on public.serial_units (organization_id, upper(serial));
create index serial_units_pick_idx on public.serial_units (variant_id, location_id, status, received_at);

create trigger serial_units_touch before update on public.serial_units
  for each row execute function public.touch_updated_at();

-- ---------------------------------------------------------------------------
-- Stock receipts (goods in, independent of purchasing)
-- ---------------------------------------------------------------------------

create table public.stock_receipts (
  id              uuid primary key default gen_random_uuid(),
  organization_id uuid not null,
  location_id     uuid not null,
  number          text not null,
  reference       text,
  note            text,
  created_by      uuid default auth.uid(),
  created_at      timestamptz not null default now(),
  unique (organization_id, number),
  unique (organization_id, id),
  foreign key (organization_id, location_id) references public.locations (organization_id, id)
);

-- ---------------------------------------------------------------------------
-- The ledger
-- ---------------------------------------------------------------------------

create table public.inventory_movements (
  id              bigint generated always as identity primary key,
  organization_id uuid not null,
  location_id     uuid not null,
  variant_id      uuid not null,
  batch_id        uuid,
  serial_unit_id  uuid,
  movement_type   public.movement_type not null,
  quantity        numeric(14,3) not null check (quantity <> 0),
  unit_cost       numeric(14,4),
  source_type     text not null,
  source_id       uuid,
  note            text,
  created_by      uuid default auth.uid(),
  created_at      timestamptz not null default now(),
  foreign key (organization_id, location_id) references public.locations (organization_id, id),
  foreign key (organization_id, variant_id) references public.product_variants (organization_id, id),
  foreign key (organization_id, batch_id) references public.batches (organization_id, id),
  foreign key (organization_id, serial_unit_id) references public.serial_units (organization_id, id),
  check (
    (movement_type in ('receipt','sale_return','adjustment_in','transfer_in') and quantity > 0) or
    (movement_type in ('sale','adjustment_out','damage','transfer_out') and quantity < 0))
);
create index inventory_movements_stock_idx on public.inventory_movements (location_id, variant_id, created_at);
create index inventory_movements_source_idx on public.inventory_movements (source_type, source_id);
create index inventory_movements_serial_idx on public.inventory_movements (serial_unit_id) where serial_unit_id is not null;
create index inventory_movements_org_time_idx on public.inventory_movements (organization_id, created_at);

-- ---------------------------------------------------------------------------
-- Reservations (online checkouts, held sales, pickups)
-- ---------------------------------------------------------------------------

create table public.stock_reservations (
  id              uuid primary key default gen_random_uuid(),
  organization_id uuid not null,
  location_id     uuid not null,
  variant_id      uuid not null,
  batch_id        uuid,
  serial_unit_id  uuid,
  quantity        numeric(14,3) not null check (quantity > 0),
  status          public.reservation_status not null default 'active',
  expires_at      timestamptz,
  source_type     text not null,
  source_id       uuid not null,
  created_at      timestamptz not null default now(),
  closed_at       timestamptz,
  foreign key (organization_id, location_id) references public.locations (organization_id, id),
  foreign key (organization_id, variant_id) references public.product_variants (organization_id, id),
  foreign key (organization_id, batch_id) references public.batches (organization_id, id),
  foreign key (organization_id, serial_unit_id) references public.serial_units (organization_id, id)
);
create index stock_reservations_source_idx on public.stock_reservations (source_type, source_id);
create index stock_reservations_expiry_idx on public.stock_reservations (expires_at) where status = 'active';

-- ---------------------------------------------------------------------------
-- Applying a movement
-- ---------------------------------------------------------------------------
-- Lock order everywhere in this schema: stock_levels row first, then the
-- batch_stock / serial_units rows under it. Keeping one order is what keeps
-- concurrent sales from deadlocking each other.

create or replace function public.inventory_movement_apply() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_mode   public.tracking_mode;
  v_frac   boolean;
  v_level  public.stock_levels%rowtype;
  v_bstock public.batch_stock%rowtype;
begin
  select p.tracking_mode, p.allow_fractional into v_mode, v_frac
    from public.product_variants v
    join public.products p on p.id = v.product_id
   where v.id = new.variant_id and v.organization_id = new.organization_id;
  if not found then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'variant';
  end if;

  if not v_frac and new.quantity <> trunc(new.quantity) then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
      detail = 'this product is counted in whole units';
  end if;
  -- 'non_stock' (0014): services, fees and gift cards never have stock.
  if v_mode = 'non_stock' then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'this product is not stocked';
  end if;

  -- The shape of a movement must match how the product is tracked.
  if v_mode = 'serial' then
    if new.serial_unit_id is null or new.batch_id is not null or abs(new.quantity) <> 1 then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
        detail = 'serial-tracked stock moves one identified unit at a time';
    end if;
  elsif v_mode = 'batch' then
    if new.batch_id is null or new.serial_unit_id is not null then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
        detail = 'batch-tracked stock must name its batch';
    end if;
  elsif new.batch_id is not null or new.serial_unit_id is not null then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
      detail = 'this product is not serial- or batch-tracked';
  end if;

  insert into public.stock_levels (organization_id, location_id, variant_id)
  values (new.organization_id, new.location_id, new.variant_id)
  on conflict (location_id, variant_id) do nothing;

  -- FOR UPDATE waits for any concurrent sale of the same item and then reads
  -- the row as that sale left it, so the check below always sees the truth.
  select * into v_level from public.stock_levels
   where location_id = new.location_id and variant_id = new.variant_id
   for update;

  if v_level.on_hand + new.quantity < v_level.reserved then
    raise exception using errcode = 'NC001', message = 'OUT_OF_STOCK',
      detail = json_build_object('variant_id', new.variant_id, 'location_id', new.location_id,
                                 'available', v_level.on_hand - v_level.reserved,
                                 'requested', -new.quantity)::text;
  end if;

  if new.unit_cost is null then
    if new.serial_unit_id is not null then
      select unit_cost into new.unit_cost from public.serial_units where id = new.serial_unit_id;
    end if;
    new.unit_cost := coalesce(new.unit_cost, v_level.avg_unit_cost);
  end if;

  update public.stock_levels
     set on_hand = on_hand + new.quantity,
         avg_unit_cost = case
           when new.quantity > 0 and on_hand + new.quantity > 0
             then round((on_hand * avg_unit_cost + new.quantity * new.unit_cost) / (on_hand + new.quantity), 4)
           else avg_unit_cost end,
         updated_at = now()
   where location_id = new.location_id and variant_id = new.variant_id;

  if new.batch_id is not null then
    insert into public.batch_stock (organization_id, location_id, batch_id)
    values (new.organization_id, new.location_id, new.batch_id)
    on conflict (location_id, batch_id) do nothing;

    select * into v_bstock from public.batch_stock
     where location_id = new.location_id and batch_id = new.batch_id
     for update;

    if v_bstock.on_hand + new.quantity < v_bstock.reserved then
      raise exception using errcode = 'NC001', message = 'OUT_OF_STOCK',
        detail = json_build_object('variant_id', new.variant_id, 'batch_id', new.batch_id,
                                   'available', v_bstock.on_hand - v_bstock.reserved,
                                   'requested', -new.quantity)::text;
    end if;

    update public.batch_stock set on_hand = on_hand + new.quantity
     where location_id = new.location_id and batch_id = new.batch_id;
  end if;

  return new;
end $$;

create trigger inventory_movements_apply before insert on public.inventory_movements
  for each row execute function public.inventory_movement_apply();
create trigger inventory_movements_append_only before update or delete on public.inventory_movements
  for each row execute function public.prevent_mutation();

-- ======================================================================
-- 0004_stock_engine.sql
-- ======================================================================
-- 0004_stock_engine.sql
-- Internal building blocks used by every command that moves stock. None of
-- these are callable from the API (see 0007_security.sql); commands check
-- permissions and then call them.
--
-- Every function here locks the stock_levels row for (location, variant) before
-- touching batch_stock or serial_units rows, which is the schema-wide lock order.

set check_function_bodies = off;

create or replace function public._lock_stock_row(p_org uuid, p_location uuid, p_variant uuid)
returns public.stock_levels
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_level public.stock_levels%rowtype;
begin
  insert into public.stock_levels (organization_id, location_id, variant_id)
  values (p_org, p_location, p_variant)
  on conflict (location_id, variant_id) do nothing;

  select * into v_level from public.stock_levels
   where location_id = p_location and variant_id = p_variant
   for update;
  return v_level;
end $$;

create or replace function public._out_of_stock(p_variant uuid, p_location uuid, p_available numeric, p_requested numeric)
returns void
language plpgsql as $$
begin
  raise exception using errcode = 'NC001', message = 'OUT_OF_STOCK',
    detail = json_build_object('variant_id', p_variant, 'location_id', p_location,
                               'available', greatest(p_available, 0), 'requested', p_requested)::text;
end $$;

create or replace function public._tracking_mode(p_variant uuid) returns public.tracking_mode
language sql stable security definer set search_path = public, pg_temp as $$
  select p.tracking_mode from public.product_variants v
    join public.products p on p.id = v.product_id
   where v.id = p_variant
$$;

-- Batches that may be sold today, first expiry first. A batch expiring today
-- can still be sold today; an expired one only leaves through an adjustment.
create or replace function public._sellable_batch(p_expires_on date) returns boolean
language sql stable as $$
  select p_expires_on is null or p_expires_on >= current_date
$$;

-- ---------------------------------------------------------------------------
-- Reserve: hold stock for a source (an unpaid online order, a held sale)
-- ---------------------------------------------------------------------------
create or replace function public._reserve_line(
  p_org         uuid,
  p_location    uuid,
  p_variant     uuid,
  p_quantity    numeric,
  p_source_type text,
  p_source_id   uuid,
  p_expires_at  timestamptz,
  p_serials     text[] default null,
  p_lot_code    text default null) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_mode      public.tracking_mode := public._tracking_mode(p_variant);
  v_level     public.stock_levels%rowtype;
  v_units     uuid[];
  v_unit      uuid;
  v_remaining numeric := p_quantity;
  v_take      numeric;
  r           record;
begin
  if v_mode = 'non_stock' then return; end if;  -- nothing to hold
  v_level := public._lock_stock_row(p_org, p_location, p_variant);
  if v_level.on_hand - v_level.reserved < p_quantity then
    perform public._out_of_stock(p_variant, p_location, v_level.on_hand - v_level.reserved, p_quantity);
  end if;

  if v_mode = 'serial' then
    if p_serials is not null then
      select array_agg(id) into v_units from (
        select su.id from public.serial_units su
         where su.organization_id = p_org and su.variant_id = p_variant
           and su.location_id = p_location and su.status = 'available'
           and su.serial = any (p_serials)
         for update) s;
      if coalesce(cardinality(v_units), 0) <> cardinality(p_serials) then
        raise exception using errcode = 'NC004', message = 'SERIAL_UNAVAILABLE',
          detail = 'one or more of the given serial numbers is not available here';
      end if;
    else
      select array_agg(id) into v_units from (
        select su.id from public.serial_units su
         where su.organization_id = p_org and su.variant_id = p_variant
           and su.location_id = p_location and su.status = 'available'
         order by su.received_at, su.id
         limit p_quantity
         for update skip locked) s;
      if coalesce(cardinality(v_units), 0) < p_quantity then
        perform public._out_of_stock(p_variant, p_location, coalesce(cardinality(v_units), 0), p_quantity);
      end if;
    end if;

    update public.serial_units set status = 'reserved' where id = any (v_units);
    foreach v_unit in array v_units loop
      insert into public.stock_reservations
        (organization_id, location_id, variant_id, serial_unit_id, quantity, expires_at, source_type, source_id)
      values (p_org, p_location, p_variant, v_unit, 1, p_expires_at, p_source_type, p_source_id);
    end loop;

  elsif v_mode = 'batch' then
    for r in
      select bs.batch_id, bs.on_hand - bs.reserved as available
        from public.batch_stock bs
        join public.batches b on b.id = bs.batch_id
       where bs.location_id = p_location and b.variant_id = p_variant
         and bs.on_hand - bs.reserved > 0
         and public._sellable_batch(b.expires_on)
         and (p_lot_code is null or b.lot_code = p_lot_code)
       order by b.expires_on nulls last, b.created_at
       for update of bs
    loop
      exit when v_remaining <= 0;
      v_take := least(r.available, v_remaining);
      update public.batch_stock set reserved = reserved + v_take
       where location_id = p_location and batch_id = r.batch_id;
      insert into public.stock_reservations
        (organization_id, location_id, variant_id, batch_id, quantity, expires_at, source_type, source_id)
      values (p_org, p_location, p_variant, r.batch_id, v_take, p_expires_at, p_source_type, p_source_id);
      v_remaining := v_remaining - v_take;
    end loop;
    if v_remaining > 0 then
      perform public._out_of_stock(p_variant, p_location, p_quantity - v_remaining, p_quantity);
    end if;

  else
    insert into public.stock_reservations
      (organization_id, location_id, variant_id, quantity, expires_at, source_type, source_id)
    values (p_org, p_location, p_variant, p_quantity, p_expires_at, p_source_type, p_source_id);
  end if;

  update public.stock_levels set reserved = reserved + p_quantity, updated_at = now()
   where location_id = p_location and variant_id = p_variant;
end $$;

-- ---------------------------------------------------------------------------
-- Release: give a reservation back (cancelled, expired)
-- ---------------------------------------------------------------------------
create or replace function public._release_reservation(p_reservation_id uuid, p_final public.reservation_status)
returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  r public.stock_reservations%rowtype;
begin
  select * into r from public.stock_reservations where id = p_reservation_id;
  perform public._lock_stock_row(r.organization_id, r.location_id, r.variant_id);
  -- Re-read under the stock lock: a concurrent release may have beaten us.
  select * into r from public.stock_reservations where id = p_reservation_id for update;
  if r.status <> 'active' then
    return;
  end if;

  update public.stock_levels set reserved = reserved - r.quantity, updated_at = now()
   where location_id = r.location_id and variant_id = r.variant_id;
  if r.batch_id is not null then
    update public.batch_stock set reserved = reserved - r.quantity
     where location_id = r.location_id and batch_id = r.batch_id;
  end if;
  if r.serial_unit_id is not null then
    update public.serial_units set status = 'available'
     where id = r.serial_unit_id and status = 'reserved';
  end if;
  update public.stock_reservations set status = p_final, closed_at = now() where id = r.id;
end $$;

-- ---------------------------------------------------------------------------
-- Consume: turn every active reservation of a source into a stock issue
-- ---------------------------------------------------------------------------
create or replace function public._consume_reservations(
  p_source_type   text,
  p_source_id     uuid,
  p_movement_type public.movement_type) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  r public.stock_reservations%rowtype;
begin
  for r in
    select * from public.stock_reservations
     where source_type = p_source_type and source_id = p_source_id and status = 'active'
     order by location_id, variant_id, id
  loop
    perform public._lock_stock_row(r.organization_id, r.location_id, r.variant_id);
    -- Under the stock lock the reservation must still be live; callers hold the
    -- source (order) row lock, so this only fires if that rule is broken.
    if (select sr.status from public.stock_reservations sr where sr.id = r.id for update) <> 'active' then
      raise exception using errcode = 'NC006', message = 'INVALID_STATE', detail = 'reservation is no longer active';
    end if;

    update public.stock_levels set reserved = reserved - r.quantity
     where location_id = r.location_id and variant_id = r.variant_id;
    if r.batch_id is not null then
      update public.batch_stock set reserved = reserved - r.quantity
       where location_id = r.location_id and batch_id = r.batch_id;
    end if;
    if r.serial_unit_id is not null then
      update public.serial_units set status = 'sold' where id = r.serial_unit_id;
    end if;

    insert into public.inventory_movements
      (organization_id, location_id, variant_id, batch_id, serial_unit_id, movement_type, quantity, source_type, source_id)
    values (r.organization_id, r.location_id, r.variant_id, r.batch_id, r.serial_unit_id,
            p_movement_type, -r.quantity, p_source_type, p_source_id);

    update public.stock_reservations set status = 'consumed', closed_at = now() where id = r.id;
  end loop;
end $$;

-- ---------------------------------------------------------------------------
-- Issue: take stock out immediately (counter sale, write-off, damage)
-- Returns the serial units issued, if any.
-- ---------------------------------------------------------------------------
create or replace function public._issue_line(
  p_org           uuid,
  p_location      uuid,
  p_variant       uuid,
  p_quantity      numeric,
  p_movement_type public.movement_type,
  p_source_type   text,
  p_source_id     uuid,
  p_serials       text[] default null,
  p_lot_code      text default null,
  p_serial_final  public.serial_status default 'sold',
  p_note          text default null) returns uuid[]
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_mode      public.tracking_mode := public._tracking_mode(p_variant);
  v_level     public.stock_levels%rowtype;
  v_units     uuid[] := '{}';
  v_unit      uuid;
  v_remaining numeric := p_quantity;
  v_take      numeric;
  r           record;
begin
  if v_mode = 'non_stock' then return v_units; end if;  -- nothing leaves the shelf
  v_level := public._lock_stock_row(p_org, p_location, p_variant);
  if v_level.on_hand - v_level.reserved < p_quantity then
    perform public._out_of_stock(p_variant, p_location, v_level.on_hand - v_level.reserved, p_quantity);
  end if;

  if v_mode = 'serial' then
    if p_serials is null then
      select array_agg(id) into v_units from (
        select su.id from public.serial_units su
         where su.organization_id = p_org and su.variant_id = p_variant
           and su.location_id = p_location and su.status = 'available'
         order by su.received_at, su.id
         limit p_quantity
         for update skip locked) s;
    else
      -- Conditional update: two counters scanning the same unit cannot both win.
      with taken as (
        update public.serial_units su set status = p_serial_final
         where su.organization_id = p_org and su.variant_id = p_variant
           and su.location_id = p_location and su.status = 'available'
           and su.serial = any (p_serials)
        returning su.id)
      select array_agg(id) into v_units from taken;
      if coalesce(cardinality(v_units), 0) <> cardinality(p_serials) then
        raise exception using errcode = 'NC004', message = 'SERIAL_UNAVAILABLE',
          detail = 'one or more of the given serial numbers is not in stock here';
      end if;
    end if;
    if coalesce(cardinality(v_units), 0) < p_quantity then
      perform public._out_of_stock(p_variant, p_location, coalesce(cardinality(v_units), 0), p_quantity);
    end if;
    update public.serial_units set status = p_serial_final where id = any (v_units);

    foreach v_unit in array v_units loop
      insert into public.inventory_movements
        (organization_id, location_id, variant_id, serial_unit_id, movement_type, quantity, source_type, source_id, note)
      values (p_org, p_location, p_variant, v_unit, p_movement_type, -1, p_source_type, p_source_id, p_note);
    end loop;

  elsif v_mode = 'batch' then
    for r in
      select bs.batch_id, bs.on_hand - bs.reserved as available
        from public.batch_stock bs
        join public.batches b on b.id = bs.batch_id
       where bs.location_id = p_location and b.variant_id = p_variant
         and bs.on_hand - bs.reserved > 0
         -- Expired lots are never sold; a named expired lot can still be written off.
         and (public._sellable_batch(b.expires_on)
              or (p_lot_code is not null and p_movement_type <> 'sale'))
         and (p_lot_code is null or b.lot_code = p_lot_code)
       order by b.expires_on nulls last, b.created_at
       for update of bs
    loop
      exit when v_remaining <= 0;
      v_take := least(r.available, v_remaining);
      insert into public.inventory_movements
        (organization_id, location_id, variant_id, batch_id, movement_type, quantity, source_type, source_id, note)
      values (p_org, p_location, p_variant, r.batch_id, p_movement_type, -v_take, p_source_type, p_source_id, p_note);
      v_remaining := v_remaining - v_take;
    end loop;
    if v_remaining > 0 then
      perform public._out_of_stock(p_variant, p_location, p_quantity - v_remaining, p_quantity);
    end if;

  else
    insert into public.inventory_movements
      (organization_id, location_id, variant_id, movement_type, quantity, source_type, source_id, note)
    values (p_org, p_location, p_variant, p_movement_type, -p_quantity, p_source_type, p_source_id, p_note);
  end if;

  return v_units;
end $$;

-- ---------------------------------------------------------------------------
-- Stock in: receipts and positive adjustments
-- ---------------------------------------------------------------------------
create or replace function public._stock_in_line(
  p_org           uuid,
  p_location      uuid,
  p_variant       uuid,
  p_quantity      numeric,
  p_movement_type public.movement_type,
  p_unit_cost     numeric,
  p_source_type   text,
  p_source_id     uuid,
  p_serials       text[] default null,
  p_lot_code      text default null,
  p_expires_on    date default null,
  p_note          text default null) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_mode   public.tracking_mode := public._tracking_mode(p_variant);
  v_batch  public.batches%rowtype;
  v_serial text;
  v_unit   uuid;
begin
  if v_mode = 'non_stock' then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'this product is not stocked';
  end if;
  if v_mode = 'serial' then
    if p_serials is null or cardinality(p_serials) <> p_quantity then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
        detail = 'serial-tracked stock needs exactly one serial number per unit';
    end if;
    if (select count(distinct s) from unnest(p_serials) s) <> cardinality(p_serials) then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'duplicate serial numbers';
    end if;
    perform public._lock_stock_row(p_org, p_location, p_variant);
    foreach v_serial in array p_serials loop
      begin
        insert into public.serial_units (organization_id, variant_id, serial, status, location_id, unit_cost)
        values (p_org, p_variant, btrim(v_serial), 'available', p_location, p_unit_cost)
        returning id into v_unit;
      exception when unique_violation then
        raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
          detail = format('serial %s is already registered for this item', v_serial);
      end;
      insert into public.inventory_movements
        (organization_id, location_id, variant_id, serial_unit_id, movement_type, quantity, unit_cost, source_type, source_id, note)
      values (p_org, p_location, p_variant, v_unit, p_movement_type, 1, p_unit_cost, p_source_type, p_source_id, p_note);
    end loop;

  elsif v_mode = 'batch' then
    if p_lot_code is null or btrim(p_lot_code) = '' then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
        detail = 'batch-tracked stock needs a lot code';
    end if;
    insert into public.batches (organization_id, variant_id, lot_code, expires_on)
    values (p_org, p_variant, btrim(p_lot_code), p_expires_on)
    on conflict (organization_id, variant_id, lot_code) do nothing;
    select * into v_batch from public.batches
     where organization_id = p_org and variant_id = p_variant and lot_code = btrim(p_lot_code);
    if p_expires_on is not null and v_batch.expires_on is distinct from p_expires_on then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
        detail = format('lot %s is already recorded with expiry %s', v_batch.lot_code, v_batch.expires_on);
    end if;
    insert into public.inventory_movements
      (organization_id, location_id, variant_id, batch_id, movement_type, quantity, unit_cost, source_type, source_id, note)
    values (p_org, p_location, p_variant, v_batch.id, p_movement_type, p_quantity, p_unit_cost, p_source_type, p_source_id, p_note);

  else
    if p_serials is not null or p_lot_code is not null then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
        detail = 'this product is not serial- or batch-tracked';
    end if;
    insert into public.inventory_movements
      (organization_id, location_id, variant_id, movement_type, quantity, unit_cost, source_type, source_id, note)
    values (p_org, p_location, p_variant, p_movement_type, p_quantity, p_unit_cost, p_source_type, p_source_id, p_note);
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- Integrity: the current position must always equal what the ledger says
-- ---------------------------------------------------------------------------
create or replace function public._inventory_integrity(p_org uuid)
returns table (check_name text, location_id uuid, variant_id uuid, expected numeric, actual numeric)
language sql stable security definer set search_path = public, pg_temp as $$
  -- on_hand = sum of the ledger
  select 'on_hand_matches_ledger', s.location_id, s.variant_id,
         coalesce(m.total, 0), s.on_hand
    from public.stock_levels s
    left join (select im.location_id, im.variant_id, sum(im.quantity) total
                 from public.inventory_movements im where im.organization_id = p_org
                group by 1, 2) m using (location_id, variant_id)
   where s.organization_id = p_org and s.on_hand <> coalesce(m.total, 0)
  union all
  -- reserved = sum of active reservations
  select 'reserved_matches_reservations', s.location_id, s.variant_id,
         coalesce(r.total, 0), s.reserved
    from public.stock_levels s
    left join (select sr.location_id, sr.variant_id, sum(sr.quantity) total
                 from public.stock_reservations sr
                where sr.organization_id = p_org and sr.status = 'active'
                group by 1, 2) r using (location_id, variant_id)
   where s.organization_id = p_org and s.reserved <> coalesce(r.total, 0)
  union all
  -- batch-tracked: batch lots add up to the variant position
  select 'batches_match_variant', s.location_id, s.variant_id,
         coalesce(b.total, 0), s.on_hand
    from public.stock_levels s
    join public.product_variants v on v.id = s.variant_id
    join public.products p on p.id = v.product_id and p.tracking_mode = 'batch'
    left join (select bs.location_id, bt.variant_id, sum(bs.on_hand) total
                 from public.batch_stock bs join public.batches bt on bt.id = bs.batch_id
                where bs.organization_id = p_org group by 1, 2) b using (location_id, variant_id)
   where s.organization_id = p_org and s.on_hand <> coalesce(b.total, 0)
  union all
  -- serial-tracked: units physically here add up to the variant position
  select 'serials_match_variant', s.location_id, s.variant_id,
         coalesce(u.total, 0), s.on_hand
    from public.stock_levels s
    join public.product_variants v on v.id = s.variant_id
    join public.products p on p.id = v.product_id and p.tracking_mode = 'serial'
    left join (select su.location_id, su.variant_id, count(*)::numeric total
                 from public.serial_units su
                where su.organization_id = p_org and su.status in ('available','reserved')
                group by 1, 2) u using (location_id, variant_id)
   where s.organization_id = p_org and s.on_hand <> coalesce(u.total, 0)
$$;

-- ======================================================================
-- 0005_orders.sql
-- ======================================================================
-- 0005_orders.sql
-- Customers, document numbering and the single order model. A counter sale, an
-- online order, an app order, a phone order and an order keyed in by admin are
-- all rows in `orders`; only `channel` differs. That is what lets one customer
-- see every purchase and one report add up every channel.

set check_function_bodies = off;

create type public.sales_channel as enum ('online', 'pos', 'mobile_app', 'phone_order', 'admin_order');

create type public.order_status as enum (
  'pending_payment',  -- online: stock is reserved, waiting for the payment gateway
  'confirmed',        -- stock issued; payment captured or taken at the counter
  'completed',        -- handed over / delivered
  'cancelled',
  'expired',          -- the reservation lapsed before payment arrived
  'stock_conflict'    -- paid after the hold lapsed and the stock was gone: needs refund or backorder
);

-- ---------------------------------------------------------------------------
-- Customers (shared by storefront, POS and app)
-- ---------------------------------------------------------------------------

create table public.customers (
  id              uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete cascade,
  auth_user_id    uuid references auth.users(id) on delete set null,
  full_name       text,
  -- Stored normalised (+94771234567); counter staff look customers up by phone.
  phone           text check (phone is null or phone ~ '^\+[1-9][0-9]{6,14}$'),
  email           text check (email is null or email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
  notes           text,
  marketing_consent boolean not null default false,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  unique (organization_id, id)
);
create unique index customers_phone_uq on public.customers (organization_id, phone) where phone is not null;
create unique index customers_email_uq on public.customers (organization_id, lower(email)) where email is not null;
create unique index customers_auth_uq on public.customers (organization_id, auth_user_id) where auth_user_id is not null;

create trigger customers_touch before update on public.customers
  for each row execute function public.touch_updated_at();

-- ---------------------------------------------------------------------------
-- Gap-free document numbers
-- ---------------------------------------------------------------------------
-- A row per (organisation, document type, scope) incremented under a row lock.
-- Unlike a sequence, a rolled-back transaction gives its number back, so
-- invoice numbers have no holes.

create table public.document_sequences (
  organization_id uuid not null references public.organizations(id) on delete cascade,
  doc_type        text not null,
  scope           text not null default '',
  prefix          text not null,
  next_value      bigint not null default 1 check (next_value > 0),
  pad             int not null default 6,
  primary key (organization_id, doc_type, scope)
);

create or replace function public.next_document_number(
  p_org uuid, p_doc_type text, p_prefix text, p_scope text default '') returns text
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_value bigint;
  v_prefix text;
  v_pad int;
begin
  insert into public.document_sequences (organization_id, doc_type, scope, prefix)
  values (p_org, p_doc_type, p_scope, p_prefix)
  on conflict do nothing;

  update public.document_sequences
     set next_value = next_value + 1
   where organization_id = p_org and doc_type = p_doc_type and scope = p_scope
  returning next_value - 1, prefix, pad into v_value, v_prefix, v_pad;

  return v_prefix || lpad(v_value::text, v_pad, '0');
end $$;

-- ---------------------------------------------------------------------------
-- Orders
-- ---------------------------------------------------------------------------

create table public.orders (
  id                     uuid primary key default gen_random_uuid(),
  organization_id        uuid not null references public.organizations(id) on delete cascade,
  number                 text not null,
  channel                public.sales_channel not null,
  location_id            uuid not null,
  customer_id            uuid,
  status                 public.order_status not null,
  currency_code          char(3) not null,
  subtotal               numeric(14,2) not null default 0,
  discount_total         numeric(14,2) not null default 0,
  tax_total              numeric(14,2) not null default 0,
  total                  numeric(14,2) not null default 0,
  idempotency_key        text,
  reservation_expires_at timestamptz,
  note                   text,
  placed_by              uuid default auth.uid(),
  placed_at              timestamptz not null default now(),
  confirmed_at           timestamptz,
  cancelled_at           timestamptz,
  updated_at             timestamptz not null default now(),
  unique (organization_id, number),
  unique (organization_id, id),
  foreign key (organization_id, location_id) references public.locations (organization_id, id),
  foreign key (organization_id, customer_id) references public.customers (organization_id, id),
  check (total = subtotal - discount_total + tax_total)
);
create unique index orders_idempotency_uq on public.orders (organization_id, idempotency_key)
  where idempotency_key is not null;
create index orders_org_time_idx on public.orders (organization_id, placed_at desc);
create index orders_customer_idx on public.orders (customer_id, placed_at desc);
create index orders_channel_idx on public.orders (organization_id, channel, placed_at);

create trigger orders_touch before update on public.orders
  for each row execute function public.touch_updated_at();

create table public.order_lines (
  id              uuid primary key default gen_random_uuid(),
  organization_id uuid not null,
  order_id        uuid not null,
  variant_id      uuid not null,
  -- Snapshots: what the customer bought, as it was named and priced then.
  product_name    text not null,
  variant_title   text not null,
  sku             text,
  lot_code        text,
  quantity        numeric(14,3) not null check (quantity > 0),
  unit_price      numeric(14,2) not null check (unit_price >= 0),
  line_total      numeric(14,2) not null,
  position        int not null default 0,
  unique (organization_id, id),
  foreign key (organization_id, order_id) references public.orders (organization_id, id) on delete cascade,
  foreign key (organization_id, variant_id) references public.product_variants (organization_id, id)
);
create index order_lines_order_idx on public.order_lines (order_id, position);
create index order_lines_variant_idx on public.order_lines (variant_id);

-- Which identified units went out on which line (serial module).
create table public.order_line_units (
  organization_id uuid not null,
  order_line_id   uuid not null,
  serial_unit_id  uuid not null,
  primary key (order_line_id, serial_unit_id),
  foreign key (organization_id, order_line_id) references public.order_lines (organization_id, id) on delete cascade,
  foreign key (organization_id, serial_unit_id) references public.serial_units (organization_id, id)
);
create index order_line_units_serial_idx on public.order_line_units (serial_unit_id);

-- ======================================================================
-- 0006_commands.sql
-- ======================================================================
-- 0006_commands.sql
-- The API. Clients never write stock, orders or reservations directly; they
-- call these functions, which check permission, module and location access and
-- then do the whole job in one transaction.
--
-- Lock order: order row, then stock_levels rows in variant order, then
-- batch/serial rows. Every command below follows it.

set check_function_bodies = off;

-- ---------------------------------------------------------------------------
-- Line input: validate, merge duplicates, price from the catalogue
-- ---------------------------------------------------------------------------
-- Lines are [{variant_id, quantity, serials?: [...], lot_code?}]. Prices always
-- come from the catalogue; a client cannot propose one.
create or replace function public._order_input(p_org uuid, p_lines jsonb)
returns table (
  variant_id    uuid,
  lot_code      text,
  quantity      numeric,
  serials       text[],
  product_name  text,
  variant_title text,
  sku           text,
  unit_price    numeric,
  tracking_mode public.tracking_mode)
language plpgsql stable security definer set search_path = public, pg_temp as $$
#variable_conflict use_column
declare
  r record;
begin
  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'an order needs at least one line';
  end if;
  if exists (select 1 from jsonb_array_elements(p_lines) e
              where jsonb_typeof(e) <> 'object' or not (e ? 'variant_id') or not (e ? 'quantity')
                 or (e ? 'serials' and jsonb_typeof(e->'serials') <> 'array')) then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
      detail = 'each line needs variant_id and quantity; serials must be a list';
  end if;

  for r in
    with raw as (
      select (e->>'variant_id')::uuid                as variant_id,
             (e->>'quantity')::numeric               as quantity,
             nullif(btrim(e->>'lot_code'), '')       as lot_code,
             e->'serials'                            as serials
        from jsonb_array_elements(p_lines) e),
    grouped as (
      select g.variant_id, g.lot_code, sum(g.quantity) as quantity,
             bool_or(g.serials is not null)          as has_serials,
             (select array_agg(btrim(s))
                from raw r2 cross join lateral jsonb_array_elements_text(r2.serials) s
               where r2.variant_id = g.variant_id
                 and r2.lot_code is not distinct from g.lot_code) as serials
        from raw g
       group by g.variant_id, g.lot_code)
    select gr.*, v.organization_id as v_org, v.title, v.sku, v.price, v.is_active,
           p.name, p.status, p.tracking_mode, p.allow_fractional
      from grouped gr
      left join public.product_variants v on v.id = gr.variant_id
      left join public.products p on p.id = v.product_id
     order by gr.variant_id, gr.lot_code nulls first
  loop
    if r.v_org is distinct from p_org then
      raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = format('variant %s', r.variant_id);
    end if;
    if not r.is_active or r.status <> 'active' then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = format('%s is not for sale', r.name);
    end if;
    if r.quantity is null or r.quantity <= 0 then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'quantity must be positive';
    end if;
    if not r.allow_fractional and r.quantity <> trunc(r.quantity) then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
        detail = format('%s is sold in whole units', r.name);
    end if;
    if r.has_serials then
      if r.tracking_mode <> 'serial' then
        raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
          detail = format('%s is not serial-tracked', r.name);
      end if;
      if coalesce(cardinality(r.serials), 0) <> r.quantity
         or (select count(distinct s) from unnest(r.serials) s) <> cardinality(r.serials) then
        raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
          detail = format('%s needs one distinct serial number per unit', r.name);
      end if;
    end if;
    if r.lot_code is not null and r.tracking_mode <> 'batch' then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
        detail = format('%s is not batch-tracked', r.name);
    end if;

    variant_id    := r.variant_id;
    lot_code      := r.lot_code;
    quantity      := r.quantity;
    serials       := case when r.has_serials then r.serials end;
    product_name  := r.name;
    variant_title := r.title;
    sku           := r.sku;
    unit_price    := r.price;
    tracking_mode := r.tracking_mode;
    return next;
  end loop;
end $$;

create or replace function public._order_summary(p_order uuid) returns jsonb
language sql stable security definer set search_path = public, pg_temp as $$
  select jsonb_build_object(
    'order_id', o.id, 'number', o.number, 'status', o.status, 'channel', o.channel,
    'location_id', o.location_id, 'customer_id', o.customer_id,
    'currency_code', o.currency_code, 'subtotal', o.subtotal, 'total', o.total,
    'reservation_expires_at', o.reservation_expires_at,
    'lines', coalesce((
      select jsonb_agg(jsonb_build_object(
               'line_id', ol.id, 'variant_id', ol.variant_id, 'name', ol.product_name,
               'variant', ol.variant_title, 'quantity', ol.quantity,
               'unit_price', ol.unit_price, 'line_total', ol.line_total,
               'serials', (select jsonb_agg(su.serial order by su.serial)
                             from public.order_line_units u
                             join public.serial_units su on su.id = u.serial_unit_id
                            where u.order_line_id = ol.id))
             order by ol.position)
        from public.order_lines ol where ol.order_id = o.id), '[]'::jsonb))
  from public.orders o where o.id = p_order
$$;

create or replace function public._is_idempotency_clash(p_constraint text) returns boolean
language sql immutable as $$ select p_constraint = 'orders_idempotency_uq' $$;

-- ---------------------------------------------------------------------------
-- place_order: counter, phone and admin orders - stock leaves immediately
-- ---------------------------------------------------------------------------
create or replace function public.place_order(
  p_location_id     uuid,
  p_channel         public.sales_channel,
  p_lines           jsonb,
  p_customer_id     uuid default null,
  p_idempotency_key text default null,
  p_note            text default null) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
#variable_conflict use_column
declare
  v_org      uuid;
  v_currency char(3);
  v_order    uuid;
  v_line     uuid;
  v_units    uuid[];
  v_pos      int := 0;
  v_subtotal numeric := 0;
  v_constraint text;
  r          record;
begin
  select l.organization_id, o.currency_code into v_org, v_currency
    from public.locations l join public.organizations o on o.id = l.organization_id
   where l.id = p_location_id and l.is_active;
  if v_org is null then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'location';
  end if;

  if p_channel in ('online', 'mobile_app') then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
      detail = 'online and app orders go through start_checkout';
  elsif p_channel = 'pos' then
    perform public.assert_module(v_org, 'pos');
    perform public.assert_permission(v_org, 'pos.sell');
  else
    perform public.assert_permission(v_org, 'orders.manage');
  end if;
  perform public.assert_location_access(v_org, p_location_id);

  if p_idempotency_key is not null then
    select o.id into v_order from public.orders o
     where o.organization_id = v_org and o.idempotency_key = p_idempotency_key;
    if found then
      return public._order_summary(v_order) || '{"replayed": true}'::jsonb;
    end if;
  end if;

  if p_customer_id is not null and not exists (
       select 1 from public.customers c where c.id = p_customer_id and c.organization_id = v_org) then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'customer';
  end if;

  begin
    insert into public.orders
      (organization_id, number, channel, location_id, customer_id, status, currency_code,
       idempotency_key, note, confirmed_at)
    values
      (v_org, public.next_document_number(v_org, 'order', 'ORD-'), p_channel, p_location_id,
       p_customer_id, 'confirmed', v_currency, p_idempotency_key, p_note, now())
    returning id into v_order;
  exception when unique_violation then
    get stacked diagnostics v_constraint = constraint_name;
    if not public._is_idempotency_clash(v_constraint) then
      raise;
    end if;
    -- The same request is being placed concurrently and got there first.
    select o.id into v_order from public.orders o
     where o.organization_id = v_org and o.idempotency_key = p_idempotency_key;
    return public._order_summary(v_order) || '{"replayed": true}'::jsonb;
  end;

  for r in select * from public._order_input(v_org, p_lines) loop
    if p_channel = 'pos' and r.tracking_mode = 'serial' and r.serials is null then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
        detail = format('scan the serial number of each %s sold at the counter', r.product_name);
    end if;

    v_pos := v_pos + 1;
    insert into public.order_lines
      (organization_id, order_id, variant_id, product_name, variant_title, sku, lot_code,
       quantity, unit_price, line_total, position)
    values
      (v_org, v_order, r.variant_id, r.product_name, r.variant_title, r.sku, r.lot_code,
       r.quantity, r.unit_price, round(r.quantity * r.unit_price, 2), v_pos)
    returning id into v_line;

    v_units := public._issue_line(v_org, p_location_id, r.variant_id, r.quantity, 'sale',
                                  'order', v_order, r.serials, r.lot_code);
    if coalesce(cardinality(v_units), 0) > 0 then
      insert into public.order_line_units (organization_id, order_line_id, serial_unit_id)
      select v_org, v_line, u from unnest(v_units) u;
    end if;

    v_subtotal := v_subtotal + round(r.quantity * r.unit_price, 2);
  end loop;

  update public.orders set subtotal = v_subtotal, total = v_subtotal where id = v_order;
  return public._order_summary(v_order);
end $$;

-- ---------------------------------------------------------------------------
-- start_checkout: online / app orders - stock is held until payment arrives
-- ---------------------------------------------------------------------------
create or replace function public.start_checkout(
  p_organization_id uuid,
  p_lines           jsonb,
  p_idempotency_key text,
  p_channel         public.sales_channel default 'online',
  p_customer_id     uuid default null,
  p_note            text default null) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
#variable_conflict use_column
declare
  v_currency   char(3);
  v_settings   jsonb;
  v_customer   uuid;
  v_hold       int;
  v_max        numeric;
  v_expires    timestamptz;
  v_order      uuid;
  v_done       boolean := false;
  v_detail     text;
  v_constraint text;
  v_pos        int;
  v_subtotal   numeric;
  v_loc        record;
  r            record;
begin
  select o.currency_code, o.settings into v_currency, v_settings
    from public.organizations o where o.id = p_organization_id;
  if not found then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'organization';
  end if;

  if p_channel = 'online' then
    perform public.assert_module(p_organization_id, 'storefront');
  elsif p_channel = 'mobile_app' then
    perform public.assert_module(p_organization_id, 'mobile_app');
  else
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
      detail = 'counter, phone and admin orders go through place_order';
  end if;

  if p_idempotency_key is null or length(p_idempotency_key) < 8 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
      detail = 'an idempotency key of at least 8 characters is required';
  end if;

  select o.id into v_order from public.orders o
   where o.organization_id = p_organization_id and o.idempotency_key = p_idempotency_key;
  if found then
    return public._order_summary(v_order) || '{"replayed": true}'::jsonb;
  end if;

  -- Staff may place a checkout for a named customer; shoppers are themselves or a guest.
  if public.has_permission(p_organization_id, 'orders.manage') then
    v_customer := p_customer_id;
    if v_customer is not null and not exists (
         select 1 from public.customers c where c.id = v_customer and c.organization_id = p_organization_id) then
      raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'customer';
    end if;
  elsif p_customer_id is not null then
    raise exception using errcode = '42501', message = 'PERMISSION_DENIED',
      detail = 'shoppers cannot order on behalf of another customer';
  elsif auth.uid() is not null then
    select c.id into v_customer from public.customers c
     where c.organization_id = p_organization_id and c.auth_user_id = auth.uid();
  end if;

  if exists (select 1 from jsonb_array_elements(p_lines) e where e ? 'serials' or e ? 'lot_code') then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
      detail = 'online orders are allocated units and lots automatically';
  end if;

  v_hold := least(greatest(coalesce((v_settings->>'checkout_hold_minutes')::int, 15), 1), 120);
  v_max  := coalesce((v_settings->>'checkout_max_line_quantity')::numeric, 20);
  if exists (select 1 from public._order_input(p_organization_id, p_lines) i where i.quantity > v_max) then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
      detail = format('at most %s of one item per order', v_max);
  end if;
  v_expires := now() + make_interval(mins => v_hold);

  -- Fulfil from the first online location that can supply every line.
  for v_loc in
    select l.id from public.locations l
     where l.organization_id = p_organization_id and l.is_active and l.sells_online
     order by l.fulfilment_priority, l.code
  loop
    begin
      insert into public.orders
        (organization_id, number, channel, location_id, customer_id, status, currency_code,
         idempotency_key, reservation_expires_at, note)
      values
        (p_organization_id, public.next_document_number(p_organization_id, 'order', 'ORD-'), p_channel,
         v_loc.id, v_customer, 'pending_payment', v_currency, p_idempotency_key, v_expires, p_note)
      returning id into v_order;

      v_pos := 0;
      v_subtotal := 0;
      for r in select * from public._order_input(p_organization_id, p_lines) loop
        v_pos := v_pos + 1;
        insert into public.order_lines
          (organization_id, order_id, variant_id, product_name, variant_title, sku,
           quantity, unit_price, line_total, position)
        values
          (p_organization_id, v_order, r.variant_id, r.product_name, r.variant_title, r.sku,
           r.quantity, r.unit_price, round(r.quantity * r.unit_price, 2), v_pos);
        perform public._reserve_line(p_organization_id, v_loc.id, r.variant_id, r.quantity,
                                     'order', v_order, v_expires);
        v_subtotal := v_subtotal + round(r.quantity * r.unit_price, 2);
      end loop;

      update public.orders set subtotal = v_subtotal, total = v_subtotal where id = v_order;
      v_done := true;
      exit;
    exception
      when sqlstate 'NC001' or sqlstate 'NC004' then
        get stacked diagnostics v_detail = pg_exception_detail;
      when unique_violation then
        get stacked diagnostics v_constraint = constraint_name;
        if not public._is_idempotency_clash(v_constraint) then
          raise;
        end if;
        select o.id into v_order from public.orders o
         where o.organization_id = p_organization_id and o.idempotency_key = p_idempotency_key;
        return public._order_summary(v_order) || '{"replayed": true}'::jsonb;
    end;
  end loop;

  if not v_done then
    raise exception using errcode = 'NC001', message = 'OUT_OF_STOCK',
      detail = coalesce(v_detail, 'no location is set up to fulfil online orders');
  end if;

  return public._order_summary(v_order);
end $$;

-- ---------------------------------------------------------------------------
-- confirm_order: payment captured (gateway webhook) - reservations become sales
-- ---------------------------------------------------------------------------
create or replace function public.confirm_order(p_order_id uuid) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  o public.orders%rowtype;
  r record;
begin
  select * into o from public.orders where id = p_order_id for update;
  if not found then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'order';
  end if;
  perform public.assert_permission(o.organization_id, 'orders.manage');

  if o.status in ('confirmed', 'completed') then
    return public._order_summary(o.id) || '{"replayed": true}'::jsonb;
  elsif o.status = 'cancelled' then
    raise exception using errcode = 'NC006', message = 'INVALID_STATE', detail = 'order was cancelled';
  end if;

  -- The hold lapsed (or an earlier attempt hit a conflict): try to take the
  -- stock again now. If it has gone, park the order for a refund or backorder
  -- instead of overselling.
  if not exists (select 1 from public.stock_reservations sr
                  where sr.source_type = 'order' and sr.source_id = o.id and sr.status = 'active') then
    begin
      for r in
        select ol.variant_id, sum(ol.quantity) as quantity
          from public.order_lines ol where ol.order_id = o.id
         group by ol.variant_id order by ol.variant_id
      loop
        perform public._reserve_line(o.organization_id, o.location_id, r.variant_id, r.quantity,
                                     'order', o.id, null);
      end loop;
    exception when sqlstate 'NC001' or sqlstate 'NC004' then
      update public.orders set status = 'stock_conflict', reservation_expires_at = null where id = o.id;
      return public._order_summary(o.id);
    end;
  end if;

  perform public._consume_reservations('order', o.id, 'sale');

  insert into public.order_line_units (organization_id, order_line_id, serial_unit_id)
  select o.organization_id, ol.id, sr.serial_unit_id
    from public.stock_reservations sr
    join lateral (select l.id from public.order_lines l
                   where l.order_id = o.id and l.variant_id = sr.variant_id
                   order by l.position limit 1) ol on true
   where sr.source_type = 'order' and sr.source_id = o.id
     and sr.status = 'consumed' and sr.serial_unit_id is not null
  on conflict do nothing;

  update public.orders
     set status = 'confirmed', confirmed_at = now(), reservation_expires_at = null
   where id = o.id;
  return public._order_summary(o.id);
end $$;

-- ---------------------------------------------------------------------------
-- cancel_order: before payment - the held stock goes back on sale
-- ---------------------------------------------------------------------------
create or replace function public.cancel_order(p_order_id uuid, p_reason text default null) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  o public.orders%rowtype;
  r record;
begin
  select * into o from public.orders where id = p_order_id for update;
  if not found then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'order';
  end if;

  if not public.has_permission(o.organization_id, 'orders.manage') and not (
       o.status = 'pending_payment' and auth.uid() is not null and exists (
         select 1 from public.customers c where c.id = o.customer_id and c.auth_user_id = auth.uid())) then
    raise exception using errcode = '42501', message = 'PERMISSION_DENIED', detail = 'orders.manage';
  end if;

  if o.status = 'cancelled' then
    return public._order_summary(o.id) || '{"replayed": true}'::jsonb;
  elsif o.status not in ('pending_payment', 'expired', 'stock_conflict') then
    raise exception using errcode = 'NC006', message = 'INVALID_STATE',
      detail = 'a confirmed order is reversed through a return, not cancelled';
  end if;

  for r in
    select sr.id from public.stock_reservations sr
     where sr.source_type = 'order' and sr.source_id = o.id and sr.status = 'active'
     order by sr.location_id, sr.variant_id, sr.id
  loop
    perform public._release_reservation(r.id, 'released');
  end loop;

  update public.orders
     set status = 'cancelled', cancelled_at = now(), reservation_expires_at = null,
         note = case when p_reason is null then note
                     else concat_ws(E'\n', note, 'Cancelled: ' || p_reason) end
   where id = o.id;
  return public._order_summary(o.id);
end $$;

-- ---------------------------------------------------------------------------
-- expire_reservations: run every minute (pg_cron / scheduled Edge Function)
-- ---------------------------------------------------------------------------
create or replace function public.expire_reservations() returns int
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_order uuid;
  v_count int := 0;
  r record;
begin
  if not public.is_platform_admin() then
    raise exception using errcode = '42501', message = 'PERMISSION_DENIED', detail = 'platform admin only';
  end if;

  loop
    -- One order at a time, skipping any a payment confirmation is holding.
    select o.id into v_order from public.orders o
     where o.status = 'pending_payment' and o.reservation_expires_at < now()
     order by o.reservation_expires_at
     limit 1
     for update skip locked;
    exit when not found;

    for r in
      select sr.id from public.stock_reservations sr
       where sr.source_type = 'order' and sr.source_id = v_order and sr.status = 'active'
       order by sr.location_id, sr.variant_id, sr.id
    loop
      perform public._release_reservation(r.id, 'expired');
    end loop;
    update public.orders set status = 'expired' where id = v_order;
    v_count := v_count + 1;
  end loop;

  -- Holds from other sources (held counter sales, pickups) as they are added.
  for r in
    select sr.id from public.stock_reservations sr
     where sr.status = 'active' and sr.source_type <> 'order' and sr.expires_at < now()
     order by sr.location_id, sr.variant_id, sr.id
  loop
    perform public._release_reservation(r.id, 'expired');
  end loop;

  return v_count;
end $$;

-- ---------------------------------------------------------------------------
-- receive_stock: goods in
-- ---------------------------------------------------------------------------
-- Lines are [{variant_id, quantity, unit_cost?, serials?: [...], lot_code?, expires_on?}].
create or replace function public.receive_stock(
  p_location_id uuid,
  p_lines       jsonb,
  p_reference   text default null,
  p_note        text default null) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_org     uuid;
  v_receipt uuid;
  v_number  text;
  v_count   int := 0;
  e         jsonb;
begin
  select l.organization_id into v_org from public.locations l where l.id = p_location_id and l.is_active;
  if v_org is null then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'location';
  end if;
  perform public.assert_permission(v_org, 'inventory.receive');
  perform public.assert_location_access(v_org, p_location_id);

  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'nothing to receive';
  end if;

  v_number := public.next_document_number(v_org, 'receipt', 'RCV-');
  insert into public.stock_receipts (organization_id, location_id, number, reference, note)
  values (v_org, p_location_id, v_number, p_reference, p_note)
  returning id into v_receipt;

  for e in
    select x from jsonb_array_elements(p_lines) x order by x->>'variant_id'
  loop
    if not exists (select 1 from public.product_variants v
                    where v.id = (e->>'variant_id')::uuid and v.organization_id = v_org) then
      raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = format('variant %s', e->>'variant_id');
    end if;
    if coalesce((e->>'quantity')::numeric, 0) <= 0 or coalesce((e->>'unit_cost')::numeric, 0) < 0 then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
        detail = 'quantity must be positive and cost cannot be negative';
    end if;

    perform public._stock_in_line(
      v_org, p_location_id, (e->>'variant_id')::uuid, (e->>'quantity')::numeric, 'receipt',
      (e->>'unit_cost')::numeric, 'stock_receipt', v_receipt,
      case when e ? 'serials' then array(select jsonb_array_elements_text(e->'serials')) end,
      nullif(btrim(e->>'lot_code'), ''),
      (e->>'expires_on')::date);
    v_count := v_count + 1;
  end loop;

  return jsonb_build_object('receipt_id', v_receipt, 'number', v_number, 'lines', v_count);
end $$;

-- ---------------------------------------------------------------------------
-- adjust_stock: counts, write-offs, damage. Always positive quantity; the
-- reason gives the direction. A note is mandatory.
-- ---------------------------------------------------------------------------
create or replace function public.adjust_stock(
  p_location_id uuid,
  p_variant_id  uuid,
  p_quantity    numeric,
  p_reason      public.movement_type,
  p_note        text,
  p_serials     text[] default null,
  p_lot_code    text default null,
  p_expires_on  date default null,
  p_unit_cost   numeric default null) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_org  uuid;
  v_mode public.tracking_mode;
  v_id   uuid := gen_random_uuid();
begin
  select l.organization_id into v_org from public.locations l where l.id = p_location_id and l.is_active;
  if v_org is null then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'location';
  end if;
  perform public.assert_permission(v_org, 'inventory.adjust');
  perform public.assert_location_access(v_org, p_location_id);

  if not exists (select 1 from public.product_variants v where v.id = p_variant_id and v.organization_id = v_org) then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'variant';
  end if;
  if p_reason not in ('adjustment_in', 'adjustment_out', 'damage') then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
      detail = 'reason must be adjustment_in, adjustment_out or damage';
  end if;
  if p_quantity is null or p_quantity <= 0 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'quantity must be positive';
  end if;
  if p_note is null or length(btrim(p_note)) < 3 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'say why the stock is being adjusted';
  end if;

  v_mode := public._tracking_mode(p_variant_id);

  if p_reason = 'adjustment_in' then
    perform public._stock_in_line(v_org, p_location_id, p_variant_id, p_quantity, 'adjustment_in',
                                  p_unit_cost, 'adjustment', v_id, p_serials, p_lot_code, p_expires_on, p_note);
  else
    if v_mode = 'serial' and (p_serials is null or cardinality(p_serials) <> p_quantity) then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
        detail = 'name the serial number of each unit being removed';
    end if;
    if v_mode = 'batch' and p_lot_code is null then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'name the lot being removed';
    end if;
    perform public._issue_line(v_org, p_location_id, p_variant_id, p_quantity, p_reason, 'adjustment', v_id,
                               p_serials, p_lot_code,
                               case p_reason when 'damage' then 'damaged' else 'written_off' end::public.serial_status,
                               p_note);
  end if;

  return jsonb_build_object('adjustment_id', v_id);
end $$;

-- ---------------------------------------------------------------------------
-- lookup_serial: one box for IMEI / serial search, whichever channel sold it
-- ---------------------------------------------------------------------------
create or replace function public.lookup_serial(p_organization_id uuid, p_serial text) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
begin
  perform public.assert_module(p_organization_id, 'serial_tracking');
  if not (public.has_permission(p_organization_id, 'orders.view')
          or public.has_permission(p_organization_id, 'inventory.view')) then
    raise exception using errcode = '42501', message = 'PERMISSION_DENIED', detail = 'orders.view';
  end if;

  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'serial_unit_id', su.id,
      'serial',         su.serial,
      'status',         su.status,
      'product',        p.name,
      'variant',        v.title,
      'sku',            v.sku,
      'location',       l.name,
      'received_at',    su.received_at,
      'sale', (
        select jsonb_build_object(
          'order_id', o.id, 'number', o.number, 'channel', o.channel,
          'placed_at', o.placed_at, 'confirmed_at', o.confirmed_at, 'location', ol.name,
          'customer', case when c.id is null then null
                           else jsonb_build_object('id', c.id, 'name', c.full_name, 'phone', c.phone) end)
          from public.order_line_units olu
          join public.order_lines ln on ln.id = olu.order_line_id
          join public.orders o on o.id = ln.order_id
          join public.locations ol on ol.id = o.location_id
          left join public.customers c on c.id = o.customer_id
         where olu.serial_unit_id = su.id
         order by o.placed_at desc
         limit 1),
      'history', (
        select jsonb_agg(jsonb_build_object('type', m.movement_type, 'quantity', m.quantity,
                                            'at', m.created_at, 'source_type', m.source_type,
                                            'source_id', m.source_id) order by m.id)
          from public.inventory_movements m where m.serial_unit_id = su.id))
      order by su.received_at desc)
      from public.serial_units su
      join public.product_variants v on v.id = su.variant_id
      join public.products p on p.id = v.product_id
      left join public.locations l on l.id = su.location_id
     where su.organization_id = p_organization_id
       and upper(su.serial) = upper(btrim(p_serial))), '[]'::jsonb);
end $$;

-- ---------------------------------------------------------------------------
-- Storefront reads
-- ---------------------------------------------------------------------------
-- What the storefront may sell right now: stock at online locations, minus
-- holds, minus expired lots. Cost and location detail are not exposed.
create or replace function public.storefront_availability(p_organization_id uuid, p_variant_ids uuid[] default null)
returns table (variant_id uuid, available numeric)
language sql stable security definer set search_path = public, pg_temp as $$
  select v.id,
         case when p.tracking_mode = 'non_stock' then 999999
              when p.tracking_mode = 'batch' then
           coalesce((select sum(bs.on_hand - bs.reserved)
                       from public.batch_stock bs
                       join public.batches b on b.id = bs.batch_id
                       join public.locations l on l.id = bs.location_id
                      where b.variant_id = v.id and l.sells_online and l.is_active
                        and public._sellable_batch(b.expires_on)), 0)
         else
           coalesce((select sum(s.on_hand - s.reserved)
                       from public.stock_levels s
                       join public.locations l on l.id = s.location_id
                      where s.variant_id = v.id and l.sells_online and l.is_active), 0)
         end
    from public.product_variants v
    join public.products p on p.id = v.product_id
   where v.organization_id = p_organization_id
     and v.is_active and p.status = 'active'
     and (p_variant_ids is null or v.id = any (p_variant_ids))
$$;

create or replace function public.inventory_integrity_report(p_organization_id uuid)
returns table (check_name text, location_id uuid, variant_id uuid, expected numeric, actual numeric)
language plpgsql stable security definer set search_path = public, pg_temp as $$
begin
  perform public.assert_permission(p_organization_id, 'reports.view');
  return query select * from public._inventory_integrity(p_organization_id);
end $$;

-- ======================================================================
-- 0007_security.sql
-- ======================================================================
-- 0007_security.sql
-- Row-level security on every table, write access closed on everything the
-- commands own, and an explicit allowlist of callable functions.
--
-- Supabase grants ALL on new tables to anon/authenticated by default, so the
-- revokes below matter there; locally they document intent.

-- ---------------------------------------------------------------------------
-- Enable RLS everywhere
-- ---------------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array[
    'organizations','plans','organization_modules','memberships','locations','audit_log',
    'brands','categories','attribute_definitions','category_attributes','products',
    'product_options','product_option_values','product_variants','variant_option_values',
    'product_attribute_values','product_media',
    'stock_levels','batches','batch_stock','serial_units','stock_receipts','inventory_movements',
    'stock_reservations','customers','document_sequences','orders','order_lines','order_line_units']
  loop
    execute format('alter table public.%I enable row level security', t);
  end loop;
end $$;

-- ---------------------------------------------------------------------------
-- Table privileges
-- ---------------------------------------------------------------------------
grant usage on schema public to anon, authenticated, service_role;
grant all on all tables in schema public to service_role;
grant usage, select on all sequences in schema public to service_role;

-- Public catalogue and store info: anyone may read (RLS narrows to active rows).
grant select on public.plans, public.locations, public.brands, public.categories,
  public.attribute_definitions, public.category_attributes, public.products, public.product_options,
  public.product_option_values, public.product_variants, public.variant_option_values,
  public.product_attribute_values, public.product_media
  to anon, authenticated;

-- Staff-only reads.
grant select on public.organizations, public.organization_modules, public.memberships, public.audit_log,
  public.stock_levels, public.batches, public.batch_stock, public.serial_units, public.stock_receipts,
  public.inventory_movements, public.stock_reservations, public.customers, public.orders,
  public.order_lines, public.order_line_units
  to authenticated;

-- Direct writes are allowed only where the table is plain master data.
grant insert, update, delete on public.brands, public.categories, public.attribute_definitions,
  public.category_attributes, public.products, public.product_options, public.product_option_values,
  public.product_variants, public.variant_option_values, public.product_attribute_values,
  public.product_media
  to authenticated;
grant insert, update on public.locations, public.customers to authenticated;

-- Everything the commands own is closed to direct writes, whatever the defaults.
revoke insert, update, delete, truncate on public.organizations, public.plans, public.organization_modules,
  public.memberships, public.audit_log, public.stock_levels, public.batches, public.batch_stock,
  public.serial_units, public.stock_receipts, public.inventory_movements, public.stock_reservations,
  public.document_sequences, public.orders, public.order_lines, public.order_line_units
  from anon, authenticated;
revoke all on public.organizations, public.organization_modules, public.memberships, public.audit_log,
  public.stock_levels, public.batches, public.batch_stock, public.serial_units, public.stock_receipts,
  public.inventory_movements, public.stock_reservations, public.document_sequences, public.customers,
  public.orders, public.order_lines, public.order_line_units
  from anon;
revoke all on public.document_sequences from authenticated;

-- ---------------------------------------------------------------------------
-- Policies
-- ---------------------------------------------------------------------------

create policy plans_read on public.plans for select using (true);

create policy organizations_read on public.organizations for select
  using (public.is_member(id));

create policy organization_modules_read on public.organization_modules for select
  using (public.is_member(organization_id));

create policy memberships_read on public.memberships for select
  using (user_id = auth.uid() or public.has_permission(organization_id, 'staff.manage'));

create policy audit_log_read on public.audit_log for select
  using (public.has_permission(organization_id, 'audit.view'));

-- Locations double as the public store directory.
create policy locations_read on public.locations for select
  using (is_active or public.is_member(organization_id));
create policy locations_insert on public.locations for insert
  with check (public.has_permission(organization_id, 'locations.manage'));
create policy locations_update on public.locations for update
  using (public.has_permission(organization_id, 'locations.manage'))
  with check (public.has_permission(organization_id, 'locations.manage'));

-- Catalogue: shoppers see what is live, staff see everything, managers edit.
do $$
declare t text;
begin
  foreach t in array array['brands','categories'] loop
    execute format($f$
      create policy %1$s_read on public.%1$I for select
        using (is_active or public.is_member(organization_id))$f$, t);
  end loop;

  foreach t in array array['attribute_definitions','category_attributes'] loop
    execute format($f$
      create policy %1$s_read on public.%1$I for select using (true)$f$, t);
  end loop;

  foreach t in array array['brands','categories','attribute_definitions','category_attributes','products',
                           'product_options','product_option_values','product_variants',
                           'variant_option_values','product_attribute_values','product_media'] loop
    execute format($f$
      create policy %1$s_insert on public.%1$I for insert
        with check (public.has_permission(organization_id, 'catalog.manage'))$f$, t);
    execute format($f$
      create policy %1$s_update on public.%1$I for update
        using (public.has_permission(organization_id, 'catalog.manage'))
        with check (public.has_permission(organization_id, 'catalog.manage'))$f$, t);
    execute format($f$
      create policy %1$s_delete on public.%1$I for delete
        using (public.has_permission(organization_id, 'catalog.manage'))$f$, t);
  end loop;
end $$;

create policy products_read on public.products for select
  using (status = 'active' or public.is_member(organization_id));

create policy product_variants_read on public.product_variants for select
  using (public.is_member(organization_id) or (is_active and exists (
    select 1 from public.products p where p.id = product_id and p.status = 'active')));

create policy product_options_read on public.product_options for select
  using (public.is_member(organization_id) or exists (
    select 1 from public.products p where p.id = product_id and p.status = 'active'));

create policy product_option_values_read on public.product_option_values for select
  using (public.is_member(organization_id) or exists (
    select 1 from public.product_options o join public.products p on p.id = o.product_id
     where o.id = option_id and p.status = 'active'));

create policy variant_option_values_read on public.variant_option_values for select
  using (public.is_member(organization_id) or exists (
    select 1 from public.product_variants v join public.products p on p.id = v.product_id
     where v.id = variant_id and v.is_active and p.status = 'active'));

create policy product_attribute_values_read on public.product_attribute_values for select
  using (public.is_member(organization_id) or exists (
    select 1 from public.products p where p.id = product_id and p.status = 'active'));

create policy product_media_read on public.product_media for select
  using (public.is_member(organization_id) or exists (
    select 1 from public.products p where p.id = product_id and p.status = 'active'));

-- Stock: readable by staff with inventory.view, writable by nobody.
do $$
declare t text;
begin
  foreach t in array array['stock_levels','batches','batch_stock','serial_units','stock_receipts',
                           'inventory_movements','stock_reservations'] loop
    execute format($f$
      create policy %1$s_read on public.%1$I for select
        using (public.has_permission(organization_id, 'inventory.view'))$f$, t);
  end loop;
end $$;

-- Customers: themselves, or staff.
create policy customers_read on public.customers for select
  using ((auth_user_id is not null and auth_user_id = auth.uid())
         or public.has_permission(organization_id, 'customers.view'));
create policy customers_insert on public.customers for insert
  with check (public.has_permission(organization_id, 'customers.manage'));
create policy customers_update on public.customers for update
  using (public.has_permission(organization_id, 'customers.manage'))
  with check (public.has_permission(organization_id, 'customers.manage'));

-- Orders: staff with orders.view, or the customer the order belongs to.
create or replace function public.owns_order(p_order uuid) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select auth.uid() is not null and exists (
    select 1 from public.orders o join public.customers c on c.id = o.customer_id
     where o.id = p_order and c.auth_user_id = auth.uid())
$$;

create policy orders_read on public.orders for select
  using (public.has_permission(organization_id, 'orders.view') or public.owns_order(id));
create policy order_lines_read on public.order_lines for select
  using (public.has_permission(organization_id, 'orders.view') or public.owns_order(order_id));
create policy order_line_units_read on public.order_line_units for select
  using (public.has_permission(organization_id, 'orders.view') or exists (
    select 1 from public.order_lines ol where ol.id = order_line_id and public.owns_order(ol.order_id)));

-- document_sequences: no policy at all, so no API access.

-- ---------------------------------------------------------------------------
-- Function privileges: closed by default, explicit allowlist
-- ---------------------------------------------------------------------------
-- PostgreSQL grants EXECUTE to PUBLIC on every new function and anon /
-- authenticated inherit it, so PUBLIC is the grant that has to go.
revoke execute on all functions in schema public from public, anon, authenticated;
alter default privileges in schema public revoke execute on functions from public;
grant execute on all functions in schema public to service_role;

-- Used inside RLS policies, so every API role must be able to call them.
grant execute on function
  public.is_platform_admin(), public.role_permissions(public.staff_role), public.is_member(uuid),
  public.has_permission(uuid, text), public.has_location_access(uuid, uuid),
  public.module_enabled(uuid, public.module_key), public.owns_order(uuid)
  to anon, authenticated;

-- Storefront (guests and signed-in shoppers).
grant execute on function
  public.storefront_organization(text),
  public.storefront_availability(uuid, uuid[]),
  public.start_checkout(uuid, jsonb, text, public.sales_channel, uuid, text)
  to anon, authenticated;

-- Signed-in users (staff commands check their own permissions).
grant execute on function
  public.cancel_order(uuid, text),
  public.place_order(uuid, public.sales_channel, jsonb, uuid, text, text),
  public.confirm_order(uuid),
  public.receive_stock(uuid, jsonb, text, text),
  public.adjust_stock(uuid, uuid, numeric, public.movement_type, text, text[], text, date, numeric),
  public.lookup_serial(uuid, text),
  public.inventory_integrity_report(uuid),
  public.upsert_staff_member(uuid, uuid, public.staff_role, uuid[], boolean)
  to authenticated;

-- create_organization, apply_plan, set_organization_module, expire_reservations:
-- service_role only (granted above).

-- ---------------------------------------------------------------------------
-- Realtime: staff screens (POS, stock views) follow stock and order changes.
-- Realtime applies the same RLS, so shoppers receive nothing from these.
-- ---------------------------------------------------------------------------
alter publication supabase_realtime add table public.stock_levels, public.orders;

-- ======================================================================
-- 0008_money.sql
-- ======================================================================
-- 0008_money.sql
-- Phase 2: tax, manual discounts with manager approval, payments (split tender,
-- cash change, pay-later, gateway webhooks), refunds and store credit.
--
-- New error codes:
--   NC007 PAYMENT_INCOMPLETE / INSUFFICIENT_STORE_CREDIT
--   NC008 APPROVAL_REQUIRED

set check_function_bodies = off;

create extension if not exists pgcrypto with schema extensions;

-- ---------------------------------------------------------------------------
-- Tax
-- ---------------------------------------------------------------------------

create table public.tax_rates (
  id              uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete cascade,
  code            text not null check (code ~ '^[A-Z0-9][A-Z0-9_-]{0,15}$'),
  name            text not null,
  rate_percent    numeric(6,3) not null check (rate_percent >= 0 and rate_percent <= 100),
  is_default      boolean not null default false,
  is_active       boolean not null default true,
  created_at      timestamptz not null default now(),
  unique (organization_id, code),
  unique (organization_id, id)
);
create unique index tax_rates_one_default on public.tax_rates (organization_id) where is_default;

create trigger tax_rates_audit after insert or update or delete on public.tax_rates
  for each row execute function public.audit_row();

-- Retail shelf prices usually include tax; some B2B setups quote without it.
alter table public.organizations add column prices_include_tax boolean not null default true;

-- A product uses its own rate, else the organisation default; exempt means none.
alter table public.products
  add column tax_rate_id uuid,
  add column tax_exempt  boolean not null default false,
  add foreign key (organization_id, tax_rate_id) references public.tax_rates (organization_id, id);

-- ---------------------------------------------------------------------------
-- Order money columns
-- ---------------------------------------------------------------------------

create type public.payment_state as enum ('unpaid', 'partially_paid', 'paid', 'partially_refunded', 'refunded');

alter table public.orders
  add column tax_inclusive   boolean not null default true,
  add column amount_paid     numeric(14,2) not null default 0,
  add column amount_refunded numeric(14,2) not null default 0,
  add column payment_status  public.payment_state not null default 'unpaid',
  drop constraint orders_check,
  add constraint orders_totals_valid check (
    total = subtotal - discount_total + case when tax_inclusive then 0 else tax_total end
    and subtotal >= 0 and discount_total >= 0 and tax_total >= 0 and total >= 0),
  add constraint orders_refund_valid check (amount_refunded >= 0 and amount_refunded <= amount_paid);

-- line_subtotal = quantity x unit price
-- line_total    = line_subtotal - discount_amount (+ tax_amount when prices exclude tax)
alter table public.order_lines
  add column line_subtotal   numeric(14,2),
  add column discount_amount numeric(14,2) not null default 0 check (discount_amount >= 0),
  add column tax_rate        numeric(6,3) not null default 0,
  add column tax_amount      numeric(14,2) not null default 0 check (tax_amount >= 0);
update public.order_lines set line_subtotal = line_total where line_subtotal is null;
alter table public.order_lines alter column line_subtotal set not null;

-- ---------------------------------------------------------------------------
-- Payments and refunds
-- ---------------------------------------------------------------------------

create type public.payment_method as enum (
  'cash', 'card', 'bank_transfer', 'qr', 'online_gateway', 'store_credit', 'cash_on_delivery');
create type public.payment_kind as enum ('payment', 'refund');
create type public.payment_status as enum ('pending', 'captured', 'failed', 'voided');

create table public.payments (
  id                 uuid primary key default gen_random_uuid(),
  organization_id    uuid not null,
  order_id           uuid not null,
  kind               public.payment_kind not null default 'payment',
  method             public.payment_method not null,
  status             public.payment_status not null default 'captured',
  amount             numeric(14,2) not null check (amount > 0),
  -- Cash only: what the customer handed over and what went back.
  tendered           numeric(14,2),
  change_given       numeric(14,2) check (change_given is null or change_given >= 0),
  provider           text,
  provider_reference text,
  payload            jsonb not null default '{}'::jsonb,
  note               text,
  created_by         uuid default auth.uid(),
  created_at         timestamptz not null default now(),
  captured_at        timestamptz,
  unique (organization_id, id),
  foreign key (organization_id, order_id) references public.orders (organization_id, id),
  check (method = 'cash' or (tendered is null and change_given is null))
);
create index payments_order_idx on public.payments (order_id, created_at);
create index payments_org_time_idx on public.payments (organization_id, created_at);
-- A gateway may call back more than once; the same reference is recorded once.
create unique index payments_provider_ref_uq on public.payments (organization_id, provider, kind, provider_reference)
  where provider is not null and provider_reference is not null;

create trigger payments_append_only before delete on public.payments
  for each row execute function public.prevent_mutation();

-- ---------------------------------------------------------------------------
-- Store credit (append-only ledger; balance kept on the customer under lock)
-- ---------------------------------------------------------------------------

alter table public.customers
  add column store_credit_balance numeric(14,2) not null default 0,
  add constraint customers_store_credit_nonneg check (store_credit_balance >= 0);

create table public.store_credit_ledger (
  id              bigint generated always as identity primary key,
  organization_id uuid not null,
  customer_id     uuid not null,
  amount          numeric(14,2) not null check (amount <> 0),
  reason          text not null,
  source_type     text not null,
  source_id       uuid,
  created_by      uuid default auth.uid(),
  created_at      timestamptz not null default now(),
  foreign key (organization_id, customer_id) references public.customers (organization_id, id)
);
create index store_credit_ledger_customer_idx on public.store_credit_ledger (customer_id, created_at);

create or replace function public.store_credit_apply() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_balance numeric;
begin
  select store_credit_balance into v_balance from public.customers
   where id = new.customer_id and organization_id = new.organization_id
   for update;
  if not found then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'customer';
  end if;
  if v_balance + new.amount < 0 then
    raise exception using errcode = 'NC007', message = 'INSUFFICIENT_STORE_CREDIT',
      detail = json_build_object('balance', v_balance, 'requested', -new.amount)::text;
  end if;
  update public.customers set store_credit_balance = store_credit_balance + new.amount
   where id = new.customer_id;
  return new;
end $$;

create trigger store_credit_ledger_apply before insert on public.store_credit_ledger
  for each row execute function public.store_credit_apply();
create trigger store_credit_ledger_append_only before update or delete on public.store_credit_ledger
  for each row execute function public.prevent_mutation();

-- ---------------------------------------------------------------------------
-- Manager overrides: PINs and one-time approvals
-- ---------------------------------------------------------------------------

create table public.staff_pins (
  organization_id uuid not null,
  user_id         uuid not null,
  pin_hash        text not null,
  failed_attempts int not null default 0,
  locked_until    timestamptz,
  updated_at      timestamptz not null default now(),
  primary key (organization_id, user_id),
  foreign key (organization_id, user_id) references public.memberships (organization_id, user_id) on delete cascade
);

create table public.approvals (
  id                   uuid primary key default gen_random_uuid(),
  organization_id      uuid not null references public.organizations(id) on delete cascade,
  purpose              text not null,
  approver_id          uuid not null,
  requested_by         uuid not null,
  max_discount_percent numeric(5,2) not null,
  expires_at           timestamptz not null,
  used_at              timestamptz,
  order_id             uuid,
  created_at           timestamptz not null default now()
);
create index approvals_org_idx on public.approvals (organization_id, created_at desc);

create or replace function public._member_has_permission(p_org uuid, p_user uuid, p_permission text) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select exists (
    select 1 from public.memberships m
     where m.organization_id = p_org and m.user_id = p_user and m.is_active
       and public.role_permissions(m.role) && array['*', p_permission])
$$;

-- The largest discount (percent of the order) a member may give on their own.
-- Configurable per organisation in settings.discount_limits: {"cashier": 5, ...}
create or replace function public._discount_limit(p_org uuid, p_user uuid) returns numeric
language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce(
    (select (o.settings->'discount_limits'->>m.role::text)::numeric
       from public.organizations o where o.id = p_org),
    case m.role when 'owner' then 100 when 'admin' then 100 when 'manager' then 50 else 0 end)
    from public.memberships m
   where m.organization_id = p_org and m.user_id = p_user and m.is_active
$$;

create or replace function public.set_my_pin(p_organization_id uuid, p_pin text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if not public.is_member(p_organization_id) then
    raise exception using errcode = '42501', message = 'PERMISSION_DENIED', detail = 'not a member';
  end if;
  if p_pin is null or p_pin !~ '^[0-9]{4,8}$' then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'a PIN is 4 to 8 digits';
  end if;
  insert into public.staff_pins (organization_id, user_id, pin_hash)
  values (p_organization_id, auth.uid(), extensions.crypt(p_pin, extensions.gen_salt('bf', 8)))
  on conflict (organization_id, user_id) do update
     set pin_hash = excluded.pin_hash, failed_attempts = 0, locked_until = null, updated_at = now();
end $$;

-- A cashier asks a manager to approve something at the till. Returns (rather
-- than raises) on failure, so wrong-PIN attempts are recorded and can lock.
create or replace function public.request_override(
  p_organization_id uuid,
  p_approver_id     uuid,
  p_pin             text,
  p_purpose         text default 'discount') returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_pin public.staff_pins%rowtype;
  v_id  uuid;
  v_max numeric;
begin
  if not (public.has_permission(p_organization_id, 'pos.sell')
          or public.has_permission(p_organization_id, 'orders.manage')) then
    raise exception using errcode = '42501', message = 'PERMISSION_DENIED', detail = 'pos.sell';
  end if;
  if p_approver_id = auth.uid() then
    return jsonb_build_object('approved', false, 'reason', 'self_approval');
  end if;
  if not public._member_has_permission(p_organization_id, p_approver_id, 'pos.override') then
    return jsonb_build_object('approved', false, 'reason', 'not_authorised');
  end if;

  select * into v_pin from public.staff_pins
   where organization_id = p_organization_id and user_id = p_approver_id
   for update;
  if not found then
    return jsonb_build_object('approved', false, 'reason', 'no_pin');
  end if;
  if v_pin.locked_until is not null and v_pin.locked_until > now() then
    return jsonb_build_object('approved', false, 'reason', 'locked', 'locked_until', v_pin.locked_until);
  end if;

  if p_pin is null or extensions.crypt(p_pin, v_pin.pin_hash) <> v_pin.pin_hash then
    update public.staff_pins
       set failed_attempts = case when failed_attempts + 1 >= 5 then 0 else failed_attempts + 1 end,
           locked_until    = case when failed_attempts + 1 >= 5 then now() + interval '15 minutes' end
     where organization_id = p_organization_id and user_id = p_approver_id;
    return jsonb_build_object('approved', false, 'reason', 'wrong_pin',
                              'attempts_left', greatest(4 - v_pin.failed_attempts, 0));
  end if;

  update public.staff_pins set failed_attempts = 0, locked_until = null
   where organization_id = p_organization_id and user_id = p_approver_id;

  v_max := coalesce(public._discount_limit(p_organization_id, p_approver_id), 0);
  insert into public.approvals (organization_id, purpose, approver_id, requested_by, max_discount_percent, expires_at)
  values (p_organization_id, p_purpose, p_approver_id, auth.uid(), v_max, now() + interval '5 minutes')
  returning id into v_id;

  return jsonb_build_object('approved', true, 'approval_id', v_id, 'max_discount_percent', v_max);
end $$;

-- ---------------------------------------------------------------------------
-- Pricing: discounts and tax, written onto the order lines
-- ---------------------------------------------------------------------------

-- {"type": "percent", "value": 10} or {"type": "amount", "value": 500}
create or replace function public._discount_amount(p_discount jsonb, p_base numeric) returns numeric
language plpgsql immutable as $$
declare
  v_value numeric;
begin
  if p_discount is null or p_discount = 'null'::jsonb then
    return 0;
  end if;
  v_value := (p_discount->>'value')::numeric;
  if p_discount->>'type' = 'percent' and v_value > 0 and v_value <= 100 then
    return round(p_base * v_value / 100, 2);
  elsif p_discount->>'type' = 'amount' and v_value > 0 and v_value <= p_base then
    return round(v_value, 2);
  end if;
  raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
    detail = 'a discount is {type: percent, value: 0-100} or {type: amount, value <= the amount it applies to}';
end $$;

drop function public._order_input(uuid, jsonb);

-- As in 0006, plus an optional per-line discount.
create or replace function public._order_input(p_org uuid, p_lines jsonb)
returns table (
  variant_id    uuid,
  lot_code      text,
  quantity      numeric,
  serials       text[],
  product_name  text,
  variant_title text,
  sku           text,
  unit_price    numeric,
  tracking_mode public.tracking_mode,
  discount      jsonb)
language plpgsql stable security definer set search_path = public, pg_temp as $$
#variable_conflict use_column
declare
  r record;
begin
  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'an order needs at least one line';
  end if;
  if exists (select 1 from jsonb_array_elements(p_lines) e
              where jsonb_typeof(e) <> 'object' or not (e ? 'variant_id') or not (e ? 'quantity')
                 or (e ? 'serials' and jsonb_typeof(e->'serials') <> 'array')
                 or (e ? 'discount' and jsonb_typeof(e->'discount') not in ('object', 'null'))) then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
      detail = 'each line needs variant_id and quantity; serials must be a list; discount an object';
  end if;

  for r in
    with raw as (
      select (e->>'variant_id')::uuid                as variant_id,
             (e->>'quantity')::numeric               as quantity,
             nullif(btrim(e->>'lot_code'), '')       as lot_code,
             e->'serials'                            as serials,
             nullif(e->'discount', 'null'::jsonb)    as discount
        from jsonb_array_elements(p_lines) e),
    grouped as (
      select g.variant_id, g.lot_code, sum(g.quantity) as quantity,
             bool_or(g.serials is not null)          as has_serials,
             (select array_agg(btrim(s))
                from raw r2 cross join lateral jsonb_array_elements_text(r2.serials) s
               where r2.variant_id = g.variant_id
                 and r2.lot_code is not distinct from g.lot_code) as serials,
             count(distinct g.discount)              as discount_variants,
             (array_agg(g.discount) filter (where g.discount is not null))[1] as discount
        from raw g
       group by g.variant_id, g.lot_code)
    select gr.*, v.organization_id as v_org, v.title, v.sku, v.price, v.is_active,
           p.name, p.status, p.tracking_mode, p.allow_fractional
      from grouped gr
      left join public.product_variants v on v.id = gr.variant_id
      left join public.products p on p.id = v.product_id
     order by gr.variant_id, gr.lot_code nulls first
  loop
    if r.v_org is distinct from p_org then
      raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = format('variant %s', r.variant_id);
    end if;
    if not r.is_active or r.status <> 'active' then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = format('%s is not for sale', r.name);
    end if;
    if r.quantity is null or r.quantity <= 0 then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'quantity must be positive';
    end if;
    if not r.allow_fractional and r.quantity <> trunc(r.quantity) then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
        detail = format('%s is sold in whole units', r.name);
    end if;
    if r.discount_variants > 1 then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
        detail = format('%s appears twice with different discounts', r.name);
    end if;
    if r.has_serials then
      if r.tracking_mode <> 'serial' then
        raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
          detail = format('%s is not serial-tracked', r.name);
      end if;
      if coalesce(cardinality(r.serials), 0) <> r.quantity
         or (select count(distinct s) from unnest(r.serials) s) <> cardinality(r.serials) then
        raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
          detail = format('%s needs one distinct serial number per unit', r.name);
      end if;
    end if;
    if r.lot_code is not null and r.tracking_mode <> 'batch' then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
        detail = format('%s is not batch-tracked', r.name);
    end if;

    variant_id    := r.variant_id;
    lot_code      := r.lot_code;
    quantity      := r.quantity;
    serials       := case when r.has_serials then r.serials end;
    product_name  := r.name;
    variant_title := r.title;
    sku           := r.sku;
    unit_price    := r.price;
    tracking_mode := r.tracking_mode;
    discount      := r.discount;
    return next;
  end loop;
end $$;

-- Prices the lines and writes lines and order totals:
--   * manual line discounts, or failing those the best live promotion for the line
--     (percent / amount / buy-X-get-Y on its product, category or brand)
--   * a manual order discount, or failing that the best order-level promotion
--     (with its minimum spend), spread across lines in proportion
--   * tax per line on what is left
-- Gift cards are money, not goods: no discount or promotion of any kind touches
-- them, and they count toward no minimum spend.
-- A coupon code, if any, arrives in the transaction setting nwsc.coupon (set by
-- quote_order / checkout / pos_quote / pos_sale). An unknown or expired code is
-- refused. Promotions used are recorded in order_promotions and counted against
-- their usage limits (under a row lock, so two tills cannot overshoot).
-- Returns the MANUAL discount as a percentage of the undiscounted subtotal:
-- promotions never count against a cashier's discount limit.
create or replace function public._write_order_lines(
  p_org             uuid,
  p_order           uuid,
  p_lines           jsonb,
  p_order_discount  jsonb,
  p_allow_discounts boolean) returns numeric
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_inclusive    boolean;
  v_channel      public.sales_channel;
  v_default_rate numeric;
  v_coupon       text := nullif(upper(btrim(coalesce(current_setting('nwsc.coupon', true), ''))), '');
  v_coupon_used  boolean := false;
  v_gross        numeric := 0;
  v_base         numeric := 0;   -- what order-level discounts apply to (gift cards left out)
  v_last         int := 0;       -- the last line that takes a share of the order discount
  v_gift         boolean[] := '{}';
  v_manual       numeric := 0;
  v_order_disc   numeric := 0;
  v_order_promo  uuid;
  v_alloc_left   numeric;
  v_count        int := 0;
  v_i            int := 0;
  v_sub          numeric;
  v_ldisc        numeric;
  v_promo        numeric;
  v_promo_id     uuid;
  v_net          numeric;
  v_alloc        numeric;
  v_rate         numeric;
  v_tax          numeric;
  v_total        numeric;
  v_disc_total   numeric := 0;
  v_promo_total  numeric := 0;
  v_tax_total    numeric := 0;
  v_grand        numeric := 0;
  v_used         jsonb := '{}'::jsonb;
  v_promo_ids    uuid[] := '{}';
  v_promos       numeric[] := '{}';
  r              record;
  pr             record;
begin
  select o.tax_inclusive, o.channel into v_inclusive, v_channel from public.orders o where o.id = p_order;
  select tr.rate_percent into v_default_rate from public.tax_rates tr
   where tr.organization_id = p_org and tr.is_default and tr.is_active;

  if not p_allow_discounts and (p_order_discount is not null
       or exists (select 1 from jsonb_array_elements(p_lines) e where nullif(e->'discount', 'null'::jsonb) is not null)) then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'discounts cannot be applied here';
  end if;
  if v_coupon is not null and not exists (select 1 from public._live_promotions(p_org, v_channel, v_coupon) lp where lp.coupon_code = v_coupon) then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'that code is not valid right now';
  end if;

  -- Pass 1: subtotal and what each line's discount (manual or promotion) leaves.
  for r in
    select i.*, p.id as product_id, p.category_id, p.brand_id, p.is_gift_card
      from public._order_input(p_org, p_lines) i
      join public.product_variants v on v.id = i.variant_id join public.products p on p.id = v.product_id
     order by i.variant_id, i.lot_code nulls first
  loop
    v_count := v_count + 1;
    if r.is_gift_card and r.discount is not null then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'a gift card cannot be discounted';
    end if;
    v_sub := round(r.quantity * r.unit_price, 2);
    v_ldisc := public._discount_amount(r.discount, v_sub);
    v_promo := 0; v_promo_id := null;
    if r.discount is null and not r.is_gift_card then
      select lp.id, least(case lp.kind
                when 'percent_off' then round(v_sub * lp.value / 100, 2)
                when 'amount_off'  then round(lp.value * r.quantity, 2)
                else floor(r.quantity / (lp.buy_quantity + lp.get_quantity)) * lp.get_quantity * r.unit_price end, v_sub)
        into v_promo_id, v_promo
        from public._live_promotions(p_org, v_channel, v_coupon) lp
       where lp.scope = 'products'
         and (cardinality(lp.product_ids) + cardinality(lp.category_ids) + cardinality(lp.brand_ids) = 0
              or r.product_id = any (lp.product_ids) or r.category_id = any (lp.category_ids) or r.brand_id = any (lp.brand_ids))
       order by 2 desc nulls last, lp.created_at
       limit 1;
      v_promo := coalesce(v_promo, 0);
      if v_promo = 0 then v_promo_id := null; end if;
    end if;
    v_promo_ids := v_promo_ids || v_promo_id;
    v_promos := v_promos || v_promo;
    v_gift := v_gift || r.is_gift_card;
    v_gross := v_gross + v_sub;
    v_manual := v_manual + v_ldisc;
    if not r.is_gift_card then
      v_base := v_base + v_sub - v_ldisc - v_promo;
      v_last := v_count;
    end if;
  end loop;

  -- Order-level: a manual discount wins; otherwise the best order promotion.
  if p_order_discount is not null then
    v_order_disc := public._discount_amount(p_order_discount, v_base);
    v_manual := v_manual + v_order_disc;
  else
    select lp.id, least(case lp.kind when 'percent_off' then round(v_base * lp.value / 100, 2) else lp.value end, v_base)
      into v_order_promo, v_order_disc
      from public._live_promotions(p_org, v_channel, v_coupon) lp
     where lp.scope = 'order' and v_base > 0 and v_base >= coalesce(lp.min_subtotal, 0)
     order by 2 desc, lp.created_at
     limit 1;
    v_order_disc := coalesce(v_order_disc, 0);
  end if;
  v_alloc_left := v_order_disc;

  -- Pass 2: write the lines.
  -- Same rows in the same order as pass 1 (_order_input sorts its output).
  for r in
    select i.*, p.tax_exempt, ptr.rate_percent as product_rate
      from public._order_input(p_org, p_lines) i
      join public.product_variants v on v.id = i.variant_id
      join public.products p on p.id = v.product_id
      left join public.tax_rates ptr on ptr.id = p.tax_rate_id and ptr.is_active
     order by i.variant_id, i.lot_code nulls first
  loop
    v_i := v_i + 1;
    v_promo_id := v_promo_ids[v_i];
    v_promo := v_promos[v_i];
    v_sub := round(r.quantity * r.unit_price, 2);
    v_ldisc := public._discount_amount(r.discount, v_sub) + v_promo;
    v_net := v_sub - v_ldisc;

    if v_gift[v_i] then
      v_alloc := 0;
    elsif v_i = v_last then
      v_alloc := least(v_alloc_left, v_net);
    elsif v_base > 0 then
      v_alloc := least(round(v_order_disc * v_net / v_base, 2), v_alloc_left, v_net);
    else
      v_alloc := 0;
    end if;
    v_alloc_left := v_alloc_left - v_alloc;
    v_net := v_net - v_alloc;

    v_rate := case when r.tax_exempt then 0 else coalesce(r.product_rate, v_default_rate, 0) end;
    if v_inclusive then
      v_tax := round(v_net - v_net / (1 + v_rate / 100), 2);
      v_total := v_net;
    else
      v_tax := round(v_net * v_rate / 100, 2);
      v_total := v_net + v_tax;
    end if;

    insert into public.order_lines
      (organization_id, order_id, variant_id, product_name, variant_title, sku, lot_code, quantity,
       unit_price, line_subtotal, discount_amount, promo_discount, tax_rate, tax_amount, line_total, position)
    values
      (p_org, p_order, r.variant_id, r.product_name, r.variant_title, r.sku, r.lot_code, r.quantity,
       r.unit_price, v_sub, v_ldisc + v_alloc, v_promo + case when v_order_promo is not null then v_alloc else 0 end,
       v_rate, v_tax, v_total, v_i);

    if v_promo_id is not null then
      v_used := jsonb_set(v_used, array[v_promo_id::text], to_jsonb(coalesce((v_used->>v_promo_id::text)::numeric, 0) + v_promo));
    end if;
    v_disc_total := v_disc_total + v_ldisc + v_alloc;
    v_promo_total := v_promo_total + v_promo + case when v_order_promo is not null then v_alloc else 0 end;
    v_tax_total := v_tax_total + v_tax;
    v_grand := v_grand + v_total;
  end loop;
  if v_order_promo is not null and v_order_disc > 0 then
    v_used := jsonb_set(v_used, array[v_order_promo::text], to_jsonb(coalesce((v_used->>v_order_promo::text)::numeric, 0) + v_order_disc));
  end if;

  -- Record and count the promotions used; a limit reached meanwhile refuses the order.
  for pr in select key::uuid as id, value::numeric as amount from jsonb_each_text(v_used) order by key loop
    update public.promotions set usage_count = usage_count + 1
     where id = pr.id and (usage_limit is null or usage_count < usage_limit);
    if not found then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'a promotion on this order has just run out - please try again';
    end if;
    insert into public.order_promotions (organization_id, order_id, promotion_id, amount) values (p_org, p_order, pr.id, pr.amount);
    if (select coupon_code from public.promotions where id = pr.id) = v_coupon then v_coupon_used := true; end if;
  end loop;

  update public.orders
     set subtotal = v_gross, discount_total = v_disc_total, tax_total = v_tax_total, total = v_grand,
         promo_discount_total = v_promo_total, coupon_code = case when v_coupon_used then v_coupon end
   where id = p_order;

  return case when v_gross > 0 then round(v_manual * 100 / v_gross, 2) else 0 end;
end $$;

-- ---------------------------------------------------------------------------
-- Payment bookkeeping
-- ---------------------------------------------------------------------------

-- Balance due is total - paid. A refund is money the shop gave back (goodwill,
-- a returned item, a cancelled order); it never puts the customer in debt.
create or replace function public._refresh_payment_status(p_order uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_paid     numeric;
  v_refunded numeric;
  v_total    numeric;
begin
  select coalesce(sum(p.amount) filter (where p.kind = 'payment'), 0),
         coalesce(sum(p.amount) filter (where p.kind = 'refund'), 0)
    into v_paid, v_refunded
    from public.payments p where p.order_id = p_order and p.status = 'captured';
  select o.total into v_total from public.orders o where o.id = p_order;

  update public.orders
     set amount_paid = v_paid,
         amount_refunded = v_refunded,
         payment_status = case
           when v_refunded > 0 and v_refunded >= v_paid then 'refunded'
           when v_refunded > 0 then 'partially_refunded'
           when v_paid >= v_total then 'paid'
           when v_paid > 0 then 'partially_paid'
           else 'unpaid' end::public.payment_state
   where id = p_order;
end $$;

-- Tenders at the counter: [{method, amount, reference?}]. Card, transfer, QR and
-- store credit may not exceed what is due; cash may, and the excess is change.
-- Returns the change to hand back.
create or replace function public._take_payments(
  p_org          uuid,
  p_order        uuid,
  p_payments     jsonb,
  p_require_full boolean) returns numeric
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  o             public.orders%rowtype;
  v_due         numeric;
  v_noncash     numeric;
  v_cash_given  numeric;
  v_cash_taken  numeric;
  e             jsonb;
begin
  select * into o from public.orders where id = p_order;
  v_due := o.total - o.amount_paid;

  if p_payments is null or p_payments = 'null'::jsonb then
    p_payments := '[]'::jsonb;
  end if;
  if jsonb_typeof(p_payments) <> 'array' or exists (
       select 1 from jsonb_array_elements(p_payments) x
        where jsonb_typeof(x) <> 'object'
           or coalesce(x->>'method', '') not in ('cash', 'card', 'bank_transfer', 'qr', 'store_credit')
           or coalesce((x->>'amount')::numeric, 0) <= 0) then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
      detail = 'payments are [{method: cash|card|bank_transfer|qr|store_credit, amount > 0}]';
  end if;

  select coalesce(sum((x->>'amount')::numeric) filter (where x->>'method' <> 'cash'), 0),
         coalesce(sum((x->>'amount')::numeric) filter (where x->>'method' = 'cash'), 0)
    into v_noncash, v_cash_given
    from jsonb_array_elements(p_payments) x;

  if v_noncash > v_due then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
      detail = 'card, transfer, QR and store credit cannot exceed the amount due';
  end if;
  v_cash_taken := least(v_cash_given, v_due - v_noncash);

  if p_require_full and v_noncash + v_cash_taken < v_due then
    raise exception using errcode = 'NC007', message = 'PAYMENT_INCOMPLETE',
      detail = json_build_object('due', v_due, 'tendered', v_noncash + v_cash_given)::text;
  end if;

  for e in select x from jsonb_array_elements(p_payments) x where x->>'method' <> 'cash' loop
    if e->>'method' = 'store_credit' then
      if o.customer_id is null then
        raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
          detail = 'store credit needs a customer on the order';
      end if;
      insert into public.store_credit_ledger (organization_id, customer_id, amount, reason, source_type, source_id)
      values (p_org, o.customer_id, -(e->>'amount')::numeric, 'Spent on order ' || o.number, 'order', o.id);
    end if;
    insert into public.payments (organization_id, order_id, method, amount, provider_reference, captured_at)
    values (p_org, o.id, (e->>'method')::public.payment_method, (e->>'amount')::numeric,
            nullif(e->>'reference', ''), now());
  end loop;

  if v_cash_taken > 0 then
    insert into public.payments (organization_id, order_id, method, amount, tendered, change_given, captured_at)
    values (p_org, o.id, 'cash', v_cash_taken, v_cash_given, v_cash_given - v_cash_taken, now());
  end if;

  perform public._refresh_payment_status(o.id);
  return v_cash_given - v_cash_taken;
end $$;

-- ---------------------------------------------------------------------------
-- Summary, now with money
-- ---------------------------------------------------------------------------
create or replace function public._order_summary(p_order uuid) returns jsonb
language sql stable security definer set search_path = public, pg_temp as $$
  select jsonb_build_object(
    'order_id', o.id, 'number', o.number, 'status', o.status, 'channel', o.channel,
    'location_id', o.location_id, 'customer_id', o.customer_id,
    'currency_code', o.currency_code, 'tax_inclusive', o.tax_inclusive,
    'subtotal', o.subtotal, 'discount_total', o.discount_total, 'tax_total', o.tax_total, 'total', o.total,
    'amount_paid', o.amount_paid, 'amount_refunded', o.amount_refunded,
    'balance_due', greatest(o.total - o.amount_paid, 0),
    'payment_status', o.payment_status,
    'reservation_expires_at', o.reservation_expires_at,
    'lines', coalesce((
      select jsonb_agg(jsonb_build_object(
               'line_id', ol.id, 'variant_id', ol.variant_id, 'name', ol.product_name,
               'variant', ol.variant_title, 'quantity', ol.quantity, 'unit_price', ol.unit_price,
               'line_subtotal', ol.line_subtotal, 'discount_amount', ol.discount_amount,
               'tax_rate', ol.tax_rate, 'tax_amount', ol.tax_amount, 'line_total', ol.line_total,
               'serials', (select jsonb_agg(su.serial order by su.serial)
                             from public.order_line_units u
                             join public.serial_units su on su.id = u.serial_unit_id
                            where u.order_line_id = ol.id))
             order by ol.position)
        from public.order_lines ol where ol.order_id = o.id), '[]'::jsonb),
    'payments', coalesce((
      select jsonb_agg(jsonb_build_object(
               'payment_id', p.id, 'kind', p.kind, 'method', p.method, 'status', p.status,
               'amount', p.amount, 'tendered', p.tendered, 'change_given', p.change_given,
               'provider', p.provider, 'reference', p.provider_reference, 'at', p.created_at)
             order by p.created_at, p.id)
        from public.payments p where p.order_id = o.id), '[]'::jsonb))
  from public.orders o where o.id = p_order
$$;

-- ---------------------------------------------------------------------------
-- place_order, now with discounts, approvals and payment
-- ---------------------------------------------------------------------------
drop function public.place_order(uuid, public.sales_channel, jsonb, uuid, text, text);

create or replace function public.place_order(
  p_location_id     uuid,
  p_channel         public.sales_channel,
  p_lines           jsonb,
  p_customer_id     uuid default null,
  p_idempotency_key text default null,
  p_note            text default null,
  p_payments        jsonb default null,
  p_order_discount  jsonb default null,
  p_approval_id     uuid default null) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
#variable_conflict use_column
declare
  v_org        uuid;
  v_currency   char(3);
  v_inclusive  boolean;
  v_order      uuid;
  v_units      uuid[];
  v_pct        numeric;
  v_limit      numeric;
  v_approved   numeric;
  v_change     numeric;
  v_constraint text;
  r            record;
begin
  select l.organization_id, o.currency_code, o.prices_include_tax into v_org, v_currency, v_inclusive
    from public.locations l join public.organizations o on o.id = l.organization_id
   where l.id = p_location_id and l.is_active;
  if v_org is null then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'location';
  end if;

  if p_channel in ('online', 'mobile_app') then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
      detail = 'online and app orders go through start_checkout';
  elsif p_channel = 'pos' then
    perform public.assert_module(v_org, 'pos');
    perform public.assert_permission(v_org, 'pos.sell');
    -- Counter sales are rung up on an open till shift so every rupee of cash is
    -- accounted for. pos_sale() marks its transaction; API clients cannot set
    -- this (set_config is not exposed), so they cannot skip the shift.
    if coalesce(current_setting('nwsc.pos_shift', true), '') = '' then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
        detail = 'counter sales are rung up on an open till shift (pos_sale)';
    end if;
  else
    perform public.assert_permission(v_org, 'orders.manage');
  end if;
  perform public.assert_location_access(v_org, p_location_id);

  if p_idempotency_key is not null then
    select o.id into v_order from public.orders o
     where o.organization_id = v_org and o.idempotency_key = p_idempotency_key;
    if found then
      return public._order_summary(v_order) || '{"replayed": true}'::jsonb;
    end if;
  end if;

  if p_customer_id is not null and not exists (
       select 1 from public.customers c where c.id = p_customer_id and c.organization_id = v_org) then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'customer';
  end if;

  begin
    insert into public.orders
      (organization_id, number, channel, location_id, customer_id, status, currency_code,
       tax_inclusive, idempotency_key, note, confirmed_at)
    values
      (v_org, public.next_document_number(v_org, 'order', 'ORD-'), p_channel, p_location_id,
       p_customer_id, 'confirmed', v_currency, v_inclusive, p_idempotency_key, p_note, now())
    returning id into v_order;
  exception when unique_violation then
    get stacked diagnostics v_constraint = constraint_name;
    if not public._is_idempotency_clash(v_constraint) then
      raise;
    end if;
    select o.id into v_order from public.orders o
     where o.organization_id = v_org and o.idempotency_key = p_idempotency_key;
    return public._order_summary(v_order) || '{"replayed": true}'::jsonb;
  end;

  v_pct := public._write_order_lines(v_org, v_order, p_lines, p_order_discount, true);

  -- A discount beyond the seller's own limit needs a manager's fresh approval.
  if v_pct > 0 and not public.is_platform_admin() then
    v_limit := coalesce(public._discount_limit(v_org, auth.uid()), 0);
    if v_pct > v_limit then
      update public.approvals a
         set used_at = now(), order_id = v_order
       where a.id = p_approval_id and a.organization_id = v_org and a.requested_by = auth.uid()
         and a.used_at is null and a.expires_at > now()
         and public._member_has_permission(v_org, a.approver_id, 'pos.override')
      returning a.max_discount_percent into v_approved;
      if v_approved is null or v_approved < v_pct then
        raise exception using errcode = 'NC008', message = 'APPROVAL_REQUIRED',
          detail = json_build_object('discount_percent', v_pct, 'your_limit', v_limit,
                                     'approved_up_to', v_approved)::text;
      end if;
    end if;
  end if;

  for r in
    select ol.id as line_id, ol.variant_id, ol.lot_code, ol.quantity, i.serials, i.tracking_mode, i.product_name
      from public.order_lines ol
      join public._order_input(v_org, p_lines) i
        on i.variant_id = ol.variant_id and i.lot_code is not distinct from ol.lot_code
     where ol.order_id = v_order
     order by ol.variant_id, ol.lot_code nulls first
  loop
    if p_channel = 'pos' and r.tracking_mode = 'serial' and r.serials is null then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
        detail = format('scan the serial number of each %s sold at the counter', r.product_name);
    end if;
    v_units := public._issue_line(v_org, p_location_id, r.variant_id, r.quantity, 'sale',
                                  'order', v_order, r.serials, r.lot_code);
    if coalesce(cardinality(v_units), 0) > 0 then
      insert into public.order_line_units (organization_id, order_line_id, serial_unit_id)
      select v_org, r.line_id, u from unnest(v_units) u;
    end if;
  end loop;

  -- The counter is paid in full before the customer leaves; phone and admin
  -- orders may be paid later (cash on delivery, invoice).
  v_change := public._take_payments(v_org, v_order, p_payments, p_channel = 'pos');
  perform public._after_confirm(v_order);  -- gift cards issued, points earned (0014)

  return public._order_summary(v_order) || jsonb_build_object('change_due', v_change);
end $$;

-- ---------------------------------------------------------------------------
-- start_checkout, now priced with tax (no manual discounts online)
-- ---------------------------------------------------------------------------
create or replace function public.start_checkout(
  p_organization_id uuid,
  p_lines           jsonb,
  p_idempotency_key text,
  p_channel         public.sales_channel default 'online',
  p_customer_id     uuid default null,
  p_note            text default null) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
#variable_conflict use_column
declare
  v_currency   char(3);
  v_inclusive  boolean;
  v_settings   jsonb;
  v_customer   uuid;
  v_hold       int;
  v_max        numeric;
  v_expires    timestamptz;
  v_order      uuid;
  v_done       boolean := false;
  v_detail     text;
  v_constraint text;
  v_loc        record;
  r            record;
begin
  select o.currency_code, o.settings, o.prices_include_tax into v_currency, v_settings, v_inclusive
    from public.organizations o where o.id = p_organization_id;
  if not found then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'organization';
  end if;

  if p_channel = 'online' then
    perform public.assert_module(p_organization_id, 'storefront');
  elsif p_channel = 'mobile_app' then
    perform public.assert_module(p_organization_id, 'mobile_app');
  else
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
      detail = 'counter, phone and admin orders go through place_order';
  end if;

  if p_idempotency_key is null or length(p_idempotency_key) < 8 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
      detail = 'an idempotency key of at least 8 characters is required';
  end if;

  select o.id into v_order from public.orders o
   where o.organization_id = p_organization_id and o.idempotency_key = p_idempotency_key;
  if found then
    return public._order_summary(v_order) || '{"replayed": true}'::jsonb;
  end if;

  if public.has_permission(p_organization_id, 'orders.manage') then
    v_customer := p_customer_id;
    if v_customer is not null and not exists (
         select 1 from public.customers c where c.id = v_customer and c.organization_id = p_organization_id) then
      raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'customer';
    end if;
  elsif p_customer_id is not null then
    raise exception using errcode = '42501', message = 'PERMISSION_DENIED',
      detail = 'shoppers cannot order on behalf of another customer';
  elsif auth.uid() is not null then
    select c.id into v_customer from public.customers c
     where c.organization_id = p_organization_id and c.auth_user_id = auth.uid();
  end if;

  if exists (select 1 from jsonb_array_elements(p_lines) e where e ? 'serials' or e ? 'lot_code') then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
      detail = 'online orders are allocated units and lots automatically';
  end if;

  v_hold := least(greatest(coalesce((v_settings->>'checkout_hold_minutes')::int, 15), 1), 120);
  v_max  := coalesce((v_settings->>'checkout_max_line_quantity')::numeric, 20);
  if exists (select 1 from public._order_input(p_organization_id, p_lines) i where i.quantity > v_max) then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
      detail = format('at most %s of one item per order', v_max);
  end if;
  v_expires := now() + make_interval(mins => v_hold);

  for v_loc in
    select l.id from public.locations l
     where l.organization_id = p_organization_id and l.is_active and l.sells_online
     order by l.fulfilment_priority, l.code
  loop
    begin
      insert into public.orders
        (organization_id, number, channel, location_id, customer_id, status, currency_code,
         tax_inclusive, idempotency_key, reservation_expires_at, note)
      values
        (p_organization_id, public.next_document_number(p_organization_id, 'order', 'ORD-'), p_channel,
         v_loc.id, v_customer, 'pending_payment', v_currency, v_inclusive, p_idempotency_key, v_expires, p_note)
      returning id into v_order;

      perform public._write_order_lines(p_organization_id, v_order, p_lines, null, false);

      for r in
        select ol.variant_id, sum(ol.quantity) as quantity
          from public.order_lines ol where ol.order_id = v_order
         group by ol.variant_id order by ol.variant_id
      loop
        perform public._reserve_line(p_organization_id, v_loc.id, r.variant_id, r.quantity,
                                     'order', v_order, v_expires);
      end loop;

      v_done := true;
      exit;
    exception
      when sqlstate 'NC001' or sqlstate 'NC004' then
        get stacked diagnostics v_detail = pg_exception_detail;
      when unique_violation then
        get stacked diagnostics v_constraint = constraint_name;
        if not public._is_idempotency_clash(v_constraint) then
          raise;
        end if;
        select o.id into v_order from public.orders o
         where o.organization_id = p_organization_id and o.idempotency_key = p_idempotency_key;
        return public._order_summary(v_order) || '{"replayed": true}'::jsonb;
    end;
  end loop;

  if not v_done then
    raise exception using errcode = 'NC001', message = 'OUT_OF_STOCK',
      detail = coalesce(v_detail, 'no location is set up to fulfil online orders');
  end if;

  return public._order_summary(v_order);
end $$;

-- ---------------------------------------------------------------------------
-- confirm_order split into a permission wrapper and the internal step, so
-- payment functions can confirm an order they have just seen paid.
-- ---------------------------------------------------------------------------
create or replace function public._confirm_order(p_order_id uuid) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  o public.orders%rowtype;
  r record;
begin
  select * into o from public.orders where id = p_order_id for update;
  if not found then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'order';
  end if;

  if o.status in ('confirmed', 'completed') then
    return public._order_summary(o.id) || '{"replayed": true}'::jsonb;
  elsif o.status = 'cancelled' then
    raise exception using errcode = 'NC006', message = 'INVALID_STATE', detail = 'order was cancelled';
  end if;

  if not exists (select 1 from public.stock_reservations sr
                  where sr.source_type = 'order' and sr.source_id = o.id and sr.status = 'active') then
    begin
      for r in
        select ol.variant_id, sum(ol.quantity) as quantity
          from public.order_lines ol where ol.order_id = o.id
         group by ol.variant_id order by ol.variant_id
      loop
        perform public._reserve_line(o.organization_id, o.location_id, r.variant_id, r.quantity,
                                     'order', o.id, null);
      end loop;
    exception when sqlstate 'NC001' or sqlstate 'NC004' then
      update public.orders set status = 'stock_conflict', reservation_expires_at = null where id = o.id;
      return public._order_summary(o.id);
    end;
  end if;

  perform public._consume_reservations('order', o.id, 'sale');

  insert into public.order_line_units (organization_id, order_line_id, serial_unit_id)
  select o.organization_id, ol.id, sr.serial_unit_id
    from public.stock_reservations sr
    join lateral (select l.id from public.order_lines l
                   where l.order_id = o.id and l.variant_id = sr.variant_id
                   order by l.position limit 1) ol on true
   where sr.source_type = 'order' and sr.source_id = o.id
     and sr.status = 'consumed' and sr.serial_unit_id is not null
  on conflict do nothing;

  update public.orders
     set status = 'confirmed', confirmed_at = now(), reservation_expires_at = null
   where id = o.id;
  perform public._after_confirm(o.id);  -- gift cards issued, points earned (0014)
  return public._order_summary(o.id);
end $$;

create or replace function public.confirm_order(p_order_id uuid) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_org uuid;
begin
  select organization_id into v_org from public.orders where id = p_order_id;
  if v_org is null then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'order';
  end if;
  perform public.assert_permission(v_org, 'orders.manage');
  return public._confirm_order(p_order_id);
end $$;

-- ---------------------------------------------------------------------------
-- record_payment: staff take money against an existing order - cash on
-- delivery collected, a bank transfer seen in the account, a pay-later order
-- settled at the counter. A fully paid online order is confirmed.
-- ---------------------------------------------------------------------------
create or replace function public.record_payment(
  p_order_id  uuid,
  p_method    public.payment_method,
  p_amount    numeric,
  p_reference text default null,
  p_note      text default null) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  o     public.orders%rowtype;
  v_due numeric;
begin
  select * into o from public.orders where id = p_order_id for update;
  if not found then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'order';
  end if;
  if not (public.has_permission(o.organization_id, 'orders.manage')
          or (public.has_permission(o.organization_id, 'pos.sell')
              and public.has_location_access(o.organization_id, o.location_id))) then
    raise exception using errcode = '42501', message = 'PERMISSION_DENIED', detail = 'orders.manage';
  end if;
  if o.status in ('cancelled', 'expired') then
    raise exception using errcode = 'NC006', message = 'INVALID_STATE', detail = format('order is %s', o.status);
  end if;
  if p_method = 'online_gateway' then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
      detail = 'gateway payments arrive through record_gateway_payment';
  end if;

  v_due := o.total - o.amount_paid;
  if p_amount is null or p_amount <= 0 or p_amount > v_due then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
      detail = json_build_object('due', v_due, 'amount', p_amount)::text;
  end if;

  if p_method = 'store_credit' then
    if o.customer_id is null then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'store credit needs a customer';
    end if;
    insert into public.store_credit_ledger (organization_id, customer_id, amount, reason, source_type, source_id)
    values (o.organization_id, o.customer_id, -p_amount, 'Spent on order ' || o.number, 'order', o.id);
  end if;

  insert into public.payments (organization_id, order_id, method, amount, provider_reference, note, captured_at)
  values (o.organization_id, o.id, p_method, p_amount, p_reference, p_note, now());
  perform public._refresh_payment_status(o.id);

  if o.status in ('pending_payment', 'stock_conflict')
     and (select amount_paid >= total from public.orders where id = o.id) then
    return public._confirm_order(o.id);
  end if;
  return public._order_summary(o.id);
end $$;

-- ---------------------------------------------------------------------------
-- record_gateway_payment: the payment gateway webhook (service role only).
-- The same (provider, reference) is recorded once however often it arrives.
-- ---------------------------------------------------------------------------
create or replace function public.record_gateway_payment(
  p_order_id  uuid,
  p_provider  text,
  p_reference text,
  p_amount    numeric,
  p_status    public.payment_status default 'captured',
  p_payload   jsonb default '{}'::jsonb) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  o public.orders%rowtype;
begin
  if not public.is_platform_admin() then
    raise exception using errcode = '42501', message = 'PERMISSION_DENIED', detail = 'payment webhooks only';
  end if;
  if p_provider is null or p_reference is null or p_amount is null or p_amount <= 0
     or p_status not in ('captured', 'failed') then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
      detail = 'provider, reference, a positive amount and status captured|failed are required';
  end if;

  -- The order row lock serialises duplicate deliveries of the same webhook.
  select * into o from public.orders where id = p_order_id for update;
  if not found then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'order';
  end if;

  if exists (select 1 from public.payments p
              where p.organization_id = o.organization_id and p.provider = p_provider
                and p.kind = 'payment' and p.provider_reference = p_reference) then
    return public._order_summary(o.id) || '{"replayed": true}'::jsonb;
  end if;

  insert into public.payments
    (organization_id, order_id, method, status, amount, provider, provider_reference, payload, captured_at)
  values
    (o.organization_id, o.id, 'online_gateway', p_status, p_amount, p_provider, p_reference, coalesce(p_payload, '{}'),
     case when p_status = 'captured' then now() end);
  perform public._refresh_payment_status(o.id);

  if p_status = 'captured' and o.status in ('pending_payment', 'expired', 'stock_conflict')
     and (select amount_paid >= total from public.orders where id = o.id) then
    return public._confirm_order(o.id);
  end if;
  return public._order_summary(o.id);
end $$;

-- ---------------------------------------------------------------------------
-- refund_payment: money back. Stock is not touched here - putting goods back
-- on the shelf is the returns module's job.
-- ---------------------------------------------------------------------------
create or replace function public.refund_payment(
  p_order_id  uuid,
  p_amount    numeric,
  p_method    public.payment_method,
  p_reason    text,
  p_reference text default null) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  o            public.orders%rowtype;
  v_refundable numeric;
begin
  select * into o from public.orders where id = p_order_id for update;
  if not found then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'order';
  end if;
  perform public.assert_permission(o.organization_id, 'orders.manage');

  if p_reason is null or length(btrim(p_reason)) < 3 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'say why the money is going back';
  end if;
  v_refundable := o.amount_paid - o.amount_refunded;
  if p_amount is null or p_amount <= 0 or p_amount > v_refundable then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
      detail = json_build_object('refundable', v_refundable, 'amount', p_amount)::text;
  end if;

  if p_method = 'store_credit' then
    if o.customer_id is null then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'store credit needs a customer';
    end if;
    insert into public.store_credit_ledger (organization_id, customer_id, amount, reason, source_type, source_id)
    values (o.organization_id, o.customer_id, p_amount, 'Refund on order ' || o.number || ': ' || p_reason, 'order', o.id);
  end if;

  insert into public.payments
    (organization_id, order_id, kind, method, amount, provider_reference, note, captured_at)
  values
    (o.organization_id, o.id, 'refund', p_method, p_amount, p_reference, p_reason, now());
  perform public._refresh_payment_status(o.id);
  return public._order_summary(o.id);
end $$;

-- ---------------------------------------------------------------------------
-- adjust_store_credit: goodwill credit or a correction, always with a reason
-- ---------------------------------------------------------------------------
create or replace function public.adjust_store_credit(
  p_customer_id uuid,
  p_amount      numeric,
  p_reason      text) returns numeric
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_org uuid;
begin
  select organization_id into v_org from public.customers where id = p_customer_id;
  if v_org is null then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'customer';
  end if;
  perform public.assert_permission(v_org, 'orders.manage');
  if p_amount is null or p_amount = 0 or p_reason is null or length(btrim(p_reason)) < 3 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'a non-zero amount and a reason are required';
  end if;
  insert into public.store_credit_ledger (organization_id, customer_id, amount, reason, source_type)
  values (v_org, p_customer_id, p_amount, p_reason, 'adjustment');
  return (select store_credit_balance from public.customers where id = p_customer_id);
end $$;

-- ---------------------------------------------------------------------------
-- Security for everything above
-- ---------------------------------------------------------------------------
alter table public.tax_rates enable row level security;
alter table public.payments enable row level security;
alter table public.store_credit_ledger enable row level security;
alter table public.staff_pins enable row level security;
alter table public.approvals enable row level security;

grant select on public.tax_rates to anon, authenticated;
grant insert, update on public.tax_rates to authenticated;
grant select on public.payments, public.store_credit_ledger, public.approvals to authenticated;
grant all on public.tax_rates, public.payments, public.store_credit_ledger, public.staff_pins, public.approvals to service_role;
revoke all on public.payments, public.store_credit_ledger, public.staff_pins, public.approvals from anon;
revoke insert, update, delete, truncate on public.payments, public.store_credit_ledger, public.approvals from authenticated;
revoke all on public.staff_pins from authenticated;

-- RLS decides which customer rows staff may edit, not which columns. Staff edit
-- contact details only: the store credit balance moves solely through its
-- ledger, and linking a login to a customer record is not a till operation.
revoke insert, update on public.customers from authenticated;
grant insert (organization_id, full_name, phone, email, notes, marketing_consent) on public.customers to authenticated;
grant update (full_name, phone, email, notes, marketing_consent) on public.customers to authenticated;

create policy tax_rates_read on public.tax_rates for select using (is_active or public.is_member(organization_id));
create policy tax_rates_insert on public.tax_rates for insert
  with check (public.has_permission(organization_id, 'settings.manage'));
create policy tax_rates_update on public.tax_rates for update
  using (public.has_permission(organization_id, 'settings.manage'))
  with check (public.has_permission(organization_id, 'settings.manage'));

create policy payments_read on public.payments for select
  using (public.has_permission(organization_id, 'orders.view') or public.owns_order(order_id));
create policy store_credit_ledger_read on public.store_credit_ledger for select
  using (public.has_permission(organization_id, 'customers.view') or exists (
    select 1 from public.customers c where c.id = customer_id and c.auth_user_id = auth.uid()));
create policy approvals_read on public.approvals for select
  using (public.has_permission(organization_id, 'audit.view'));
-- staff_pins: no policy, no API access at all.

revoke execute on all functions in schema public from public, anon, authenticated;
grant execute on all functions in schema public to service_role;

grant execute on function
  public.is_platform_admin(), public.role_permissions(public.staff_role), public.is_member(uuid),
  public.has_permission(uuid, text), public.has_location_access(uuid, uuid),
  public.module_enabled(uuid, public.module_key), public.owns_order(uuid)
  to anon, authenticated;

grant execute on function
  public.storefront_organization(text),
  public.storefront_availability(uuid, uuid[]),
  public.start_checkout(uuid, jsonb, text, public.sales_channel, uuid, text)
  to anon, authenticated;

grant execute on function
  public.cancel_order(uuid, text),
  public.place_order(uuid, public.sales_channel, jsonb, uuid, text, text, jsonb, jsonb, uuid),
  public.confirm_order(uuid),
  public.receive_stock(uuid, jsonb, text, text),
  public.adjust_stock(uuid, uuid, numeric, public.movement_type, text, text[], text, date, numeric),
  public.lookup_serial(uuid, text),
  public.inventory_integrity_report(uuid),
  public.upsert_staff_member(uuid, uuid, public.staff_role, uuid[], boolean),
  public.set_my_pin(uuid, text),
  public.request_override(uuid, uuid, text, text),
  public.record_payment(uuid, public.payment_method, numeric, text, text),
  public.refund_payment(uuid, numeric, public.payment_method, text, text),
  public.adjust_store_credit(uuid, numeric, text)
  to authenticated;

-- record_gateway_payment: service_role only (granted above).

-- ======================================================================
-- 0009_admin.sql
-- ======================================================================
-- 0009_admin.sql
-- Commands and read models for the admin app: atomic product save, organisation
-- settings, staff by email, stock overview and movement history (cost only for
-- people who may see it), variant search for pickers, dashboard summary.

set check_function_bodies = off;

-- ---------------------------------------------------------------------------
-- Cost is management information: hide cost columns from direct reads.
-- Cost figures come through functions that require reports.view.
-- ---------------------------------------------------------------------------
revoke select on public.stock_levels, public.inventory_movements, public.serial_units from authenticated;
grant select (organization_id, location_id, variant_id, on_hand, reserved, low_stock_threshold, updated_at)
  on public.stock_levels to authenticated;
grant select (id, organization_id, location_id, variant_id, batch_id, serial_unit_id, movement_type, quantity,
              source_type, source_id, note, created_by, created_at)
  on public.inventory_movements to authenticated;
grant select (id, organization_id, variant_id, serial, status, location_id, received_at, updated_at)
  on public.serial_units to authenticated;

-- ---------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------
create or replace function public.slugify(p_text text) returns text
language sql immutable as $$
  select nullif(trim(both '-' from regexp_replace(lower(coalesce(p_text, '')), '[^a-z0-9]+', '-', 'g')), '')
$$;

create or replace function public._unique_product_slug(p_org uuid, p_base text, p_product uuid) returns text
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  v_base text := coalesce(public.slugify(p_base), 'product');
  v_slug text := v_base;
  v_n    int := 1;
begin
  while exists (select 1 from public.products p
                 where p.organization_id = p_org and p.slug = v_slug and p.id is distinct from p_product) loop
    v_n := v_n + 1;
    v_slug := v_base || '-' || v_n;
  end loop;
  return v_slug;
end $$;

-- ---------------------------------------------------------------------------
-- save_product: the product, its options, variants and attributes in one go
-- ---------------------------------------------------------------------------
-- p_product = {
--   id?, name, slug?, summary?, description?, status?, brand_id?, category_id?,
--   tracking_mode?, unit_of_measure?, allow_fractional?, tax_rate_id?, tax_exempt?,
--   options:    [{name, values: [..]}],                     -- may be empty
--   variants:   [{id?, option_values: [..], title?, sku?, barcode?, price,
--                 compare_at_price?, is_active?}],          -- at least one
--   attributes: {"<attribute_id>": value, ...}
-- }
-- The payload is the product's complete new state (what the edit form shows):
-- a field left out is cleared, not kept. Variants left out are deactivated,
-- never deleted, because sold stock refers to them.
create or replace function public.save_product(p_organization_id uuid, p_product jsonb) returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_id       uuid := nullif(p_product->>'id', '')::uuid;
  v_existing public.products%rowtype;
  v_options  jsonb := coalesce(p_product->'options', '[]'::jsonb);
  v_variants jsonb := coalesce(p_product->'variants', '[]'::jsonb);
  v_opt_count int;
  v_keep     uuid[] := '{}';
  v_opt      jsonb;
  v_opt_id   uuid;
  v_var      jsonb;
  v_var_id   uuid;
  v_vals     text[];
  v_val_ids  uuid[];
  v_title    text;
  v_combos   text[] := '{}';
  v_key      text;
  v_attr     record;
  v_i        int;
  v_constraint text;
begin
  perform public.assert_permission(p_organization_id, 'catalog.manage');

  if coalesce(btrim(p_product->>'name'), '') = '' then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'a product needs a name';
  end if;
  if jsonb_typeof(v_options) <> 'array' or jsonb_typeof(v_variants) <> 'array' or jsonb_array_length(v_variants) = 0 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'a product needs at least one variant';
  end if;
  v_opt_count := jsonb_array_length(v_options);
  if v_opt_count > 3 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'at most three options (e.g. size, colour, material)';
  end if;
  if (select count(distinct lower(btrim(o->>'name'))) from jsonb_array_elements(v_options) o) <> v_opt_count
     or exists (select 1 from jsonb_array_elements(v_options) o
                 where coalesce(btrim(o->>'name'), '') = '' or jsonb_typeof(o->'values') <> 'array'
                    or jsonb_array_length(o->'values') = 0) then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
      detail = 'each option needs a unique name and at least one value';
  end if;

  if v_id is not null then
    select * into v_existing from public.products where id = v_id and organization_id = p_organization_id for update;
    if not found then
      raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'product';
    end if;
  end if;

  begin
    if v_id is null then
      insert into public.products
        (organization_id, name, slug, summary, description, status, brand_id, category_id, tracking_mode,
         unit_of_measure, allow_fractional, tax_rate_id, tax_exempt)
      values
        (p_organization_id, btrim(p_product->>'name'),
         public._unique_product_slug(p_organization_id, coalesce(nullif(p_product->>'slug', ''), p_product->>'name'), null),
         p_product->>'summary', p_product->>'description',
         coalesce(p_product->>'status', 'draft')::public.product_status,
         nullif(p_product->>'brand_id', '')::uuid, nullif(p_product->>'category_id', '')::uuid,
         coalesce(p_product->>'tracking_mode', 'none')::public.tracking_mode,
         coalesce(nullif(p_product->>'unit_of_measure', ''), 'each'),
         coalesce((p_product->>'allow_fractional')::boolean, false),
         nullif(p_product->>'tax_rate_id', '')::uuid, coalesce((p_product->>'tax_exempt')::boolean, false))
      returning id into v_id;
    else
      update public.products set
        name             = btrim(p_product->>'name'),
        slug             = case when nullif(p_product->>'slug', '') is null or p_product->>'slug' = v_existing.slug
                                then v_existing.slug
                                else public._unique_product_slug(p_organization_id, p_product->>'slug', v_id) end,
        summary          = p_product->>'summary',
        description      = p_product->>'description',
        status           = coalesce(p_product->>'status', v_existing.status::text)::public.product_status,
        brand_id         = nullif(p_product->>'brand_id', '')::uuid,
        category_id      = nullif(p_product->>'category_id', '')::uuid,
        tracking_mode    = coalesce(p_product->>'tracking_mode', v_existing.tracking_mode::text)::public.tracking_mode,
        unit_of_measure  = coalesce(nullif(p_product->>'unit_of_measure', ''), v_existing.unit_of_measure),
        allow_fractional = coalesce((p_product->>'allow_fractional')::boolean, v_existing.allow_fractional),
        tax_rate_id      = nullif(p_product->>'tax_rate_id', '')::uuid,
        tax_exempt       = coalesce((p_product->>'tax_exempt')::boolean, v_existing.tax_exempt)
      where id = v_id;
    end if;
  exception when foreign_key_violation then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'unknown brand, category or tax rate';
  end;

  -- Options: drop the ones no longer listed (their variant links go with them),
  -- then upsert by name and reconcile values.
  delete from public.product_options po
   where po.product_id = v_id
     and not exists (select 1 from jsonb_array_elements(v_options) o where lower(btrim(o->>'name')) = lower(po.name));

  v_i := 0;
  for v_opt in select o from jsonb_array_elements(v_options) o loop
    v_i := v_i + 1;
    select id into v_opt_id from public.product_options
     where product_id = v_id and lower(name) = lower(btrim(v_opt->>'name'));
    if v_opt_id is null then
      insert into public.product_options (organization_id, product_id, name, position)
      values (p_organization_id, v_id, btrim(v_opt->>'name'), v_i) returning id into v_opt_id;
    else
      update public.product_options set name = btrim(v_opt->>'name'), position = v_i where id = v_opt_id;
    end if;

    delete from public.product_option_values pv
     where pv.option_id = v_opt_id
       and not exists (select 1 from jsonb_array_elements_text(v_opt->'values') x where btrim(x) = pv.value);
    insert into public.product_option_values (organization_id, option_id, value, position)
    select p_organization_id, v_opt_id, btrim(x.v), x.n
      from jsonb_array_elements_text(v_opt->'values') with ordinality x(v, n)
    on conflict (option_id, value) do update set position = excluded.position;
    v_opt_id := null;
  end loop;

  -- Variants
  for v_var in select x from jsonb_array_elements(v_variants) x loop
    v_vals := array(select btrim(x) from jsonb_array_elements_text(coalesce(v_var->'option_values', '[]'::jsonb)) x);
    if cardinality(v_vals) <> v_opt_count then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
        detail = format('each variant needs one value per option (%s)', v_opt_count);
    end if;
    v_key := lower(array_to_string(v_vals, '|'));
    if v_key = any (v_combos) then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
        detail = format('two variants are both "%s"', array_to_string(v_vals, ' / '));
    end if;
    v_combos := v_combos || v_key;

    -- resolve option values in option order
    select array_agg(pv.id order by po.position) into v_val_ids
      from unnest(v_vals) with ordinality u(val, n)
      join public.product_options po on po.product_id = v_id and po.position = u.n
      join public.product_option_values pv on pv.option_id = po.id and pv.value = u.val;
    if coalesce(cardinality(v_val_ids), 0) <> v_opt_count then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
        detail = format('"%s" uses a value that is not in its option', array_to_string(v_vals, ' / '));
    end if;

    v_title := coalesce(nullif(btrim(v_var->>'title'), ''),
                        nullif(array_to_string(v_vals, ' / '), ''), 'Default');
    v_var_id := nullif(v_var->>'id', '')::uuid;

    begin
      if v_var_id is not null then
        update public.product_variants set
          title = v_title, sku = nullif(btrim(v_var->>'sku'), ''), barcode = nullif(btrim(v_var->>'barcode'), ''),
          price = (v_var->>'price')::numeric, compare_at_price = nullif(v_var->>'compare_at_price', '')::numeric,
          is_active = coalesce((v_var->>'is_active')::boolean, true)
        where id = v_var_id and product_id = v_id;
        if not found then
          raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'variant does not belong to this product';
        end if;
      else
        insert into public.product_variants
          (organization_id, product_id, title, sku, barcode, price, compare_at_price, is_active, position)
        values
          (p_organization_id, v_id, v_title, nullif(btrim(v_var->>'sku'), ''), nullif(btrim(v_var->>'barcode'), ''),
           (v_var->>'price')::numeric, nullif(v_var->>'compare_at_price', '')::numeric,
           coalesce((v_var->>'is_active')::boolean, true), cardinality(v_keep) + 1)
        returning id into v_var_id;
      end if;
    exception
      when unique_violation then
        get stacked diagnostics v_constraint = constraint_name;
        raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
          detail = case when v_constraint like '%barcode%' then format('barcode %s is already used', v_var->>'barcode')
                        else format('SKU %s is already used', v_var->>'sku') end;
      when check_violation or not_null_violation then
        raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
          detail = format('"%s": price is required and a compare-at price must be higher than the price', v_title);
    end;

    delete from public.variant_option_values where variant_id = v_var_id;
    insert into public.variant_option_values (organization_id, variant_id, option_value_id)
    select p_organization_id, v_var_id, x from unnest(v_val_ids) x;

    update public.product_variants set position = cardinality(v_keep) + 1 where id = v_var_id;
    v_keep := v_keep || v_var_id;
  end loop;

  update public.product_variants set is_active = false
   where product_id = v_id and not (id = any (v_keep)) and is_active;

  -- Attributes (structured specifications)
  if p_product ? 'attributes' then
    delete from public.product_attribute_values where product_id = v_id;
    for v_attr in select key, value from jsonb_each(coalesce(p_product->'attributes', '{}'::jsonb)) loop
      continue when v_attr.value is null or v_attr.value = 'null'::jsonb or v_attr.value = '""'::jsonb;
      insert into public.product_attribute_values (organization_id, product_id, attribute_id, value)
      select p_organization_id, v_id, ad.id, v_attr.value
        from public.attribute_definitions ad
       where ad.id = v_attr.key::uuid and ad.organization_id = p_organization_id;
    end loop;
  end if;

  return v_id;
end $$;

-- ---------------------------------------------------------------------------
-- Organisation settings (a whitelist, not arbitrary JSON)
-- ---------------------------------------------------------------------------
create or replace function public.update_organization_settings(p_organization_id uuid, p_changes jsonb)
returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_allowed constant text[] := array['checkout_hold_minutes', 'checkout_max_line_quantity', 'discount_limits',
                                     'receipt_footer', 'contact_email', 'contact_phone', 'low_stock_default'];
  v_settings jsonb;
  v_key text;
begin
  perform public.assert_permission(p_organization_id, 'settings.manage');

  for v_key in select jsonb_object_keys(coalesce(p_changes->'settings', '{}'::jsonb)) loop
    if not (v_key = any (v_allowed)) then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = format('unknown setting %s', v_key);
    end if;
  end loop;
  if p_changes ? 'name' and coalesce(btrim(p_changes->>'name'), '') = '' then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'the business needs a name';
  end if;
  if coalesce((p_changes->'settings'->>'checkout_hold_minutes')::int, 15) not between 1 and 120 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'checkout hold is 1 to 120 minutes';
  end if;
  if exists (select 1 from jsonb_each_text(coalesce(p_changes->'settings'->'discount_limits', '{}'::jsonb)) d
              where d.key::text not in ('owner','admin','manager','cashier','stock_keeper','viewer')
                 or d.value::numeric < 0 or d.value::numeric > 100) then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'discount limits are 0-100 per role';
  end if;

  update public.organizations
     set name = coalesce(nullif(btrim(p_changes->>'name'), ''), name),
         prices_include_tax = coalesce((p_changes->>'prices_include_tax')::boolean, prices_include_tax),
         timezone = coalesce(nullif(p_changes->>'timezone', ''), timezone),
         settings = settings || coalesce(p_changes->'settings', '{}'::jsonb)
   where id = p_organization_id
  returning settings into v_settings;
  return v_settings;
end $$;

-- What the signed-in user needs to open the admin: their organisations, role,
-- permissions and switched-on modules.
create or replace function public.my_workspaces()
returns table (organization_id uuid, name text, slug text, currency_code char(3), timezone text,
               prices_include_tax boolean, settings jsonb, role public.staff_role, permissions text[],
               location_ids uuid[], modules public.module_key[])
language sql stable security definer set search_path = public, pg_temp as $$
  select o.id, o.name, o.slug, o.currency_code, o.timezone, o.prices_include_tax, o.settings,
         m.role, public.role_permissions(m.role), m.location_ids,
         coalesce((select array_agg(om.module order by om.module) from public.organization_modules om
                    where om.organization_id = o.id and om.enabled), '{}')
    from public.memberships m join public.organizations o on o.id = m.organization_id
   where m.user_id = auth.uid() and m.is_active
   order by o.name
$$;

-- ---------------------------------------------------------------------------
-- Staff
-- ---------------------------------------------------------------------------
create or replace function public.list_staff(p_organization_id uuid)
returns table (user_id uuid, email text, role public.staff_role, location_ids uuid[], is_active boolean,
               has_pin boolean, created_at timestamptz)
language plpgsql stable security definer set search_path = public, pg_temp as $$
begin
  perform public.assert_permission(p_organization_id, 'staff.manage');
  return query
    select m.user_id, u.email::text, m.role, m.location_ids, m.is_active,
           exists (select 1 from public.staff_pins sp where sp.organization_id = m.organization_id and sp.user_id = m.user_id),
           m.created_at
      from public.memberships m join auth.users u on u.id = m.user_id
     where m.organization_id = p_organization_id
     order by m.is_active desc, m.role, u.email;
end $$;

-- Adds someone who already has an account. (Email invitations need the auth
-- admin API and come with the hosted Supabase project.)
create or replace function public.add_staff_by_email(
  p_organization_id uuid, p_email text, p_role public.staff_role, p_location_ids uuid[] default null)
returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_user uuid;
begin
  perform public.assert_permission(p_organization_id, 'staff.manage');
  select id into v_user from auth.users where lower(email) = lower(btrim(p_email));
  if v_user is null then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND',
      detail = 'no account uses that email yet - ask them to sign up first';
  end if;
  perform public.upsert_staff_member(p_organization_id, v_user, p_role, p_location_ids, true);
  return v_user;
end $$;

-- ---------------------------------------------------------------------------
-- Inventory read models
-- ---------------------------------------------------------------------------
create or replace function public.search_variants(
  p_organization_id uuid, p_query text, p_location_id uuid default null, p_limit int default 20)
returns table (variant_id uuid, product_id uuid, product_name text, variant_title text, sku text, barcode text,
               price numeric, status public.product_status, tracking_mode public.tracking_mode,
               unit_of_measure text, allow_fractional boolean, on_hand numeric, available numeric)
language plpgsql stable security definer set search_path = public, pg_temp as $$
begin
  if not (public.has_permission(p_organization_id, 'catalog.view')
          or public.has_permission(p_organization_id, 'inventory.view')) then
    raise exception using errcode = '42501', message = 'PERMISSION_DENIED', detail = 'catalog.view';
  end if;
  return query
    select v.id, p.id, p.name, v.title, v.sku, v.barcode, v.price, p.status, p.tracking_mode,
           p.unit_of_measure, p.allow_fractional,
           case when p.tracking_mode = 'non_stock' then null else coalesce(sum(s.on_hand), 0) end,
           case when p.tracking_mode = 'non_stock' then null else coalesce(sum(s.on_hand - s.reserved), 0) end
      from public.product_variants v
      join public.products p on p.id = v.product_id
      left join public.stock_levels s on s.variant_id = v.id and (p_location_id is null or s.location_id = p_location_id)
     where v.organization_id = p_organization_id and v.is_active and p.status <> 'archived'
       and (coalesce(btrim(p_query), '') = ''
            or v.barcode = btrim(p_query)
            or v.sku ilike btrim(p_query) || '%'
            or p.name ilike '%' || btrim(p_query) || '%'
            or v.title ilike '%' || btrim(p_query) || '%')
     group by v.id, p.id
     order by (v.barcode = btrim(p_query) or lower(v.sku) = lower(btrim(p_query))) desc, p.name, v.position
     limit least(greatest(p_limit, 1), 100);
end $$;

create or replace function public.stock_overview(
  p_organization_id uuid, p_location_id uuid default null, p_query text default null,
  p_low_only boolean default false, p_limit int default 200, p_offset int default 0)
returns table (variant_id uuid, product_id uuid, product_name text, variant_title text, sku text,
               tracking_mode public.tracking_mode, unit_of_measure text,
               location_id uuid, location_name text, on_hand numeric, reserved numeric, available numeric,
               low_stock_threshold numeric, is_low boolean, avg_unit_cost numeric, stock_value numeric)
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  v_costs   boolean;
  v_default numeric;
begin
  perform public.assert_permission(p_organization_id, 'inventory.view');
  v_costs := public.has_permission(p_organization_id, 'reports.view');
  select coalesce((settings->>'low_stock_default')::numeric, 3) into v_default
    from public.organizations where id = p_organization_id;

  return query
    select v.id, p.id, p.name, v.title, v.sku, p.tracking_mode, p.unit_of_measure,
           l.id, l.name, s.on_hand, s.reserved, s.on_hand - s.reserved,
           s.low_stock_threshold,
           (s.on_hand - s.reserved) <= coalesce(s.low_stock_threshold, v_default),
           case when v_costs then s.avg_unit_cost end,
           case when v_costs then round(s.on_hand * s.avg_unit_cost, 2) end
      from public.stock_levels s
      join public.product_variants v on v.id = s.variant_id
      join public.products p on p.id = v.product_id
      join public.locations l on l.id = s.location_id
     where s.organization_id = p_organization_id
       and (p_location_id is null or s.location_id = p_location_id)
       and (coalesce(btrim(p_query), '') = '' or p.name ilike '%' || btrim(p_query) || '%'
            or v.sku ilike btrim(p_query) || '%' or v.barcode = btrim(p_query))
       and (not p_low_only or (s.on_hand - s.reserved) <= coalesce(s.low_stock_threshold, v_default))
     order by p.name, v.position, l.name
     limit least(greatest(p_limit, 1), 1000) offset greatest(p_offset, 0);
end $$;

create or replace function public.stock_movements(
  p_organization_id uuid, p_variant_id uuid, p_location_id uuid default null, p_limit int default 100)
returns table (id bigint, created_at timestamptz, location_name text, movement_type public.movement_type,
               quantity numeric, unit_cost numeric, lot_code text, serial text, source_type text,
               source_id uuid, reference text, note text, actor_email text)
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  v_costs boolean;
begin
  perform public.assert_permission(p_organization_id, 'inventory.view');
  v_costs := public.has_permission(p_organization_id, 'reports.view');
  return query
    select m.id, m.created_at, l.name, m.movement_type, m.quantity,
           case when v_costs then m.unit_cost end,
           b.lot_code, su.serial, m.source_type, m.source_id,
           coalesce(o.number, r.number), m.note, u.email::text
      from public.inventory_movements m
      join public.locations l on l.id = m.location_id
      left join public.batches b on b.id = m.batch_id
      left join public.serial_units su on su.id = m.serial_unit_id
      left join public.orders o on m.source_type = 'order' and o.id = m.source_id
      left join public.stock_receipts r on m.source_type = 'stock_receipt' and r.id = m.source_id
      left join auth.users u on u.id = m.created_by
     where m.organization_id = p_organization_id and m.variant_id = p_variant_id
       and (p_location_id is null or m.location_id = p_location_id)
     order by m.id desc
     limit least(greatest(p_limit, 1), 500);
end $$;

create or replace function public.set_low_stock_threshold(p_location_id uuid, p_variant_id uuid, p_threshold numeric)
returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_org uuid;
begin
  select organization_id into v_org from public.locations where id = p_location_id;
  if v_org is null or not exists (select 1 from public.product_variants where id = p_variant_id and organization_id = v_org) then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'location or variant';
  end if;
  perform public.assert_permission(v_org, 'inventory.adjust');
  if p_threshold is not null and p_threshold < 0 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'threshold cannot be negative';
  end if;
  perform public._lock_stock_row(v_org, p_location_id, p_variant_id);
  update public.stock_levels set low_stock_threshold = p_threshold
   where location_id = p_location_id and variant_id = p_variant_id;
end $$;

-- ---------------------------------------------------------------------------
-- Dashboard
-- ---------------------------------------------------------------------------
create or replace function public.dashboard_summary(p_organization_id uuid, p_from timestamptz, p_to timestamptz)
returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  v_default numeric;
begin
  perform public.assert_permission(p_organization_id, 'reports.view');
  select coalesce((settings->>'low_stock_default')::numeric, 3) into v_default
    from public.organizations where id = p_organization_id;

  return jsonb_build_object(
    'totals', (
      select jsonb_build_object(
        'orders', count(*), 'gross', coalesce(sum(o.subtotal), 0), 'discounts', coalesce(sum(o.discount_total), 0),
        'tax', coalesce(sum(o.tax_total), 0), 'sales', coalesce(sum(o.total), 0),
        'refunds', coalesce(sum(o.amount_refunded), 0),
        'net', coalesce(sum(o.total - o.amount_refunded), 0),
        'outstanding', coalesce(sum(greatest(o.total - o.amount_paid, 0)), 0))
        from public.orders o
       where o.organization_id = p_organization_id and o.status in ('confirmed', 'completed')
         and o.placed_at >= p_from and o.placed_at < p_to),
    'by_channel', coalesce((
      select jsonb_agg(jsonb_build_object('channel', c.channel, 'orders', c.n, 'sales', c.sales) order by c.sales desc)
        from (select o.channel, count(*) n, sum(o.total) sales from public.orders o
               where o.organization_id = p_organization_id and o.status in ('confirmed', 'completed')
                 and o.placed_at >= p_from and o.placed_at < p_to
               group by o.channel) c), '[]'::jsonb),
    'by_method', coalesce((
      select jsonb_agg(jsonb_build_object('method', x.method, 'amount', x.amount) order by x.amount desc)
        from (select p.method, sum(case when p.kind = 'payment' then p.amount else -p.amount end) amount
                from public.payments p
               where p.organization_id = p_organization_id and p.status = 'captured'
                 and p.created_at >= p_from and p.created_at < p_to
               group by p.method) x), '[]'::jsonb),
    'awaiting_payment', (select count(*) from public.orders o
                          where o.organization_id = p_organization_id and o.status = 'pending_payment'),
    'stock_conflicts', (select count(*) from public.orders o
                         where o.organization_id = p_organization_id and o.status = 'stock_conflict'),
    'low_stock', (select count(*) from public.stock_levels s
                   where s.organization_id = p_organization_id
                     and s.on_hand - s.reserved <= coalesce(s.low_stock_threshold, v_default)),
    'catalogue', jsonb_build_object(
      'products', (select count(*) from public.products p where p.organization_id = p_organization_id and p.status <> 'archived'),
      'active',   (select count(*) from public.products p where p.organization_id = p_organization_id and p.status = 'active'),
      'stocked',  (select count(distinct s.variant_id) from public.stock_levels s
                    where s.organization_id = p_organization_id and s.on_hand > 0)),
    'setup', jsonb_build_object(
      'has_tax_rate', exists (select 1 from public.tax_rates t where t.organization_id = p_organization_id and t.is_active),
      'has_product',  exists (select 1 from public.products p where p.organization_id = p_organization_id),
      'has_stock',    exists (select 1 from public.inventory_movements m where m.organization_id = p_organization_id),
      'has_staff',    (select count(*) > 1 from public.memberships m where m.organization_id = p_organization_id),
      'has_sale',     exists (select 1 from public.orders o where o.organization_id = p_organization_id)));
end $$;

-- ---------------------------------------------------------------------------
-- Grants
-- ---------------------------------------------------------------------------
revoke execute on all functions in schema public from public, anon, authenticated;
grant execute on all functions in schema public to service_role;

grant execute on function
  public.is_platform_admin(), public.role_permissions(public.staff_role), public.is_member(uuid),
  public.has_permission(uuid, text), public.has_location_access(uuid, uuid),
  public.module_enabled(uuid, public.module_key), public.owns_order(uuid), public.slugify(text)
  to anon, authenticated;

grant execute on function
  public.storefront_organization(text),
  public.storefront_availability(uuid, uuid[]),
  public.start_checkout(uuid, jsonb, text, public.sales_channel, uuid, text)
  to anon, authenticated;

grant execute on function
  public.cancel_order(uuid, text),
  public.place_order(uuid, public.sales_channel, jsonb, uuid, text, text, jsonb, jsonb, uuid),
  public.confirm_order(uuid),
  public.receive_stock(uuid, jsonb, text, text),
  public.adjust_stock(uuid, uuid, numeric, public.movement_type, text, text[], text, date, numeric),
  public.lookup_serial(uuid, text),
  public.inventory_integrity_report(uuid),
  public.upsert_staff_member(uuid, uuid, public.staff_role, uuid[], boolean),
  public.set_my_pin(uuid, text),
  public.request_override(uuid, uuid, text, text),
  public.record_payment(uuid, public.payment_method, numeric, text, text),
  public.refund_payment(uuid, numeric, public.payment_method, text, text),
  public.adjust_store_credit(uuid, numeric, text),
  public.save_product(uuid, jsonb),
  public.update_organization_settings(uuid, jsonb),
  public.my_workspaces(),
  public.list_staff(uuid),
  public.add_staff_by_email(uuid, text, public.staff_role, uuid[]),
  public.search_variants(uuid, text, uuid, int),
  public.stock_overview(uuid, uuid, text, boolean, int, int),
  public.stock_movements(uuid, uuid, uuid, int),
  public.set_low_stock_threshold(uuid, uuid, numeric),
  public.dashboard_summary(uuid, timestamptz, timestamptz)
  to authenticated;

-- ======================================================================
-- 0010_storefront.sql
-- ======================================================================
-- 0010_storefront.sql
-- Phase 4: what the online store (and later the app) needs.
--   * orders learn how they reach the customer: delivery / pickup, contact, fee
--   * a server-side cart keyed by a secret token (the app will share it)
--   * catalogue listing with facets, product page, category tree
--   * quote_order: prices a basket with exactly the code checkout uses
--   * checkout: contact + fulfilment + payment method on top of start_checkout
--   * order lookup for guests by a private token; customer profiles for sign-ups

set check_function_bodies = off;

-- ---------------------------------------------------------------------------
-- Orders: fulfilment, contact, delivery fee, private access token
-- ---------------------------------------------------------------------------
create type public.fulfilment_method as enum ('in_store', 'pickup', 'delivery');

alter table public.orders
  add column fulfilment_method       public.fulfilment_method not null default 'in_store',
  add column contact                 jsonb not null default '{}'::jsonb,
  add column shipping_address        jsonb,
  add column shipping_total          numeric(14,2) not null default 0 check (shipping_total >= 0),
  add column intended_payment_method public.payment_method,
  -- Lets a guest open their own order page without an account.
  add column access_token            text not null default encode(extensions.gen_random_bytes(18), 'hex'),
  drop constraint orders_totals_valid,
  add constraint orders_totals_valid check (
    total = subtotal - discount_total + case when tax_inclusive then 0 else tax_total end + shipping_total
    and subtotal >= 0 and discount_total >= 0 and tax_total >= 0 and total >= 0);

-- ---------------------------------------------------------------------------
-- Carts
-- ---------------------------------------------------------------------------
create table public.carts (
  id              uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete cascade,
  -- sha256 of the browser's / app's secret token; the token itself is never stored.
  token_hash      text not null,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  unique (organization_id, token_hash)
);

create table public.cart_items (
  cart_id         uuid not null references public.carts(id) on delete cascade,
  organization_id uuid not null,
  variant_id      uuid not null,
  quantity        numeric(14,3) not null check (quantity > 0),
  added_at        timestamptz not null default now(),
  primary key (cart_id, variant_id),
  foreign key (organization_id, variant_id) references public.product_variants (organization_id, id) on delete cascade
);

alter table public.carts enable row level security;
alter table public.cart_items enable row level security;
revoke all on public.carts, public.cart_items from anon, authenticated;
grant all on public.carts, public.cart_items to service_role;
-- No policies: carts are reached only through the cart_* functions, by token.

create or replace function public._cart_id(p_org uuid, p_token text, p_create boolean) returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_hash text;
  v_id   uuid;
begin
  if p_token is null or length(p_token) < 32 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'a cart token of at least 32 characters is required';
  end if;
  v_hash := encode(extensions.digest(p_token, 'sha256'), 'hex');
  select id into v_id from public.carts where organization_id = p_org and token_hash = v_hash;
  if v_id is null and p_create then
    insert into public.carts (organization_id, token_hash) values (p_org, v_hash)
    on conflict (organization_id, token_hash) do update set updated_at = now()
    returning id into v_id;
  end if;
  return v_id;
end $$;

create or replace function public.cart_get(p_organization_id uuid, p_token text) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  v_cart uuid := public._cart_id(p_organization_id, p_token, false);
begin
  if v_cart is null then
    return jsonb_build_object('items', '[]'::jsonb, 'count', 0, 'subtotal', 0);
  end if;
  return (
    with lines as (
      select ci.variant_id, ci.quantity, v.title, v.sku, v.price, v.compare_at_price,
             p.name, p.slug, p.unit_of_measure, p.allow_fractional,
             (v.is_active and p.status = 'active') as for_sale,
             coalesce(a.available, 0) as available,
             (select m.storage_path from public.product_media m where m.product_id = p.id
               order by (m.variant_id = v.id) desc nulls last, m.position limit 1) as image,
             ci.added_at
        from public.cart_items ci
        join public.product_variants v on v.id = ci.variant_id
        join public.products p on p.id = v.product_id
        left join public.storefront_availability(p_organization_id,
                    array(select variant_id from public.cart_items where cart_id = v_cart)) a on a.variant_id = ci.variant_id
       where ci.cart_id = v_cart)
    select jsonb_build_object(
      'items', coalesce(jsonb_agg(jsonb_build_object(
                 'variant_id', l.variant_id, 'quantity', l.quantity, 'name', l.name, 'slug', l.slug,
                 'variant', l.title, 'sku', l.sku, 'unit_price', l.price, 'compare_at_price', l.compare_at_price,
                 'unit_of_measure', l.unit_of_measure, 'allow_fractional', l.allow_fractional,
                 'line_total', round(l.quantity * l.price, 2), 'available', l.available,
                 'for_sale', l.for_sale, 'image', l.image) order by l.added_at), '[]'::jsonb),
      'count', coalesce(sum(case when l.allow_fractional then 1 else l.quantity end), 0),
      'subtotal', coalesce(sum(round(l.quantity * l.price, 2)) filter (where l.for_sale), 0))
      from lines l);
end $$;

-- Sets a line's quantity (0 removes it) and returns the cart.
create or replace function public.cart_set_item(
  p_organization_id uuid, p_token text, p_variant_id uuid, p_quantity numeric) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_cart uuid;
  v_frac boolean;
  v_max  numeric;
begin
  perform public.assert_module(p_organization_id, 'storefront');
  select p.allow_fractional into v_frac
    from public.product_variants v join public.products p on p.id = v.product_id
   where v.id = p_variant_id and v.organization_id = p_organization_id and v.is_active and p.status = 'active';
  if not found then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'this item is not for sale';
  end if;
  if p_quantity is null or p_quantity < 0 or (not v_frac and p_quantity <> trunc(p_quantity)) then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'quantity must be zero or more, in whole units for this item';
  end if;
  select coalesce((settings->>'checkout_max_line_quantity')::numeric, 20) into v_max
    from public.organizations where id = p_organization_id;
  if p_quantity > v_max then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = format('at most %s of one item per order', v_max);
  end if;

  v_cart := public._cart_id(p_organization_id, p_token, true);
  if p_quantity = 0 then
    delete from public.cart_items where cart_id = v_cart and variant_id = p_variant_id;
  else
    insert into public.cart_items (cart_id, organization_id, variant_id, quantity)
    values (v_cart, p_organization_id, p_variant_id, p_quantity)
    on conflict (cart_id, variant_id) do update set quantity = excluded.quantity;
  end if;
  update public.carts set updated_at = now() where id = v_cart;
  return public.cart_get(p_organization_id, p_token);
end $$;

create or replace function public.cart_clear(p_organization_id uuid, p_token text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_cart uuid := public._cart_id(p_organization_id, p_token, false);
begin
  if v_cart is not null then
    delete from public.cart_items where cart_id = v_cart;
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- Delivery fee
-- ---------------------------------------------------------------------------
-- settings.delivery_fee (default 0) and settings.free_delivery_over (optional),
-- judged on what the goods cost after discounts, including tax.
create or replace function public._apply_fulfilment(p_order uuid, p_method public.fulfilment_method) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_settings jsonb;
  v_goods    numeric;
  v_fee      numeric := 0;
begin
  select o.settings, ord.total into v_settings, v_goods
    from public.orders ord join public.organizations o on o.id = ord.organization_id
   where ord.id = p_order;
  if p_method = 'delivery' then
    v_fee := coalesce((v_settings->>'delivery_fee')::numeric, 0);
    if (v_settings->>'free_delivery_over') is not null and v_goods >= (v_settings->>'free_delivery_over')::numeric then
      v_fee := 0;
    end if;
  end if;
  update public.orders
     set fulfilment_method = p_method,
         total = total - shipping_total + v_fee,
         shipping_total = v_fee
   where id = p_order;
end $$;

-- ---------------------------------------------------------------------------
-- Summary gains fulfilment and contact
-- ---------------------------------------------------------------------------
create or replace function public._order_summary(p_order uuid) returns jsonb
language sql stable security definer set search_path = public, pg_temp as $$
  select jsonb_build_object(
    'order_id', o.id, 'number', o.number, 'status', o.status, 'channel', o.channel,
    'location_id', o.location_id, 'customer_id', o.customer_id,
    'currency_code', o.currency_code, 'tax_inclusive', o.tax_inclusive,
    'subtotal', o.subtotal, 'discount_total', o.discount_total, 'tax_total', o.tax_total,
    'shipping_total', o.shipping_total, 'total', o.total,
    'amount_paid', o.amount_paid, 'amount_refunded', o.amount_refunded,
    'balance_due', greatest(o.total - o.amount_paid, 0),
    'payment_status', o.payment_status,
    'fulfilment_method', o.fulfilment_method, 'contact', o.contact, 'shipping_address', o.shipping_address,
    'intended_payment_method', o.intended_payment_method,
    'reservation_expires_at', o.reservation_expires_at, 'placed_at', o.placed_at,
    'coupon_code', o.coupon_code, 'promo_discount_total', o.promo_discount_total,
    'promotions', coalesce((select jsonb_agg(jsonb_build_object('name', pm.name, 'amount', op.amount) order by op.amount desc)
                             from public.order_promotions op join public.promotions pm on pm.id = op.promotion_id
                            where op.order_id = o.id), '[]'::jsonb),
    'lines', coalesce((
      select jsonb_agg(jsonb_build_object(
               'line_id', ol.id, 'variant_id', ol.variant_id, 'name', ol.product_name,
               'variant', ol.variant_title, 'quantity', ol.quantity, 'unit_price', ol.unit_price,
               'line_subtotal', ol.line_subtotal, 'discount_amount', ol.discount_amount,
               'tax_rate', ol.tax_rate, 'tax_amount', ol.tax_amount, 'line_total', ol.line_total,
               'serials', (select jsonb_agg(su.serial order by su.serial)
                             from public.order_line_units u
                             join public.serial_units su on su.id = u.serial_unit_id
                            where u.order_line_id = ol.id))
             order by ol.position)
        from public.order_lines ol where ol.order_id = o.id), '[]'::jsonb),
    'payments', coalesce((
      select jsonb_agg(jsonb_build_object(
               'payment_id', p.id, 'kind', p.kind, 'method', p.method, 'status', p.status,
               'amount', p.amount, 'tendered', p.tendered, 'change_given', p.change_given,
               'provider', p.provider, 'reference', p.provider_reference, 'at', p.created_at)
             order by p.created_at, p.id)
        from public.payments p where p.order_id = o.id), '[]'::jsonb))
  from public.orders o where o.id = p_order
$$;

-- ---------------------------------------------------------------------------
-- quote_order: price a basket exactly as checkout will, without keeping anything
-- ---------------------------------------------------------------------------
-- A draft order is written with the real pricing code, summarised, and rolled
-- back. The quote can never drift from what checkout charges.
create or replace function public.quote_order(
  p_organization_id uuid, p_lines jsonb, p_fulfilment_method public.fulfilment_method default 'delivery',
  p_coupon text default null, p_channel public.sales_channel default 'online')
returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_loc     uuid;
  v_order   uuid;
  v_result  jsonb;
  v_org     public.organizations%rowtype;
begin
  -- Priced as the channel will sell it, so channel-only promotions show.
  if p_channel = 'online' then
    perform public.assert_module(p_organization_id, 'storefront');
  elsif p_channel = 'mobile_app' then
    perform public.assert_module(p_organization_id, 'mobile_app');
  else
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'quotes are for the online store or the app';
  end if;
  perform set_config('nwsc.coupon', coalesce(p_coupon, ''), true);
  select * into v_org from public.organizations where id = p_organization_id;
  select l.id into v_loc from public.locations l
   where l.organization_id = p_organization_id and l.is_active and l.sells_online
   order by l.fulfilment_priority, l.code limit 1;
  if v_loc is null then
    raise exception using errcode = 'NC006', message = 'INVALID_STATE', detail = 'no location fulfils online orders';
  end if;

  begin
    insert into public.orders (organization_id, number, channel, location_id, status, currency_code, tax_inclusive)
    values (p_organization_id, 'QUOTE-' || gen_random_uuid(), p_channel, v_loc, 'pending_payment',
            v_org.currency_code, v_org.prices_include_tax)
    returning id into v_order;
    perform public._write_order_lines(p_organization_id, v_order, p_lines, null, false);
    perform public._apply_fulfilment(v_order, p_fulfilment_method);
    v_result := public._order_summary(v_order);
    raise exception using errcode = 'NCQ00', message = 'QUOTE_ROLLBACK';
  exception when sqlstate 'NCQ00' then
    null;  -- the draft is gone; v_result survives
  end;

  return v_result - 'order_id' - 'number' - 'status' - 'location_id' - 'customer_id' - 'payments'
                  - 'amount_paid' - 'amount_refunded' - 'payment_status' - 'reservation_expires_at'
                  - 'placed_at' - 'contact' - 'shipping_address' - 'intended_payment_method';
end $$;

-- ---------------------------------------------------------------------------
-- Customer profiles for people who sign up online
-- ---------------------------------------------------------------------------
-- Creates (or updates the name on) the signed-in user's customer record. A phone
-- number already used by another customer - say, one created at the counter - is
-- not attached: linking an online login to someone's in-store history needs a
-- verified number, which comes with SMS verification.
create or replace function public.ensure_customer_profile(
  p_organization_id uuid, p_full_name text default null, p_phone text default null) returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_id    uuid;
  v_email text;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'PERMISSION_DENIED', detail = 'sign in first';
  end if;
  if p_phone is not null and p_phone !~ '^\+[1-9][0-9]{6,14}$' then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'phone must be in international form, e.g. +94771234567';
  end if;
  select email into v_email from auth.users where id = auth.uid();

  select id into v_id from public.customers where organization_id = p_organization_id and auth_user_id = auth.uid();
  if v_id is null then
    insert into public.customers (organization_id, auth_user_id, full_name, email, phone)
    values (p_organization_id, auth.uid(), nullif(btrim(p_full_name), ''),
            case when not exists (select 1 from public.customers c
                                   where c.organization_id = p_organization_id and lower(c.email) = lower(v_email))
                 then v_email end,
            case when p_phone is not null and not exists (select 1 from public.customers c
                                   where c.organization_id = p_organization_id and c.phone = p_phone)
                 then p_phone end)
    returning id into v_id;
  elsif nullif(btrim(p_full_name), '') is not null then
    update public.customers set full_name = btrim(p_full_name) where id = v_id;
  end if;
  return v_id;
end $$;

-- ---------------------------------------------------------------------------
-- checkout: the storefront's order command
-- ---------------------------------------------------------------------------
-- p_contact    = {full_name, phone (+94...), email?}
-- p_fulfilment = {method: delivery|pickup, address?: {line1, line2?, city, postcode?}}
-- p_payment_method:
--   cash_on_delivery  (pay on delivery / at pickup) -> confirmed now, stock leaves
--   bank_transfer     -> held for settings.bank_transfer_hold_hours (default 24) until staff record it
--   online_gateway    -> held for the normal checkout window until the gateway webhook confirms
create or replace function public.checkout(
  p_organization_id uuid,
  p_lines           jsonb,
  p_idempotency_key text,
  p_contact         jsonb,
  p_fulfilment      jsonb,
  p_payment_method  public.payment_method,
  p_channel         public.sales_channel default 'online',
  p_note            text default null,
  p_coupon          text default null) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_settings jsonb;
  v_method   public.fulfilment_method;
  v_summary  jsonb;
  v_order    uuid;
  v_customer uuid;
  v_until    timestamptz;
  v_address  jsonb;
begin
  select settings into v_settings from public.organizations where id = p_organization_id;
  if not found then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'organization';
  end if;

  -- contact
  if coalesce(btrim(p_contact->>'full_name'), '') = '' then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'please give your name';
  end if;
  if coalesce(p_contact->>'phone', '') !~ '^\+[1-9][0-9]{6,14}$' then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'please give a phone number we can reach you on';
  end if;
  if coalesce(p_contact->>'email', '') <> '' and p_contact->>'email' !~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'that email address does not look right';
  end if;

  -- fulfilment
  v_method := case p_fulfilment->>'method' when 'delivery' then 'delivery' when 'pickup' then 'pickup' end::public.fulfilment_method;
  if v_method is null then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'choose delivery or pickup';
  end if;
  if v_method = 'delivery' then
    if not coalesce((v_settings->>'delivery_enabled')::boolean, true) then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'this store does not deliver';
    end if;
    v_address := p_fulfilment->'address';
    if coalesce(btrim(v_address->>'line1'), '') = '' or coalesce(btrim(v_address->>'city'), '') = '' then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'a delivery address needs a street and a city';
    end if;
  elsif not coalesce((v_settings->>'pickup_enabled')::boolean, true) then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'this store does not offer pickup';
  end if;

  -- payment method
  if p_payment_method = 'cash_on_delivery' and not coalesce((v_settings->>'allow_cash_on_delivery')::boolean, true)
     or p_payment_method = 'bank_transfer' and coalesce(v_settings->>'bank_transfer_details', '') = ''
     or p_payment_method = 'online_gateway' and not coalesce((v_settings->>'online_payments_enabled')::boolean, false)
     or p_payment_method not in ('cash_on_delivery', 'bank_transfer', 'online_gateway') then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'that payment method is not available';
  end if;

  perform set_config('nwsc.coupon', coalesce(p_coupon, ''), true);
  v_summary := public.start_checkout(p_organization_id, p_lines, p_idempotency_key, p_channel, null, p_note);
  v_order := (v_summary->>'order_id')::uuid;
  if v_summary ? 'replayed' then
    return public._order_summary(v_order)
           || jsonb_build_object('access_token', (select access_token from public.orders where id = v_order), 'replayed', true);
  end if;

  -- A signed-in shopper gets (or keeps) their customer record.
  v_customer := (v_summary->>'customer_id')::uuid;
  if v_customer is null and auth.uid() is not null and auth.role() = 'authenticated' then
    v_customer := public.ensure_customer_profile(p_organization_id, p_contact->>'full_name', p_contact->>'phone');
  end if;

  update public.orders
     set customer_id = v_customer,
         contact = jsonb_strip_nulls(jsonb_build_object(
           'full_name', btrim(p_contact->>'full_name'), 'phone', p_contact->>'phone',
           'email', nullif(btrim(coalesce(p_contact->>'email', '')), ''))),
         shipping_address = case when v_method = 'delivery' then v_address end,
         intended_payment_method = p_payment_method
   where id = v_order;
  perform public._apply_fulfilment(v_order, v_method);

  if p_payment_method = 'bank_transfer' then
    v_until := now() + make_interval(hours => least(greatest(coalesce((v_settings->>'bank_transfer_hold_hours')::int, 24), 1), 168));
    update public.orders set reservation_expires_at = v_until where id = v_order;
    update public.stock_reservations set expires_at = v_until
     where source_type = 'order' and source_id = v_order and status = 'active';
  elsif p_payment_method = 'cash_on_delivery' then
    perform public._confirm_order(v_order);
  end if;

  return public._order_summary(v_order)
         || jsonb_build_object('access_token', (select access_token from public.orders where id = v_order));
end $$;

-- The order page for a guest: the id plus the private token from checkout.
create or replace function public.get_order_by_token(p_order_id uuid, p_token text) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  v_token text;
begin
  select access_token into v_token from public.orders where id = p_order_id;
  if v_token is null or p_token is null or v_token <> p_token then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'order';
  end if;
  -- The link is the buyer's proof, so it also carries any gift cards they bought
  -- (issued once the order is paid) and the points it earned.
  return public._order_summary(p_order_id) || jsonb_build_object(
    'gift_cards', coalesce((select jsonb_agg(jsonb_build_object('code', g.code, 'value', g.initial_value, 'balance', g.balance) order by g.created_at)
                              from public.gift_cards g join public.order_lines ol on ol.id = g.order_line_id
                             where ol.order_id = p_order_id), '[]'::jsonb),
    'points_earned', (select points from public.loyalty_ledger where source_type = 'order_earned' and source_id = p_order_id));
end $$;

-- ---------------------------------------------------------------------------
-- Catalogue read models
-- ---------------------------------------------------------------------------
create or replace function public.storefront_categories(p_organization_id uuid)
returns table (id uuid, parent_id uuid, name text, slug text, sort_order int, product_count bigint)
language sql stable security definer set search_path = public, pg_temp as $$
  select c.id, c.parent_id, c.name, c.slug, c.position,
         (select count(*) from public.products p where p.category_id = c.id and p.status = 'active')
    from public.categories c
   where c.organization_id = p_organization_id and c.is_active
   order by c.position, c.name
$$;

-- Listing with facets. Facets are counted over the whole scope (category +
-- search), before brand/price/spec filters, so every option stays visible.
-- p_filters = {"brands": ["slug", ...], "min_price": n, "max_price": n,
--              "in_stock": true, "attributes": {"<attribute_id>": ["value", ...]}}
-- p_sort = relevance | newest | price_asc | price_desc | name
create or replace function public.storefront_catalog(
  p_organization_id uuid,
  p_category_slug   text default null,
  p_query           text default null,
  p_filters         jsonb default '{}'::jsonb,
  p_sort            text default 'newest',
  p_limit           int default 24,
  p_offset          int default 0) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  v_cats   uuid[];
  v_q      text := nullif(btrim(coalesce(p_query, '')), '');
  v_f      jsonb := coalesce(p_filters, '{}'::jsonb);
  v_brands text[] := array(select jsonb_array_elements_text(coalesce(v_f->'brands', '[]'::jsonb)));
  v_min    numeric := (v_f->>'min_price')::numeric;
  v_max    numeric := (v_f->>'max_price')::numeric;
  v_stock  boolean := coalesce((v_f->>'in_stock')::boolean, false);
  v_attrs  jsonb := coalesce(v_f->'attributes', '{}'::jsonb);
begin
  if p_category_slug is not null then
    with recursive tree as (
      select c.id from public.categories c
       where c.organization_id = p_organization_id and c.slug = p_category_slug and c.is_active
      union all
      select c.id from public.categories c join tree t on c.parent_id = t.id where c.is_active)
    select array_agg(id) into v_cats from tree;
    if v_cats is null then
      return jsonb_build_object('total', 0, 'items', '[]'::jsonb, 'facets',
        jsonb_build_object('brands', '[]'::jsonb, 'attributes', '[]'::jsonb, 'price', null));
    end if;
  end if;

  return (
    with avail as (
      select a.variant_id, a.available from public.storefront_availability(p_organization_id, null) a),
    scope as (
      select p.id, p.name, p.slug, p.summary, p.created_at, b.slug as brand_slug, b.name as brand_name,
             min(v.price) as min_price, max(v.price) as max_price,
             (array_agg(v.compare_at_price order by v.price))[1] as compare_at_price,
             count(v.id) as variant_count,
             coalesce(sum(av.available), 0) > 0 as in_stock,
             case when v_q is null then 0
                  when lower(p.name) = lower(v_q) then 3
                  when p.name ilike v_q || '%' then 2
                  else 1 end as relevance
        from public.products p
        join public.product_variants v on v.product_id = p.id and v.is_active
        left join public.brands b on b.id = p.brand_id and b.is_active
        left join avail av on av.variant_id = v.id
       where p.organization_id = p_organization_id and p.status = 'active'
         and (v_cats is null or p.category_id = any (v_cats))
         and (v_q is null
              or p.name ilike '%' || v_q || '%' or p.summary ilike '%' || v_q || '%' or b.name ilike '%' || v_q || '%'
              or exists (select 1 from public.product_variants x
                          where x.product_id = p.id and x.is_active and (x.sku ilike v_q || '%' or x.barcode = v_q)))
       group by p.id, b.slug, b.name),
    filtered as (
      select s.* from scope s
       where (cardinality(v_brands) = 0 or s.brand_slug = any (v_brands))
         and (v_min is null or s.max_price >= v_min)
         and (v_max is null or s.min_price <= v_max)
         and (not v_stock or s.in_stock)
         and not exists (
           select 1 from jsonb_each(v_attrs) f
            where jsonb_typeof(f.value) = 'array' and jsonb_array_length(f.value) > 0
              and not exists (
                select 1 from public.product_attribute_values pav
                 where pav.product_id = s.id and pav.attribute_id::text = f.key
                   and (pav.value #>> '{}') in (select jsonb_array_elements_text(f.value))))),
    page as (
      select f.* from filtered f
       order by
         case when p_sort = 'relevance' or (p_sort is null and v_q is not null) then f.relevance end desc nulls last,
         case when p_sort = 'price_asc' then f.min_price end asc nulls last,
         case when p_sort = 'price_desc' then f.min_price end desc nulls last,
         case when p_sort = 'name' then f.name end asc nulls last,
         f.created_at desc, f.id
       limit least(greatest(p_limit, 1), 96) offset greatest(p_offset, 0))
    select jsonb_build_object(
      'total', (select count(*) from filtered),
      'items', coalesce((select jsonb_agg(jsonb_build_object(
                  'id', pg.id, 'slug', pg.slug, 'name', pg.name, 'summary', pg.summary,
                  'brand', pg.brand_name, 'min_price', pg.min_price, 'max_price', pg.max_price,
                  'compare_at_price', pg.compare_at_price, 'variant_count', pg.variant_count, 'in_stock', pg.in_stock,
                  'image', (select m.storage_path from public.product_media m where m.product_id = pg.id order by m.position limit 1))
                ) from page pg), '[]'::jsonb),
      'facets', jsonb_build_object(
        'brands', coalesce((select jsonb_agg(jsonb_build_object('slug', x.brand_slug, 'name', x.brand_name, 'count', x.n) order by x.brand_name)
                              from (select brand_slug, brand_name, count(*) n from scope where brand_slug is not null group by 1, 2) x), '[]'::jsonb),
        'price', (select jsonb_build_object('min', min(min_price), 'max', max(max_price)) from scope),
        'attributes', coalesce((
          select jsonb_agg(jsonb_build_object('id', ad.id, 'code', ad.code, 'label', ad.label, 'unit', ad.unit, 'values', vals.v) order by ad.label)
            from public.attribute_definitions ad
            join lateral (
              select jsonb_agg(jsonb_build_object('value', t.val, 'count', t.n) order by t.val) v
                from (select pav.value #>> '{}' val, count(*) n
                        from public.product_attribute_values pav join scope s on s.id = pav.product_id
                       where pav.attribute_id = ad.id group by 1) t) vals on vals.v is not null
           where ad.organization_id = p_organization_id and ad.is_filterable), '[]'::jsonb))));
end $$;

create or replace function public.storefront_product(p_organization_id uuid, p_slug text) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  p public.products%rowtype;
begin
  select * into p from public.products
   where organization_id = p_organization_id and slug = p_slug and status = 'active';
  if not found then
    return null;
  end if;

  return jsonb_build_object(
    'id', p.id, 'slug', p.slug, 'name', p.name, 'summary', p.summary, 'description', p.description,
    'tracking_mode', p.tracking_mode, 'unit_of_measure', p.unit_of_measure, 'allow_fractional', p.allow_fractional,
    'seo', p.seo,
    'brand', (select jsonb_build_object('name', b.name, 'slug', b.slug) from public.brands b where b.id = p.brand_id and b.is_active),
    'breadcrumbs', coalesce((
      with recursive up(id, parent_id, name, slug, depth) as (
        select c.id, c.parent_id, c.name, c.slug, 0 from public.categories c where c.id = p.category_id and c.is_active
        union all
        select c.id, c.parent_id, c.name, c.slug, up.depth + 1 from public.categories c join up on c.id = up.parent_id)
      select jsonb_agg(jsonb_build_object('name', name, 'slug', slug) order by depth desc) from up), '[]'::jsonb),
    'options', coalesce((
      select jsonb_agg(jsonb_build_object('name', o.name,
               'values', (select jsonb_agg(v.value order by v.position) from public.product_option_values v where v.option_id = o.id))
             order by o.position)
        from public.product_options o where o.product_id = p.id), '[]'::jsonb),
    'variants', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', v.id, 'title', v.title, 'sku', v.sku, 'price', v.price, 'compare_at_price', v.compare_at_price,
               'available', coalesce(a.available, 0),
               'option_values', (select jsonb_agg(ov.value order by po.position)
                                   from public.variant_option_values vov
                                   join public.product_option_values ov on ov.id = vov.option_value_id
                                   join public.product_options po on po.id = ov.option_id
                                  where vov.variant_id = v.id))
             order by v.position)
        from public.product_variants v
        left join public.storefront_availability(p_organization_id,
                    array(select id from public.product_variants where product_id = p.id)) a on a.variant_id = v.id
       where v.product_id = p.id and v.is_active), '[]'::jsonb),
    'media', coalesce((select jsonb_agg(jsonb_build_object('path', m.storage_path, 'alt', m.alt_text, 'variant_id', m.variant_id) order by m.position)
                         from public.product_media m where m.product_id = p.id), '[]'::jsonb),
    'specifications', coalesce((
      select jsonb_agg(jsonb_build_object('label', ad.label, 'value', pav.value, 'unit', ad.unit, 'type', ad.data_type) order by ca.position nulls last, ad.label)
        from public.product_attribute_values pav
        join public.attribute_definitions ad on ad.id = pav.attribute_id
        left join public.category_attributes ca on ca.attribute_id = ad.id and ca.category_id = p.category_id
       where pav.product_id = p.id), '[]'::jsonb),
    'related', coalesce((
      select jsonb_agg(r) from (
        select jsonb_build_object('slug', rp.slug, 'name', rp.name,
                 'min_price', (select min(price) from public.product_variants where product_id = rp.id and is_active),
                 'image', (select storage_path from public.product_media where product_id = rp.id order by position limit 1)) r
          from public.products rp
         where rp.organization_id = p_organization_id and rp.status = 'active' and rp.id <> p.id
           and rp.category_id is not distinct from p.category_id and p.category_id is not null
         order by rp.created_at desc limit 4) x), '[]'::jsonb));
end $$;

-- Public details the storefront shows: how to pay and collect, never internal settings.
create or replace function public.storefront_settings(p_organization_id uuid) returns jsonb
language sql stable security definer set search_path = public, pg_temp as $$
  select jsonb_build_object(
    'name', o.name, 'currency_code', o.currency_code, 'prices_include_tax', o.prices_include_tax,
    'delivery_enabled', coalesce((o.settings->>'delivery_enabled')::boolean, true),
    'pickup_enabled', coalesce((o.settings->>'pickup_enabled')::boolean, true),
    'delivery_fee', coalesce((o.settings->>'delivery_fee')::numeric, 0),
    'free_delivery_over', (o.settings->>'free_delivery_over')::numeric,
    'allow_cash_on_delivery', coalesce((o.settings->>'allow_cash_on_delivery')::boolean, true),
    'bank_transfer_details', nullif(o.settings->>'bank_transfer_details', ''),
    'online_payments_enabled', coalesce((o.settings->>'online_payments_enabled')::boolean, false),
    'contact_phone', o.settings->>'contact_phone', 'contact_email', o.settings->>'contact_email',
    'returns_enabled', public.module_enabled(o.id, 'returns'), 'return_days', (o.settings->>'return_days')::int,
    'coupons_enabled', public.module_enabled(o.id, 'promotions'),
    'web_enabled', public.module_enabled(o.id, 'storefront'), 'app_enabled', public.module_enabled(o.id, 'mobile_app'),
    'loyalty_enabled', public.module_enabled(o.id, 'loyalty'),
    'pickup_locations', coalesce((select jsonb_agg(jsonb_build_object('name', l.name, 'address', l.address, 'phone', l.phone) order by l.fulfilment_priority)
                                    from public.locations l where l.organization_id = o.id and l.is_active and l.sells_online and l.kind = 'store'), '[]'::jsonb))
    from public.organizations o
   where o.id = p_organization_id and (public.module_enabled(o.id, 'storefront') or public.module_enabled(o.id, 'mobile_app'))
$$;

-- Settings the admin may now set for the store.
create or replace function public.update_organization_settings(p_organization_id uuid, p_changes jsonb)
returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_allowed constant text[] := array['checkout_hold_minutes', 'checkout_max_line_quantity', 'discount_limits',
                                     'receipt_footer', 'contact_email', 'contact_phone', 'low_stock_default',
                                     'delivery_enabled', 'pickup_enabled', 'delivery_fee', 'free_delivery_over',
                                     'allow_cash_on_delivery', 'bank_transfer_details', 'bank_transfer_hold_hours'];
  v_settings jsonb;
  v_key text;
begin
  perform public.assert_permission(p_organization_id, 'settings.manage');

  for v_key in select jsonb_object_keys(coalesce(p_changes->'settings', '{}'::jsonb)) loop
    if not (v_key = any (v_allowed)) then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = format('unknown setting %s', v_key);
    end if;
  end loop;
  if p_changes ? 'name' and coalesce(btrim(p_changes->>'name'), '') = '' then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'the business needs a name';
  end if;
  if coalesce((p_changes->'settings'->>'checkout_hold_minutes')::int, 15) not between 1 and 120 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'checkout hold is 1 to 120 minutes';
  end if;
  if coalesce((p_changes->'settings'->>'bank_transfer_hold_hours')::int, 24) not between 1 and 168 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'bank transfer hold is 1 to 168 hours';
  end if;
  if coalesce((p_changes->'settings'->>'delivery_fee')::numeric, 0) < 0
     or coalesce((p_changes->'settings'->>'free_delivery_over')::numeric, 0) < 0 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'delivery amounts cannot be negative';
  end if;
  if exists (select 1 from jsonb_each_text(coalesce(p_changes->'settings'->'discount_limits', '{}'::jsonb)) d
              where d.key::text not in ('owner','admin','manager','cashier','stock_keeper','viewer')
                 or d.value::numeric < 0 or d.value::numeric > 100) then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'discount limits are 0-100 per role';
  end if;

  update public.organizations
     set name = coalesce(nullif(btrim(p_changes->>'name'), ''), name),
         prices_include_tax = coalesce((p_changes->>'prices_include_tax')::boolean, prices_include_tax),
         timezone = coalesce(nullif(p_changes->>'timezone', ''), timezone),
         settings = jsonb_strip_nulls(settings || coalesce(p_changes->'settings', '{}'::jsonb))
   where id = p_organization_id
  returning settings into v_settings;
  return v_settings;
end $$;

-- ---------------------------------------------------------------------------
-- Grants
-- ---------------------------------------------------------------------------
revoke execute on all functions in schema public from public, anon, authenticated;
grant execute on all functions in schema public to service_role;

grant execute on function
  public.is_platform_admin(), public.role_permissions(public.staff_role), public.is_member(uuid),
  public.has_permission(uuid, text), public.has_location_access(uuid, uuid),
  public.module_enabled(uuid, public.module_key), public.owns_order(uuid), public.slugify(text)
  to anon, authenticated;

grant execute on function
  public.storefront_organization(text),
  public.storefront_settings(uuid),
  public.storefront_availability(uuid, uuid[]),
  public.storefront_categories(uuid),
  public.storefront_catalog(uuid, text, text, jsonb, text, int, int),
  public.storefront_product(uuid, text),
  public.cart_get(uuid, text),
  public.cart_set_item(uuid, text, uuid, numeric),
  public.cart_clear(uuid, text),
  public.quote_order(uuid, jsonb, public.fulfilment_method, text, public.sales_channel),
  public.checkout(uuid, jsonb, text, jsonb, jsonb, public.payment_method, public.sales_channel, text, text),
  public.get_order_by_token(uuid, text),
  public.start_checkout(uuid, jsonb, text, public.sales_channel, uuid, text)
  to anon, authenticated;

grant execute on function
  public.ensure_customer_profile(uuid, text, text),
  public.cancel_order(uuid, text),
  public.place_order(uuid, public.sales_channel, jsonb, uuid, text, text, jsonb, jsonb, uuid),
  public.confirm_order(uuid),
  public.receive_stock(uuid, jsonb, text, text),
  public.adjust_stock(uuid, uuid, numeric, public.movement_type, text, text[], text, date, numeric),
  public.lookup_serial(uuid, text),
  public.inventory_integrity_report(uuid),
  public.upsert_staff_member(uuid, uuid, public.staff_role, uuid[], boolean),
  public.set_my_pin(uuid, text),
  public.request_override(uuid, uuid, text, text),
  public.record_payment(uuid, public.payment_method, numeric, text, text),
  public.refund_payment(uuid, numeric, public.payment_method, text, text),
  public.adjust_store_credit(uuid, numeric, text),
  public.save_product(uuid, jsonb),
  public.update_organization_settings(uuid, jsonb),
  public.my_workspaces(),
  public.list_staff(uuid),
  public.add_staff_by_email(uuid, text, public.staff_role, uuid[]),
  public.search_variants(uuid, text, uuid, int),
  public.stock_overview(uuid, uuid, text, boolean, int, int),
  public.stock_movements(uuid, uuid, uuid, int),
  public.set_low_stock_threshold(uuid, uuid, numeric),
  public.dashboard_summary(uuid, timestamptz, timestamptz)
  to authenticated;

-- ======================================================================
-- 0011_pos.sql
-- ======================================================================
-- 0011_pos.sql
-- Phase 5: the counter. Tills (terminals), cashier shifts with a cash float,
-- paid in / paid out / cash drops, sales tied to the shift that took them,
-- held sales, receipts and X / Z shift reports.
--
-- Selling itself is place_order(): stock, prices, discounts, approvals and
-- tender rules are the same tested code whichever screen calls it.

set check_function_bodies = off;

create type public.shift_status as enum ('open', 'closed');
create type public.cash_movement_kind as enum ('paid_in', 'paid_out', 'drop');

-- ---------------------------------------------------------------------------
-- Tills
-- ---------------------------------------------------------------------------
create table public.pos_terminals (
  id              uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete cascade,
  location_id     uuid not null,
  code            text not null check (code ~ '^[A-Z0-9][A-Z0-9_-]{0,15}$'),
  name            text not null check (length(btrim(name)) > 0),
  is_active       boolean not null default true,
  created_at      timestamptz not null default now(),
  unique (organization_id, code),
  unique (organization_id, id),
  foreign key (organization_id, location_id) references public.locations (organization_id, id)
);

create or replace function public.pos_terminals_enforce_module() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  perform public.assert_module(new.organization_id, 'pos');
  return new;
end $$;
create trigger pos_terminals_module_guard before insert on public.pos_terminals
  for each row execute function public.pos_terminals_enforce_module();
create trigger pos_terminals_audit after insert or update on public.pos_terminals
  for each row execute function public.audit_row();

-- ---------------------------------------------------------------------------
-- Shifts
-- ---------------------------------------------------------------------------
create table public.pos_shifts (
  id              uuid primary key default gen_random_uuid(),
  organization_id uuid not null,
  terminal_id     uuid not null,
  location_id     uuid not null,
  number          text not null,
  status          public.shift_status not null default 'open',
  opened_by       uuid not null default auth.uid(),
  opened_at       timestamptz not null default now(),
  opening_float   numeric(14,2) not null check (opening_float >= 0),
  closed_by       uuid,
  closed_at       timestamptz,
  expected_cash   numeric(14,2),
  counted_cash    numeric(14,2) check (counted_cash is null or counted_cash >= 0),
  variance        numeric(14,2),
  close_note      text,
  unique (organization_id, number),
  unique (organization_id, id),
  foreign key (organization_id, terminal_id) references public.pos_terminals (organization_id, id),
  foreign key (organization_id, location_id) references public.locations (organization_id, id),
  check ((status = 'closed') = (closed_at is not null))
);
-- One open shift per till.
create unique index pos_shifts_one_open on public.pos_shifts (terminal_id) where status = 'open';
create index pos_shifts_org_time_idx on public.pos_shifts (organization_id, opened_at desc);

create table public.pos_cash_movements (
  id              bigint generated always as identity primary key,
  organization_id uuid not null,
  shift_id        uuid not null,
  kind            public.cash_movement_kind not null,
  amount          numeric(14,2) not null check (amount > 0),
  reason          text not null check (length(btrim(reason)) >= 3),
  created_by      uuid default auth.uid(),
  created_at      timestamptz not null default now(),
  foreign key (organization_id, shift_id) references public.pos_shifts (organization_id, id)
);
create trigger pos_cash_movements_append_only before update or delete on public.pos_cash_movements
  for each row execute function public.prevent_mutation();

-- Sales and money taken at a till know which till and shift.
alter table public.orders
  add column terminal_id uuid,
  add column shift_id    uuid,
  add foreign key (organization_id, terminal_id) references public.pos_terminals (organization_id, id),
  add foreign key (organization_id, shift_id) references public.pos_shifts (organization_id, id);
create index orders_shift_idx on public.orders (shift_id) where shift_id is not null;

alter table public.payments
  add column shift_id uuid,
  add foreign key (organization_id, shift_id) references public.pos_shifts (organization_id, id);
create index payments_shift_idx on public.payments (shift_id) where shift_id is not null;

-- ---------------------------------------------------------------------------
-- Held sales (a parked ticket: no stock is held, prices are rechecked on resume)
-- ---------------------------------------------------------------------------
create table public.pos_held_sales (
  id              uuid primary key default gen_random_uuid(),
  organization_id uuid not null,
  terminal_id     uuid not null,
  label           text,
  lines           jsonb not null check (jsonb_typeof(lines) = 'array' and jsonb_array_length(lines) > 0),
  customer_id     uuid,
  created_by      uuid not null default auth.uid(),
  created_at      timestamptz not null default now(),
  foreign key (organization_id, terminal_id) references public.pos_terminals (organization_id, id) on delete cascade,
  foreign key (organization_id, customer_id) references public.customers (organization_id, id) on delete set null (customer_id)
);
create index pos_held_sales_terminal_idx on public.pos_held_sales (terminal_id, created_at);

-- ---------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------
-- The caller's own open shift, locked. Only the cashier who opened a shift sells on it.
create or replace function public._my_open_shift(p_shift_id uuid) returns public.pos_shifts
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  s public.pos_shifts%rowtype;
begin
  select * into s from public.pos_shifts where id = p_shift_id for share;
  if not found then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'shift';
  end if;
  perform public.assert_module(s.organization_id, 'pos');
  perform public.assert_permission(s.organization_id, 'pos.sell');
  if s.status <> 'open' then
    raise exception using errcode = 'NC006', message = 'INVALID_STATE', detail = 'this shift is closed - open a new one';
  end if;
  if s.opened_by is distinct from auth.uid() and not public.is_platform_admin() then
    raise exception using errcode = '42501', message = 'PERMISSION_DENIED', detail = 'this shift belongs to another cashier';
  end if;
  return s;
end $$;

create or replace function public._shift_expected_cash(p_shift_id uuid) returns numeric
language sql stable security definer set search_path = public, pg_temp as $$
  select s.opening_float
       + coalesce((select sum(case when p.kind = 'payment' then p.amount else -p.amount end)
                     from public.payments p
                    where p.shift_id = s.id and p.method = 'cash' and p.status = 'captured'), 0)
       + coalesce((select sum(case when m.kind = 'paid_in' then m.amount else -m.amount end)
                     from public.pos_cash_movements m where m.shift_id = s.id), 0)
    from public.pos_shifts s where s.id = p_shift_id
$$;

-- ---------------------------------------------------------------------------
-- Commands
-- ---------------------------------------------------------------------------
create or replace function public.pos_open_shift(p_terminal_id uuid, p_opening_float numeric) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  t public.pos_terminals%rowtype;
  v_id uuid;
begin
  select * into t from public.pos_terminals where id = p_terminal_id and is_active;
  if not found then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'till';
  end if;
  perform public.assert_module(t.organization_id, 'pos');
  perform public.assert_permission(t.organization_id, 'pos.sell');
  perform public.assert_location_access(t.organization_id, t.location_id);
  if p_opening_float is null or p_opening_float < 0 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'count the float in the drawer (0 or more)';
  end if;
  begin
    insert into public.pos_shifts (organization_id, terminal_id, location_id, number, opening_float)
    values (t.organization_id, t.id, t.location_id,
            public.next_document_number(t.organization_id, 'shift', 'SH-'), p_opening_float)
    returning id into v_id;
  exception when unique_violation then
    raise exception using errcode = 'NC006', message = 'INVALID_STATE', detail = 'this till already has an open shift - close it first';
  end;
  return public.pos_shift_summary(v_id);
end $$;

-- A sale at the counter: place_order on the caller's own open shift.
create or replace function public.pos_sale(
  p_shift_id        uuid,
  p_lines           jsonb,
  p_payments        jsonb,
  p_idempotency_key text,
  p_customer_id     uuid default null,
  p_order_discount  jsonb default null,
  p_approval_id     uuid default null,
  p_note            text default null,
  p_coupon          text default null) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  s        public.pos_shifts%rowtype;
  v_result jsonb;
  v_order  uuid;
begin
  s := public._my_open_shift(p_shift_id);
  perform set_config('nwsc.coupon', coalesce(p_coupon, ''), true);
  if p_idempotency_key is null or length(p_idempotency_key) < 8 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'an idempotency key is required';
  end if;

  perform set_config('nwsc.pos_shift', s.id::text, true);
  v_result := public.place_order(s.location_id, 'pos', p_lines, p_customer_id, p_idempotency_key, p_note,
                                 p_payments, p_order_discount, p_approval_id);
  v_order := (v_result->>'order_id')::uuid;

  if not (v_result ? 'replayed') then
    update public.orders set terminal_id = s.terminal_id, shift_id = s.id, fulfilment_method = 'in_store'
     where id = v_order;
    update public.payments set shift_id = s.id where order_id = v_order and shift_id is null;
  end if;
  return v_result || jsonb_build_object('shift_id', s.id);
end $$;

-- Money taken at the till against an earlier order (a phone order collected in store).
create or replace function public.pos_take_payment(
  p_shift_id uuid, p_order_id uuid, p_method public.payment_method, p_amount numeric, p_reference text default null)
returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  s        public.pos_shifts%rowtype;
  v_result jsonb;
begin
  s := public._my_open_shift(p_shift_id);
  v_result := public.record_payment(p_order_id, p_method, p_amount, p_reference, null);
  update public.payments set shift_id = s.id
   where id = (select p.id from public.payments p where p.order_id = p_order_id order by p.created_at desc, p.id desc limit 1)
     and shift_id is null;
  return v_result;
end $$;

create or replace function public.pos_cash_movement(
  p_shift_id uuid, p_kind public.cash_movement_kind, p_amount numeric, p_reason text) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  s public.pos_shifts%rowtype;
begin
  s := public._my_open_shift(p_shift_id);
  if p_amount is null or p_amount <= 0 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'amount must be positive';
  end if;
  if p_reason is null or length(btrim(p_reason)) < 3 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'say what the cash is for';
  end if;
  if p_kind in ('paid_out', 'drop') and p_amount > public._shift_expected_cash(s.id) then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'there is not that much cash in the drawer';
  end if;
  insert into public.pos_cash_movements (organization_id, shift_id, kind, amount, reason)
  values (s.organization_id, s.id, p_kind, p_amount, btrim(p_reason));
  return public.pos_shift_summary(s.id);
end $$;

create or replace function public.pos_close_shift(p_shift_id uuid, p_counted_cash numeric, p_note text default null)
returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  s          public.pos_shifts%rowtype;
  v_expected numeric;
begin
  select * into s from public.pos_shifts where id = p_shift_id for update;
  if not found then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'shift';
  end if;
  if s.status = 'closed' then
    raise exception using errcode = 'NC006', message = 'INVALID_STATE', detail = 'this shift is already closed';
  end if;
  -- The cashier closes their own shift; a manager can close anyone's.
  if s.opened_by = auth.uid() then
    perform public.assert_permission(s.organization_id, 'pos.sell');
  else
    perform public.assert_permission(s.organization_id, 'pos.override');
  end if;
  if p_counted_cash is null or p_counted_cash < 0 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'count the cash in the drawer';
  end if;

  v_expected := public._shift_expected_cash(s.id);
  if p_counted_cash <> v_expected and coalesce(btrim(p_note), '') = '' then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
      detail = format('the drawer is %s by %s - add a note to explain it',
                      case when p_counted_cash > v_expected then 'over' else 'short' end, abs(p_counted_cash - v_expected));
  end if;

  update public.pos_shifts
     set status = 'closed', closed_by = auth.uid(), closed_at = now(), expected_cash = v_expected,
         counted_cash = p_counted_cash, variance = p_counted_cash - v_expected, close_note = nullif(btrim(p_note), '')
   where id = s.id;
  -- Parked tickets on this till do not survive the shift.
  delete from public.pos_held_sales where terminal_id = s.terminal_id;
  return public.pos_shift_summary(s.id);
end $$;

-- X report while open, Z report once closed: the same figures.
create or replace function public.pos_shift_summary(p_shift_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  s public.pos_shifts%rowtype;
begin
  select * into s from public.pos_shifts where id = p_shift_id;
  if not found then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'shift';
  end if;
  if s.opened_by is distinct from auth.uid() and not public.has_permission(s.organization_id, 'reports.view') then
    raise exception using errcode = '42501', message = 'PERMISSION_DENIED', detail = 'reports.view';
  end if;

  return jsonb_build_object(
    'shift_id', s.id, 'number', s.number, 'status', s.status,
    'terminal', (select jsonb_build_object('id', t.id, 'code', t.code, 'name', t.name) from public.pos_terminals t where t.id = s.terminal_id),
    'location', (select l.name from public.locations l where l.id = s.location_id),
    'cashier', (select u.email from auth.users u where u.id = s.opened_by),
    'opened_at', s.opened_at, 'closed_at', s.closed_at,
    'opening_float', s.opening_float,
    'sales', (select jsonb_build_object(
                'count', count(*), 'gross', coalesce(sum(o.subtotal), 0), 'discounts', coalesce(sum(o.discount_total), 0),
                'tax', coalesce(sum(o.tax_total), 0), 'total', coalesce(sum(o.total), 0))
                from public.orders o where o.shift_id = s.id and o.status in ('confirmed', 'completed')),
    'by_method', coalesce((select jsonb_agg(jsonb_build_object('method', x.method, 'taken', x.taken, 'refunded', x.refunded, 'net', x.taken - x.refunded) order by x.method)
                  from (select p.method,
                               coalesce(sum(p.amount) filter (where p.kind = 'payment'), 0) taken,
                               coalesce(sum(p.amount) filter (where p.kind = 'refund'), 0) refunded
                          from public.payments p where p.shift_id = s.id and p.status = 'captured'
                         group by p.method) x), '[]'::jsonb),
    'cash_movements', coalesce((select jsonb_agg(jsonb_build_object('kind', m.kind, 'amount', m.amount, 'reason', m.reason, 'at', m.created_at) order by m.id)
                       from public.pos_cash_movements m where m.shift_id = s.id), '[]'::jsonb),
    'expected_cash', coalesce(s.expected_cash, public._shift_expected_cash(s.id)),
    'counted_cash', s.counted_cash, 'variance', s.variance, 'close_note', s.close_note);
end $$;

create or replace function public.pos_hold_sale(p_shift_id uuid, p_lines jsonb, p_customer_id uuid default null, p_label text default null)
returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  s    public.pos_shifts%rowtype;
  v_id uuid;
begin
  s := public._my_open_shift(p_shift_id);
  -- Validates the lines now so a bad ticket is not parked.
  perform count(*) from public._order_input(s.organization_id, p_lines);
  insert into public.pos_held_sales (organization_id, terminal_id, label, lines, customer_id)
  values (s.organization_id, s.terminal_id, nullif(btrim(p_label), ''), p_lines, p_customer_id)
  returning id into v_id;
  return v_id;
end $$;

-- Takes a held ticket back off the shelf (it is removed; the till rings it up again).
create or replace function public.pos_resume_sale(p_shift_id uuid, p_held_id uuid) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  s public.pos_shifts%rowtype;
  h public.pos_held_sales%rowtype;
begin
  s := public._my_open_shift(p_shift_id);
  delete from public.pos_held_sales where id = p_held_id and terminal_id = s.terminal_id returning * into h;
  if not found then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'held sale (already resumed?)';
  end if;
  return jsonb_build_object('lines', h.lines, 'customer_id', h.customer_id, 'label', h.label);
end $$;

-- Everything a printed or emailed receipt needs.
create or replace function public.pos_receipt(p_order_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  o public.orders%rowtype;
begin
  select * into o from public.orders where id = p_order_id;
  if not found or not (public.has_permission(o.organization_id, 'orders.view') or public.has_permission(o.organization_id, 'pos.sell')) then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'order';
  end if;
  return public._order_summary(o.id) || jsonb_build_object(
    'business', (select jsonb_build_object('name', g.name, 'phone', g.settings->>'contact_phone', 'footer', g.settings->>'receipt_footer')
                   from public.organizations g where g.id = o.organization_id),
    'location', (select jsonb_build_object('name', l.name, 'address', l.address, 'phone', l.phone) from public.locations l where l.id = o.location_id),
    'terminal', (select t.name from public.pos_terminals t where t.id = o.terminal_id),
    'cashier', (select u.email from auth.users u where u.id = o.placed_by),
    'customer', (select jsonb_build_object('name', c.full_name, 'phone', c.phone, 'loyalty_points', c.loyalty_points) from public.customers c where c.id = o.customer_id),
    'gift_cards', coalesce((select jsonb_agg(jsonb_build_object('code', g.code, 'value', g.initial_value) order by g.created_at)
                             from public.gift_cards g join public.order_lines ol on ol.id = g.order_line_id where ol.order_id = o.id), '[]'::jsonb),
    'points_earned', (select points from public.loyalty_ledger where source_type = 'order_earned' and source_id = o.id));
end $$;

-- ---------------------------------------------------------------------------
-- Read models for the POS screen
-- ---------------------------------------------------------------------------
-- The ticket's totals as the sale will charge them (a rolled-back draft through
-- the real pricing code), whether the discount needs a manager, and shelf stock.
create or replace function public.pos_quote(p_shift_id uuid, p_lines jsonb, p_order_discount jsonb default null, p_coupon text default null)
returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  s        public.pos_shifts%rowtype;
  v_org    public.organizations%rowtype;
  v_order  uuid;
  v_pct    numeric;
  v_limit  numeric;
  v_result jsonb;
begin
  s := public._my_open_shift(p_shift_id);
  perform set_config('nwsc.coupon', coalesce(p_coupon, ''), true);
  select * into v_org from public.organizations where id = s.organization_id;
  v_limit := case when public.is_platform_admin() then 100 else coalesce(public._discount_limit(s.organization_id, auth.uid()), 0) end;
  begin
    insert into public.orders (organization_id, number, channel, location_id, status, currency_code, tax_inclusive)
    values (s.organization_id, 'QUOTE-' || gen_random_uuid(), 'pos', s.location_id, 'pending_payment',
            v_org.currency_code, v_org.prices_include_tax)
    returning id into v_order;
    v_pct := public._write_order_lines(s.organization_id, v_order, p_lines, p_order_discount, true);
    v_result := public._order_summary(v_order);
    raise exception using errcode = 'NCQ00', message = 'QUOTE_ROLLBACK';
  exception when sqlstate 'NCQ00' then
    null;
  end;
  return (v_result - 'order_id' - 'number' - 'status' - 'payments' - 'contact' - 'shipping_address'
                   - 'intended_payment_method' - 'reservation_expires_at' - 'placed_at' - 'customer_id')
         || jsonb_build_object(
              'discount_percent', v_pct, 'my_discount_limit', v_limit, 'needs_approval', v_pct > v_limit,
              'stock', coalesce((select jsonb_object_agg(sl.variant_id, sl.on_hand - sl.reserved)
                                   from public.stock_levels sl
                                  where sl.location_id = s.location_id
                                    and sl.variant_id in (select (e->>'variant_id')::uuid from jsonb_array_elements(p_lines) e)), '{}'::jsonb));
end $$;

-- Who may approve at this till (names only; cashiers cannot list staff).
create or replace function public.pos_approvers(p_organization_id uuid)
returns table (user_id uuid, email text, role public.staff_role, discount_limit numeric)
language plpgsql stable security definer set search_path = public, pg_temp as $$
begin
  perform public.assert_permission(p_organization_id, 'pos.sell');
  return query
    select m.user_id, u.email::text, m.role, public._discount_limit(p_organization_id, m.user_id)
      from public.memberships m join auth.users u on u.id = m.user_id
     where m.organization_id = p_organization_id and m.is_active and m.user_id <> auth.uid()
       and public.role_permissions(m.role) && array['*', 'pos.override']
       and exists (select 1 from public.staff_pins sp where sp.organization_id = m.organization_id and sp.user_id = m.user_id)
     order by m.role, u.email;
end $$;

-- What the till screen needs on start: my tills and any shift I left open.
create or replace function public.pos_context(p_organization_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
begin
  perform public.assert_module(p_organization_id, 'pos');
  perform public.assert_permission(p_organization_id, 'pos.sell');
  return jsonb_build_object(
    'terminals', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', t.id, 'code', t.code, 'name', t.name, 'location_id', t.location_id, 'location', l.name,
               'open_shift', (select jsonb_build_object('id', sh.id, 'number', sh.number, 'cashier', u.email,
                                                        'mine', sh.opened_by = auth.uid(), 'opened_at', sh.opened_at)
                                from public.pos_shifts sh join auth.users u on u.id = sh.opened_by
                               where sh.terminal_id = t.id and sh.status = 'open'))
             order by l.name, t.code)
        from public.pos_terminals t join public.locations l on l.id = t.location_id
       where t.organization_id = p_organization_id and t.is_active and l.is_active
         and public.has_location_access(p_organization_id, t.location_id)), '[]'::jsonb),
    'my_open_shift', (select public.pos_shift_summary(sh.id) from public.pos_shifts sh
                       where sh.organization_id = p_organization_id and sh.opened_by = auth.uid() and sh.status = 'open'
                       order by sh.opened_at desc limit 1));
end $$;

-- ---------------------------------------------------------------------------
-- Security
-- ---------------------------------------------------------------------------
alter table public.pos_terminals enable row level security;
alter table public.pos_shifts enable row level security;
alter table public.pos_cash_movements enable row level security;
alter table public.pos_held_sales enable row level security;

grant select on public.pos_terminals, public.pos_shifts, public.pos_cash_movements, public.pos_held_sales to authenticated;
grant insert, update on public.pos_terminals to authenticated;
grant all on public.pos_terminals, public.pos_shifts, public.pos_cash_movements, public.pos_held_sales to service_role;
revoke all on public.pos_terminals, public.pos_shifts, public.pos_cash_movements, public.pos_held_sales from anon;
revoke insert, update, delete, truncate on public.pos_shifts, public.pos_cash_movements, public.pos_held_sales from authenticated;

create policy pos_terminals_read on public.pos_terminals for select
  using (public.has_permission(organization_id, 'pos.sell') or public.has_permission(organization_id, 'reports.view'));
create policy pos_terminals_insert on public.pos_terminals for insert
  with check (public.has_permission(organization_id, 'locations.manage'));
create policy pos_terminals_update on public.pos_terminals for update
  using (public.has_permission(organization_id, 'locations.manage'))
  with check (public.has_permission(organization_id, 'locations.manage'));
create policy pos_shifts_read on public.pos_shifts for select
  using (opened_by = auth.uid() or public.has_permission(organization_id, 'reports.view'));
create policy pos_cash_movements_read on public.pos_cash_movements for select
  using (public.has_permission(organization_id, 'reports.view')
         or exists (select 1 from public.pos_shifts s where s.id = shift_id and s.opened_by = auth.uid()));
create policy pos_held_sales_read on public.pos_held_sales for select
  using (public.has_permission(organization_id, 'pos.sell'));

revoke execute on all functions in schema public from public, anon, authenticated;
grant execute on all functions in schema public to service_role;

grant execute on function
  public.is_platform_admin(), public.role_permissions(public.staff_role), public.is_member(uuid),
  public.has_permission(uuid, text), public.has_location_access(uuid, uuid),
  public.module_enabled(uuid, public.module_key), public.owns_order(uuid), public.slugify(text)
  to anon, authenticated;

grant execute on function
  public.storefront_organization(text), public.storefront_settings(uuid), public.storefront_availability(uuid, uuid[]),
  public.storefront_categories(uuid), public.storefront_catalog(uuid, text, text, jsonb, text, int, int),
  public.storefront_product(uuid, text), public.cart_get(uuid, text), public.cart_set_item(uuid, text, uuid, numeric),
  public.cart_clear(uuid, text), public.quote_order(uuid, jsonb, public.fulfilment_method, text, public.sales_channel),
  public.checkout(uuid, jsonb, text, jsonb, jsonb, public.payment_method, public.sales_channel, text, text),
  public.get_order_by_token(uuid, text), public.start_checkout(uuid, jsonb, text, public.sales_channel, uuid, text)
  to anon, authenticated;

grant execute on function
  public.ensure_customer_profile(uuid, text, text),
  public.cancel_order(uuid, text),
  public.place_order(uuid, public.sales_channel, jsonb, uuid, text, text, jsonb, jsonb, uuid),
  public.confirm_order(uuid),
  public.receive_stock(uuid, jsonb, text, text),
  public.adjust_stock(uuid, uuid, numeric, public.movement_type, text, text[], text, date, numeric),
  public.lookup_serial(uuid, text),
  public.inventory_integrity_report(uuid),
  public.upsert_staff_member(uuid, uuid, public.staff_role, uuid[], boolean),
  public.set_my_pin(uuid, text),
  public.request_override(uuid, uuid, text, text),
  public.record_payment(uuid, public.payment_method, numeric, text, text),
  public.refund_payment(uuid, numeric, public.payment_method, text, text),
  public.adjust_store_credit(uuid, numeric, text),
  public.save_product(uuid, jsonb),
  public.update_organization_settings(uuid, jsonb),
  public.my_workspaces(),
  public.list_staff(uuid),
  public.add_staff_by_email(uuid, text, public.staff_role, uuid[]),
  public.search_variants(uuid, text, uuid, int),
  public.stock_overview(uuid, uuid, text, boolean, int, int),
  public.stock_movements(uuid, uuid, uuid, int),
  public.set_low_stock_threshold(uuid, uuid, numeric),
  public.dashboard_summary(uuid, timestamptz, timestamptz),
  public.pos_open_shift(uuid, numeric),
  public.pos_sale(uuid, jsonb, jsonb, text, uuid, jsonb, uuid, text, text),
  public.pos_take_payment(uuid, uuid, public.payment_method, numeric, text),
  public.pos_cash_movement(uuid, public.cash_movement_kind, numeric, text),
  public.pos_close_shift(uuid, numeric, text),
  public.pos_shift_summary(uuid),
  public.pos_hold_sale(uuid, jsonb, uuid, text),
  public.pos_resume_sale(uuid, uuid),
  public.pos_receipt(uuid),
  public.pos_quote(uuid, jsonb, jsonb, text),
  public.pos_approvers(uuid),
  public.pos_context(uuid)
  to authenticated;

alter publication supabase_realtime add table public.pos_held_sales;

-- ======================================================================
-- 0012_returns_warranty.sql
-- ======================================================================
-- 0012_returns_warranty.sql
-- Phase 6: returns, exchanges, inspection, warranty.
--
-- Returns
--   * refunds are what the customer paid for that line (discount and tax
--     included, delivery excluded), pro rata, with rounding settled on the last unit
--   * returned goods go to INSPECTION, never straight back on sale; inspection
--     decides restock / damaged / service / write-off (restocking at the counter
--     needs inventory.adjust)
--   * serialised units must be the exact units sold on that line
--   * exchanges happen in one transaction: the return's value pays toward the new
--     sale as 'return_credit', which clients cannot use anywhere else
-- Warranty (module 'warranty')
--   * products carry warranty_months; each sold line keeps a snapshot
--   * one lookup by serial / IMEI, order number or phone, across every channel
--   * claims with a status history

set check_function_bodies = off;

alter type public.payment_method add value if not exists 'return_credit';

create type public.return_status as enum ('requested', 'received', 'cancelled');
create type public.return_disposition as enum ('pending_inspection', 'restock', 'damaged', 'service', 'write_off');
create type public.warranty_claim_status as enum (
  'open', 'received', 'in_repair', 'awaiting_parts', 'ready', 'replaced', 'refunded', 'rejected', 'closed');

-- ---------------------------------------------------------------------------
-- Warranty on products and sold lines
-- ---------------------------------------------------------------------------
alter table public.products
  add column warranty_months int check (warranty_months is null or warranty_months between 0 and 120),
  add column warranty_terms  text;

alter table public.order_lines add column warranty_months int;

-- Snapshot at sale time: changing a product's warranty later does not change what was sold.
create or replace function public.order_lines_snapshot_warranty() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if new.warranty_months is null then
    select p.warranty_months into new.warranty_months
      from public.product_variants v join public.products p on p.id = v.product_id
     where v.id = new.variant_id;
  end if;
  return new;
end $$;
create trigger order_lines_warranty before insert on public.order_lines
  for each row execute function public.order_lines_snapshot_warranty();

-- ---------------------------------------------------------------------------
-- Returns
-- ---------------------------------------------------------------------------
create table public.returns (
  id              uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete cascade,
  number          text not null,
  order_id        uuid not null,
  status          public.return_status not null,
  channel         public.sales_channel not null,
  location_id     uuid,
  customer_id     uuid,
  shift_id        uuid,
  reason          text,
  refund_total    numeric(14,2) not null default 0 check (refund_total >= 0),
  idempotency_key text,
  requested_at    timestamptz not null default now(),
  received_at     timestamptz,
  received_by     uuid,
  created_by      uuid default auth.uid(),
  exchange_order_id uuid,
  unique (organization_id, number),
  unique (organization_id, id),
  foreign key (organization_id, order_id) references public.orders (organization_id, id),
  foreign key (organization_id, location_id) references public.locations (organization_id, id),
  foreign key (organization_id, customer_id) references public.customers (organization_id, id),
  foreign key (organization_id, shift_id) references public.pos_shifts (organization_id, id),
  foreign key (organization_id, exchange_order_id) references public.orders (organization_id, id),
  check ((status = 'received') = (received_at is not null and location_id is not null))
);
create unique index returns_idempotency_uq on public.returns (organization_id, idempotency_key) where idempotency_key is not null;
create index returns_order_idx on public.returns (order_id);
create index returns_org_time_idx on public.returns (organization_id, requested_at desc);

create table public.return_lines (
  id              uuid primary key default gen_random_uuid(),
  organization_id uuid not null,
  return_id       uuid not null,
  order_line_id   uuid not null,
  variant_id      uuid not null,
  quantity        numeric(14,3) not null check (quantity > 0),
  serial_unit_id  uuid,
  batch_id        uuid,
  line_refund     numeric(14,2) not null check (line_refund >= 0),
  unit_cost       numeric(14,4),
  reason          text,
  disposition     public.return_disposition not null default 'pending_inspection',
  inspected_by    uuid,
  inspected_at    timestamptz,
  inspection_note text,
  unique (organization_id, id),
  foreign key (organization_id, return_id) references public.returns (organization_id, id) on delete cascade,
  foreign key (organization_id, order_line_id) references public.order_lines (organization_id, id),
  foreign key (organization_id, variant_id) references public.product_variants (organization_id, id),
  foreign key (organization_id, serial_unit_id) references public.serial_units (organization_id, id),
  foreign key (organization_id, batch_id) references public.batches (organization_id, id),
  check (serial_unit_id is null or quantity = 1)
);
create index return_lines_return_idx on public.return_lines (return_id);
create index return_lines_order_line_idx on public.return_lines (order_line_id);
create index return_lines_pending_idx on public.return_lines (organization_id) where disposition in ('pending_inspection', 'service');

-- ---------------------------------------------------------------------------
-- Warranty claims
-- ---------------------------------------------------------------------------
create table public.warranty_claims (
  id              uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete cascade,
  number          text not null,
  order_line_id   uuid not null,
  serial_unit_id  uuid,
  customer_id     uuid,
  status          public.warranty_claim_status not null default 'open',
  issue           text not null check (length(btrim(issue)) >= 3),
  within_warranty boolean not null,
  expires_on      date,
  resolution      text,
  created_by      uuid default auth.uid(),
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  unique (organization_id, number),
  unique (organization_id, id),
  foreign key (organization_id, order_line_id) references public.order_lines (organization_id, id),
  foreign key (organization_id, serial_unit_id) references public.serial_units (organization_id, id),
  foreign key (organization_id, customer_id) references public.customers (organization_id, id)
);
create index warranty_claims_org_idx on public.warranty_claims (organization_id, created_at desc);
create index warranty_claims_line_idx on public.warranty_claims (order_line_id);

create table public.warranty_claim_events (
  id              bigint generated always as identity primary key,
  organization_id uuid not null,
  claim_id        uuid not null,
  status          public.warranty_claim_status not null,
  note            text,
  created_by      uuid default auth.uid(),
  created_at      timestamptz not null default now(),
  foreign key (organization_id, claim_id) references public.warranty_claims (organization_id, id) on delete cascade
);
create trigger warranty_claim_events_append_only before update or delete on public.warranty_claim_events
  for each row execute function public.prevent_mutation();
create trigger warranty_claims_touch before update on public.warranty_claims
  for each row execute function public.touch_updated_at();

-- ---------------------------------------------------------------------------
-- Return helpers
-- ---------------------------------------------------------------------------
-- Quantity of an order line already returned or asked to be returned.
create or replace function public._returned_quantity(p_order_line uuid) returns numeric
language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce(sum(rl.quantity), 0)
    from public.return_lines rl join public.returns r on r.id = rl.return_id
   where rl.order_line_id = p_order_line and r.status <> 'cancelled'
$$;

create or replace function public._returned_value(p_order_line uuid) returns numeric
language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce(sum(rl.line_refund), 0)
    from public.return_lines rl join public.returns r on r.id = rl.return_id
   where rl.order_line_id = p_order_line and r.status <> 'cancelled'
$$;

-- Adds lines to a return and returns their refund value.
-- p_lines = [{order_line_id, quantity, serials?: [...], reason?, disposition?: 'restock'}]
create or replace function public._add_return_lines(p_return uuid, p_lines jsonb, p_allow_restock boolean) returns numeric
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  r        public.returns%rowtype;
  ol       public.order_lines%rowtype;
  e        jsonb;
  v_qty    numeric;
  v_left   numeric;
  v_value  numeric;
  v_total  numeric := 0;
  v_mode   public.tracking_mode;
  v_frac   boolean;
  v_disp   public.return_disposition;
  v_batch  uuid;
  v_cost   numeric;
  v_serial text;
  v_unit   uuid;
  v_i      int;
begin
  select * into r from public.returns where id = p_return;
  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'choose at least one item to return';
  end if;

  for e in select x from jsonb_array_elements(p_lines) x order by x->>'order_line_id' loop
    select * into ol from public.order_lines
     where id = (e->>'order_line_id')::uuid and order_id = r.order_id for update;
    if not found then
      raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'that item is not on this order';
    end if;
    select p.tracking_mode, p.allow_fractional into v_mode, v_frac
      from public.product_variants v join public.products p on p.id = v.product_id where v.id = ol.variant_id;
    if exists (select 1 from public.product_variants v join public.products p on p.id = v.product_id
                where v.id = ol.variant_id and p.is_gift_card) then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'gift cards cannot be returned';
    end if;

    v_qty := (e->>'quantity')::numeric;
    v_left := ol.quantity - public._returned_quantity(ol.id);
    if v_qty is null or v_qty <= 0 or v_qty > v_left then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
        detail = format('%s: %s can still be returned', ol.product_name, v_left);
    end if;
    if not v_frac and v_qty <> trunc(v_qty) then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = format('%s is returned in whole units', ol.product_name);
    end if;

    v_disp := case when e->>'disposition' = 'restock' then 'restock' else 'pending_inspection' end;
    if v_disp = 'restock' and not p_allow_restock then
      raise exception using errcode = '42501', message = 'PERMISSION_DENIED',
        detail = 'returned goods go to inspection; only stock staff can put them straight back on sale';
    end if;

    -- The refund for these units: pro rata of what the line cost the customer;
    -- the last units returned take whatever rounding is left.
    v_value := case when v_qty = v_left then ol.line_total - public._returned_value(ol.id)
                    else round(ol.line_total * v_qty / ol.quantity, 2) end;

    -- What the goods cost when they were sold (for a correct restock valuation).
    select case when sum(-m.quantity) > 0 then sum(-m.quantity * m.unit_cost) / sum(-m.quantity) end,
           (array_agg(m.batch_id order by m.quantity))[1]
      into v_cost, v_batch
      from public.inventory_movements m
     where m.source_type = 'order' and m.source_id = r.order_id and m.variant_id = ol.variant_id and m.movement_type = 'sale';

    if v_mode = 'serial' then
      if coalesce(jsonb_array_length(e->'serials'), 0) <> v_qty then
        raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
          detail = format('%s: give the serial number of each unit coming back', ol.product_name);
      end if;
      v_i := 0;
      for v_serial in select btrim(x) from jsonb_array_elements_text(e->'serials') x loop
        v_i := v_i + 1;
        select su.id into v_unit
          from public.order_line_units u join public.serial_units su on su.id = u.serial_unit_id
         where u.order_line_id = ol.id and upper(su.serial) = upper(v_serial)
           and not exists (select 1 from public.return_lines x join public.returns rr on rr.id = x.return_id
                            where x.serial_unit_id = su.id and rr.status <> 'cancelled');
        if v_unit is null then
          raise exception using errcode = 'NC004', message = 'SERIAL_UNAVAILABLE',
            detail = format('%s was not sold on this order, or has already been returned', v_serial);
        end if;
        insert into public.return_lines
          (organization_id, return_id, order_line_id, variant_id, quantity, serial_unit_id, line_refund, unit_cost, reason, disposition)
        values
          (r.organization_id, r.id, ol.id, ol.variant_id, 1, v_unit,
           case when v_i = v_qty then v_value - round(v_value / v_qty, 2) * (v_qty - 1) else round(v_value / v_qty, 2) end,
           (select su.unit_cost from public.serial_units su where su.id = v_unit), nullif(btrim(e->>'reason'), ''), v_disp);
      end loop;
    else
      insert into public.return_lines
        (organization_id, return_id, order_line_id, variant_id, quantity, batch_id, line_refund, unit_cost, reason, disposition)
      values
        (r.organization_id, r.id, ol.id, ol.variant_id, v_qty, case when v_mode = 'batch' then v_batch end, v_value, v_cost,
         nullif(btrim(e->>'reason'), ''), v_disp);
    end if;
    v_total := v_total + v_value;
  end loop;

  update public.returns set refund_total = refund_total + v_total where id = r.id;
  return v_total;
end $$;

-- Puts one inspected return line back on sale at the return's location.
create or replace function public._restock_return_line(p_line uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  l public.return_lines%rowtype;
  r public.returns%rowtype;
begin
  select * into l from public.return_lines where id = p_line;
  select * into r from public.returns where id = l.return_id;
  if public._tracking_mode(l.variant_id) = 'non_stock' then
    return;  -- a service or fee: nothing goes back on the shelf
  end if;
  if l.serial_unit_id is not null then
    update public.serial_units set status = 'available', location_id = r.location_id where id = l.serial_unit_id;
  end if;
  insert into public.inventory_movements
    (organization_id, location_id, variant_id, batch_id, serial_unit_id, movement_type, quantity, unit_cost, source_type, source_id, note)
  values
    (l.organization_id, r.location_id, l.variant_id, l.batch_id, l.serial_unit_id, 'sale_return', l.quantity, l.unit_cost,
     'return', r.id, 'returned by customer, ' || r.number);
end $$;

-- Goods physically arrive: serial units come back into the building (inspection),
-- lines marked restock go straight back on sale.
create or replace function public._receive_return_goods(p_return uuid, p_location uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  l record;
begin
  update public.returns set status = 'received', location_id = p_location, received_at = now(), received_by = auth.uid()
   where id = p_return;
  for l in select * from public.return_lines where return_id = p_return order by variant_id, id loop
    if l.serial_unit_id is not null then
      update public.serial_units set status = 'inspection', location_id = p_location where id = l.serial_unit_id;
    end if;
    if l.disposition = 'restock' then
      perform public._restock_return_line(l.id);
      update public.return_lines set inspected_by = auth.uid(), inspected_at = now(),
             inspection_note = coalesce(inspection_note, 'restocked on return') where id = l.id;
    end if;
  end loop;
end $$;

-- Money back for a received return. p_refunds = [{method, amount, reference?}].
-- The refunds must add up to the return's value (or what is left of what was
-- actually paid, if less). 'return_credit' is only accepted from an exchange.
create or replace function public._refund_return(p_return uuid, p_refunds jsonb, p_shift uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  r        public.returns%rowtype;
  o        public.orders%rowtype;
  v_due    numeric;
  v_sum    numeric;
  e        jsonb;
  v_method public.payment_method;
  v_amount numeric;
begin
  select * into r from public.returns where id = p_return;
  select * into o from public.orders where id = r.order_id for update;
  v_due := least(r.refund_total, o.amount_paid - o.amount_refunded);
  p_refunds := coalesce(p_refunds, '[]'::jsonb);
  -- A single refund without an amount takes exactly what is due, so screens
  -- never have to reproduce the rounding rules.
  if jsonb_typeof(p_refunds) = 'array' and jsonb_array_length(p_refunds) = 1 and not (p_refunds->0 ? 'amount') then
    p_refunds := jsonb_build_array(p_refunds->0 || jsonb_build_object('amount', v_due));
  end if;
  select coalesce(sum((x->>'amount')::numeric), 0) into v_sum from jsonb_array_elements(p_refunds) x;
  if round(v_sum, 2) <> round(v_due, 2) then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
      detail = json_build_object('refund_due', v_due, 'refunds_given', v_sum)::text;
  end if;

  for e in select x from jsonb_array_elements(p_refunds) x loop
    v_method := (e->>'method')::public.payment_method;
    v_amount := (e->>'amount')::numeric;
    continue when v_amount = 0;
    if v_amount < 0 then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'refund amounts are positive';
    end if;
    if v_method = 'return_credit' and coalesce(current_setting('nwsc.exchange_return', true), '') <> r.id::text then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'return credit is only used by an exchange';
    end if;
    if v_method = 'store_credit' then
      if o.customer_id is null then
        raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'store credit needs a customer on the order';
      end if;
      insert into public.store_credit_ledger (organization_id, customer_id, amount, reason, source_type, source_id)
      values (o.organization_id, o.customer_id, v_amount, 'Return ' || r.number || ' on order ' || o.number, 'return', r.id);
    end if;
    insert into public.payments (organization_id, order_id, kind, method, amount, provider_reference, note, shift_id, captured_at)
    values (o.organization_id, o.id, 'refund', v_method, v_amount, coalesce(nullif(e->>'reference', ''), r.number),
            'Return ' || r.number, p_shift, now());
  end loop;
  perform public._refresh_payment_status(o.id);
  perform public._return_loyalty(r.id);  -- 0014
end $$;

create or replace function public._return_summary(p_return uuid) returns jsonb
language sql stable security definer set search_path = public, pg_temp as $$
  select jsonb_build_object(
    'return_id', r.id, 'number', r.number, 'status', r.status, 'channel', r.channel,
    'order_id', r.order_id, 'order_number', o.number, 'location_id', r.location_id,
    'customer_id', r.customer_id, 'reason', r.reason, 'refund_total', r.refund_total,
    'requested_at', r.requested_at, 'received_at', r.received_at, 'exchange_order_id', r.exchange_order_id,
    'lines', coalesce((select jsonb_agg(jsonb_build_object(
                'return_line_id', rl.id, 'order_line_id', rl.order_line_id, 'name', ol.product_name, 'variant', ol.variant_title,
                'quantity', rl.quantity, 'serial', su.serial, 'line_refund', rl.line_refund, 'reason', rl.reason,
                'disposition', rl.disposition, 'inspected_at', rl.inspected_at, 'inspection_note', rl.inspection_note)
              order by ol.position, su.serial)
              from public.return_lines rl
              join public.order_lines ol on ol.id = rl.order_line_id
              left join public.serial_units su on su.id = rl.serial_unit_id
             where rl.return_id = r.id), '[]'::jsonb),
    'refunds', coalesce((select jsonb_agg(jsonb_build_object('method', p.method, 'amount', p.amount, 'at', p.created_at) order by p.created_at)
                           from public.payments p where p.order_id = r.order_id and p.kind = 'refund' and p.note = 'Return ' || r.number), '[]'::jsonb))
  from public.returns r join public.orders o on o.id = r.order_id
  where r.id = p_return
$$;

create or replace function public._new_return(
  p_order public.orders, p_status public.return_status, p_channel public.sales_channel,
  p_reason text, p_idempotency_key text, p_shift uuid) returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_id uuid;
begin
  if p_order.status not in ('confirmed', 'completed') then
    raise exception using errcode = 'NC006', message = 'INVALID_STATE', detail = 'only confirmed orders can be returned';
  end if;
  insert into public.returns (organization_id, number, order_id, status, channel, customer_id, reason, idempotency_key, shift_id)
  values (p_order.organization_id, public.next_document_number(p_order.organization_id, 'return', 'RET-'), p_order.id,
          p_status, p_channel, p_order.customer_id, nullif(btrim(p_reason), ''), p_idempotency_key, p_shift)
  returning id into v_id;
  return v_id;
end $$;

-- Within settings.return_days of the sale (no setting = no limit)?
create or replace function public._within_return_window(p_order public.orders) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select (o.settings->>'return_days') is null
      or coalesce(p_order.confirmed_at, p_order.placed_at) >= now() - make_interval(days => (o.settings->>'return_days')::int)
    from public.organizations o where o.id = p_order.organization_id
$$;

-- ---------------------------------------------------------------------------
-- Return commands
-- ---------------------------------------------------------------------------
-- Staff take a return (admin: any channel's order, any time).
create or replace function public.create_return(
  p_order_id uuid, p_location_id uuid, p_lines jsonb, p_refunds jsonb,
  p_reason text default null, p_idempotency_key text default null) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  o    public.orders%rowtype;
  v_id uuid;
begin
  select * into o from public.orders where id = p_order_id for update;
  if not found then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'order';
  end if;
  perform public.assert_module(o.organization_id, 'returns');
  perform public.assert_permission(o.organization_id, 'orders.manage');
  perform public.assert_location_access(o.organization_id, p_location_id);
  if not exists (select 1 from public.locations where id = p_location_id and organization_id = o.organization_id and is_active) then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'location';
  end if;
  if p_idempotency_key is not null then
    select id into v_id from public.returns where organization_id = o.organization_id and idempotency_key = p_idempotency_key;
    if found then return public._return_summary(v_id) || '{"replayed": true}'::jsonb; end if;
  end if;

  v_id := public._new_return(o, 'requested', 'admin_order', p_reason, p_idempotency_key, null);
  perform public._add_return_lines(v_id, p_lines, public.has_permission(o.organization_id, 'inventory.adjust'));
  perform public._receive_return_goods(v_id, p_location_id);
  perform public._refund_return(v_id, p_refunds, null);
  return public._return_summary(v_id);
end $$;

-- A return at the till, on the cashier's open shift; cash refunds leave this drawer.
create or replace function public.pos_return(
  p_shift_id uuid, p_order_id uuid, p_lines jsonb, p_refunds jsonb,
  p_idempotency_key text, p_reason text default null) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  s    public.pos_shifts%rowtype;
  o    public.orders%rowtype;
  v_id uuid;
begin
  s := public._my_open_shift(p_shift_id);
  select * into o from public.orders where id = p_order_id and organization_id = s.organization_id for update;
  if not found then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'order';
  end if;
  perform public.assert_module(o.organization_id, 'returns');
  if not public._within_return_window(o) and not public.has_permission(o.organization_id, 'orders.manage') then
    raise exception using errcode = 'NC006', message = 'INVALID_STATE', detail = 'this sale is outside the return period - a manager must take the return';
  end if;
  if p_idempotency_key is null or length(p_idempotency_key) < 8 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'an idempotency key is required';
  end if;
  select id into v_id from public.returns where organization_id = o.organization_id and idempotency_key = p_idempotency_key;
  if found then return public._return_summary(v_id) || '{"replayed": true}'::jsonb; end if;

  v_id := public._new_return(o, 'requested', 'pos', p_reason, p_idempotency_key, s.id);
  perform public._add_return_lines(v_id, p_lines, public.has_permission(o.organization_id, 'inventory.adjust'));
  perform public._receive_return_goods(v_id, s.location_id);
  perform public._refund_return(v_id, p_refunds, s.id);
  return public._return_summary(v_id);
end $$;

-- Return and buy again in one go. The return's value pays toward the new sale;
-- any value left over is refunded (p_leftover_method, default cash from the drawer).
create or replace function public.pos_exchange(
  p_shift_id        uuid,
  p_order_id        uuid,
  p_return_lines    jsonb,
  p_new_lines       jsonb,
  p_payments        jsonb,
  p_idempotency_key text,
  p_leftover_method public.payment_method default 'cash',
  p_customer_id     uuid default null,
  p_reason          text default null) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  s        public.pos_shifts%rowtype;
  o        public.orders%rowtype;
  v_ret    uuid;
  v_value  numeric;
  v_quote  jsonb;
  v_total  numeric;
  v_credit numeric;
  v_sale   jsonb;
begin
  s := public._my_open_shift(p_shift_id);
  select * into o from public.orders where id = p_order_id and organization_id = s.organization_id for update;
  if not found then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'order';
  end if;
  perform public.assert_module(o.organization_id, 'returns');
  if not public._within_return_window(o) and not public.has_permission(o.organization_id, 'orders.manage') then
    raise exception using errcode = 'NC006', message = 'INVALID_STATE', detail = 'this sale is outside the return period - a manager must take the return';
  end if;
  if p_idempotency_key is null or length(p_idempotency_key) < 8 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'an idempotency key is required';
  end if;
  if p_leftover_method not in ('cash', 'card', 'bank_transfer', 'store_credit') then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'left-over value goes back as cash, card, transfer or store credit';
  end if;
  select id into v_ret from public.returns where organization_id = o.organization_id and idempotency_key = p_idempotency_key;
  if found then
    return jsonb_build_object('return', public._return_summary(v_ret), 'replayed', true,
      'sale', (select public._order_summary(exchange_order_id) from public.returns where id = v_ret));
  end if;

  -- 1. the return (goods back into inspection or stock)
  v_ret := public._new_return(o, 'requested', 'pos', coalesce(p_reason, 'exchange'), p_idempotency_key, s.id);
  v_value := public._add_return_lines(v_ret, p_return_lines, public.has_permission(o.organization_id, 'inventory.adjust'));
  perform public._receive_return_goods(v_ret, s.location_id);

  -- 2. how much of it the new sale can use
  v_quote := public.pos_quote(s.id, p_new_lines, null);
  v_total := (v_quote->>'total')::numeric;
  v_credit := least(least(v_value, o.amount_paid - o.amount_refunded), v_total);

  -- 3. refund the returned value: as credit toward the new sale, the rest as chosen
  perform set_config('nwsc.exchange_return', v_ret::text, true);
  perform public._refund_return(v_ret, jsonb_build_array(
    jsonb_build_object('method', 'return_credit', 'amount', v_credit),
    jsonb_build_object('method', p_leftover_method, 'amount', least(v_value, o.amount_paid - o.amount_refunded) - v_credit)), s.id);

  -- 4. the new sale, paid first by the return credit
  perform set_config('nwsc.return_credit', v_credit::text, true);
  v_sale := public.pos_sale(s.id, p_new_lines,
              case when v_credit > 0 then jsonb_build_array(jsonb_build_object('method', 'return_credit', 'amount', v_credit, 'reference', (select number from public.returns where id = v_ret)))
                   else '[]'::jsonb end || coalesce(p_payments, '[]'::jsonb),
              p_idempotency_key || '-sale', coalesce(p_customer_id, o.customer_id), null, null,
              'Exchange for ' || (select number from public.returns where id = v_ret));
  perform set_config('nwsc.return_credit', '', true);
  perform set_config('nwsc.exchange_return', '', true);

  update public.returns set exchange_order_id = (v_sale->>'order_id')::uuid where id = v_ret;
  return jsonb_build_object('return', public._return_summary(v_ret), 'sale', v_sale,
                            'credit_used', v_credit, 'leftover_refunded', least(v_value, o.amount_paid - o.amount_refunded) - v_credit,
                            'leftover_method', p_leftover_method);
end $$;

-- A customer asks to return part of an online order (their order page token, or signed in).
create or replace function public.request_return(p_order_id uuid, p_token text, p_lines jsonb, p_reason text)
returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  o    public.orders%rowtype;
  v_id uuid;
begin
  select * into o from public.orders where id = p_order_id for update;
  if not found or not (o.access_token = coalesce(p_token, '') or public.owns_order(o.id)) then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'order';
  end if;
  perform public.assert_module(o.organization_id, 'returns');
  if o.channel not in ('online', 'mobile_app') then
    raise exception using errcode = 'NC006', message = 'INVALID_STATE', detail = 'bring in-store purchases back to the shop';
  end if;
  if not public._within_return_window(o) then
    raise exception using errcode = 'NC006', message = 'INVALID_STATE', detail = 'this order is outside the return period';
  end if;
  if p_reason is null or length(btrim(p_reason)) < 3 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'tell us why you are returning it';
  end if;
  -- Customers cannot choose serial numbers or restock; staff confirm on receipt.
  if exists (select 1 from jsonb_array_elements(p_lines) e where e ? 'serials' or e ? 'disposition') then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'choose items and quantities only';
  end if;
  if exists (select 1 from jsonb_array_elements(p_lines) e
               join public.order_lines ol on ol.id = (e->>'order_line_id')::uuid
               join public.product_variants v on v.id = ol.variant_id join public.products p on p.id = v.product_id
              where p.tracking_mode = 'serial') then
    -- Which unit comes back has to be checked by staff against the serial sold.
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'items with serial numbers are returned in store or by calling us';
  end if;

  v_id := public._new_return(o, 'requested', o.channel, p_reason, null, null);
  perform public._add_return_lines(v_id, p_lines, false);
  return public._return_summary(v_id);
end $$;

-- Staff receive a requested return and refund it.
create or replace function public.receive_return(p_return_id uuid, p_location_id uuid, p_refunds jsonb) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  r public.returns%rowtype;
begin
  select * into r from public.returns where id = p_return_id for update;
  if not found then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'return';
  end if;
  perform public.assert_permission(r.organization_id, 'orders.manage');
  perform public.assert_location_access(r.organization_id, p_location_id);
  if r.status <> 'requested' then
    raise exception using errcode = 'NC006', message = 'INVALID_STATE', detail = format('this return is %s', r.status);
  end if;
  perform public._receive_return_goods(r.id, p_location_id);
  perform public._refund_return(r.id, p_refunds, null);
  return public._return_summary(r.id);
end $$;

create or replace function public.cancel_return(p_return_id uuid, p_reason text) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  r public.returns%rowtype;
begin
  select * into r from public.returns where id = p_return_id for update;
  if not found then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'return';
  end if;
  perform public.assert_permission(r.organization_id, 'orders.manage');
  if r.status <> 'requested' then
    raise exception using errcode = 'NC006', message = 'INVALID_STATE', detail = 'only a requested return can be cancelled';
  end if;
  update public.returns set status = 'cancelled', reason = concat_ws(E'\n', reason, 'Cancelled: ' || p_reason) where id = r.id;
  return public._return_summary(r.id);
end $$;

-- Inspection decides what happens to returned goods.
create or replace function public.inspect_return_line(p_return_line_id uuid, p_disposition public.return_disposition, p_note text default null)
returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  l public.return_lines%rowtype;
  r public.returns%rowtype;
begin
  select * into l from public.return_lines where id = p_return_line_id for update;
  if not found then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'return line';
  end if;
  select * into r from public.returns where id = l.return_id;
  perform public.assert_permission(l.organization_id, 'inventory.adjust');
  perform public.assert_location_access(l.organization_id, r.location_id);
  if r.status <> 'received' then
    raise exception using errcode = 'NC006', message = 'INVALID_STATE', detail = 'the goods have not been received yet';
  end if;
  if l.disposition not in ('pending_inspection', 'service') then
    raise exception using errcode = 'NC006', message = 'INVALID_STATE', detail = format('already decided: %s', l.disposition);
  end if;
  if p_disposition = 'pending_inspection' then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'choose restock, damaged, service or write-off';
  end if;
  if p_disposition in ('damaged', 'write_off') and coalesce(btrim(p_note), '') = '' then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'say what is wrong with it';
  end if;

  if p_disposition = 'restock' then
    perform public._restock_return_line(l.id);
  elsif l.serial_unit_id is not null then
    update public.serial_units
       set status = case p_disposition when 'damaged' then 'damaged' when 'write_off' then 'written_off' else 'inspection' end::public.serial_status
     where id = l.serial_unit_id;
  end if;
  update public.return_lines
     set disposition = p_disposition, inspected_by = auth.uid(), inspected_at = now(), inspection_note = nullif(btrim(p_note), '')
   where id = l.id;
  return public._return_summary(r.id);
end $$;

-- ---------------------------------------------------------------------------
-- 'return_credit' as a tender: only inside an exchange, never more than the credit.
-- Replaces _take_payments to recognise it (everything else unchanged).
-- ---------------------------------------------------------------------------
create or replace function public._take_payments(
  p_org          uuid,
  p_order        uuid,
  p_payments     jsonb,
  p_require_full boolean) returns numeric
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  o             public.orders%rowtype;
  v_due         numeric;
  v_noncash     numeric;
  v_cash_given  numeric;
  v_cash_taken  numeric;
  v_credit_cap  numeric := nullif(current_setting('nwsc.return_credit', true), '')::numeric;
  v_card        uuid;
  v_points      int;
  e             jsonb;
begin
  select * into o from public.orders where id = p_order;
  v_due := o.total - o.amount_paid;

  if p_payments is null or p_payments = 'null'::jsonb then
    p_payments := '[]'::jsonb;
  end if;
  if jsonb_typeof(p_payments) <> 'array' or exists (
       select 1 from jsonb_array_elements(p_payments) x
        where jsonb_typeof(x) <> 'object'
           or coalesce(x->>'method', '') not in ('cash', 'card', 'bank_transfer', 'qr', 'store_credit', 'return_credit',
                                                 'gift_card', 'loyalty_points')
           or coalesce((x->>'amount')::numeric, 0) <= 0) then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
      detail = 'payments are [{method: cash|card|bank_transfer|qr|store_credit|gift_card|loyalty_points, amount > 0}]';
  end if;
  if (select coalesce(sum((x->>'amount')::numeric), 0) from jsonb_array_elements(p_payments) x where x->>'method' = 'return_credit')
     > coalesce(v_credit_cap, 0) then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'return credit is only used by an exchange';
  end if;

  select coalesce(sum((x->>'amount')::numeric) filter (where x->>'method' <> 'cash'), 0),
         coalesce(sum((x->>'amount')::numeric) filter (where x->>'method' = 'cash'), 0)
    into v_noncash, v_cash_given
    from jsonb_array_elements(p_payments) x;

  if v_noncash > v_due then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
      detail = 'card, transfer, QR and store credit cannot exceed the amount due';
  end if;
  v_cash_taken := least(v_cash_given, v_due - v_noncash);

  if p_require_full and v_noncash + v_cash_taken < v_due then
    raise exception using errcode = 'NC007', message = 'PAYMENT_INCOMPLETE',
      detail = json_build_object('due', v_due, 'tendered', v_noncash + v_cash_given)::text;
  end if;

  for e in select x from jsonb_array_elements(p_payments) x where x->>'method' <> 'cash' loop
    if e->>'method' = 'store_credit' then
      if o.customer_id is null then
        raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
          detail = 'store credit needs a customer on the order';
      end if;
      insert into public.store_credit_ledger (organization_id, customer_id, amount, reason, source_type, source_id)
      values (p_org, o.customer_id, -(e->>'amount')::numeric, 'Spent on order ' || o.number, 'order', o.id);
    elsif e->>'method' = 'gift_card' then
      perform public.assert_module(p_org, 'loyalty');
      v_card := (select g.id from public.gift_cards g where g.organization_id = p_org and g.code = upper(btrim(coalesce(e->>'code', ''))));
      if v_card is null then
        raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'no gift card has that code';
      end if;
      insert into public.gift_card_ledger (organization_id, gift_card_id, amount, reason, order_id)
      values (p_org, v_card, -(e->>'amount')::numeric, 'Spent on ' || o.number, o.id);
      e := e || jsonb_build_object('reference', 'card ...' || right(upper(btrim(e->>'code')), 4));
    elsif e->>'method' = 'loyalty_points' then
      perform public.assert_module(p_org, 'loyalty');
      if o.customer_id is null then
        raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'points need a customer on the order';
      end if;
      v_points := ceil((e->>'amount')::numeric / nullif(public._loyalty_setting(p_org, 'loyalty_point_value', 1), 0));
      if v_points < public._loyalty_setting(p_org, 'loyalty_min_redeem', 0) then
        raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
          detail = format('at least %s points must be used at once', public._loyalty_setting(p_org, 'loyalty_min_redeem', 0));
      end if;
      insert into public.loyalty_ledger (organization_id, customer_id, points, reason, source_type, source_id)
      values (p_org, o.customer_id, -v_points, 'Spent on ' || o.number, 'order_spent', o.id);
      e := e || jsonb_build_object('reference', v_points || ' points');
    end if;
    insert into public.payments (organization_id, order_id, method, amount, provider_reference, captured_at)
    values (p_org, o.id, (e->>'method')::public.payment_method, (e->>'amount')::numeric,
            nullif(e->>'reference', ''), now());
  end loop;

  if v_cash_taken > 0 then
    insert into public.payments (organization_id, order_id, method, amount, tendered, change_given, captured_at)
    values (p_org, o.id, 'cash', v_cash_taken, v_cash_given, v_cash_given - v_cash_taken, now());
  end if;

  perform public._refresh_payment_status(o.id);
  return v_cash_given - v_cash_taken;
end $$;

-- ---------------------------------------------------------------------------
-- Warranty
-- ---------------------------------------------------------------------------
-- Finds purchases by serial / IMEI, order number or customer phone, in every
-- channel, with warranty dates, returns and claims.
create or replace function public.warranty_lookup(p_organization_id uuid, p_query text) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  v_q text := btrim(coalesce(p_query, ''));
begin
  perform public.assert_module(p_organization_id, 'warranty');
  if not (public.has_permission(p_organization_id, 'orders.view') or public.has_permission(p_organization_id, 'pos.sell')) then
    raise exception using errcode = '42501', message = 'PERMISSION_DENIED', detail = 'orders.view';
  end if;
  if length(v_q) < 3 then
    return '[]'::jsonb;
  end if;

  return coalesce((
    with hits as (
      select ol.id as line_id, su.id as unit_id
        from public.serial_units su
        join public.order_line_units u on u.serial_unit_id = su.id
        join public.order_lines ol on ol.id = u.order_line_id
       where su.organization_id = p_organization_id and upper(su.serial) = upper(v_q)
      union
      select ol.id, null from public.orders o join public.order_lines ol on ol.order_id = o.id
       where o.organization_id = p_organization_id and upper(o.number) = upper(v_q)
      union
      select ol.id, null from public.customers c
        join public.orders o on o.customer_id = c.id
        join public.order_lines ol on ol.order_id = o.id
       where c.organization_id = p_organization_id and c.phone is not null
         and c.phone = case when v_q ~ '^\+' then v_q
                            when v_q ~ '^0\d{9}$' then '+94' || substr(v_q, 2) else v_q end
      union
      select ol.id, null from public.orders o join public.order_lines ol on ol.order_id = o.id
       where o.organization_id = p_organization_id and o.contact->>'phone' is not null
         and o.contact->>'phone' = case when v_q ~ '^\+' then v_q when v_q ~ '^0\d{9}$' then '+94' || substr(v_q, 2) else v_q end)
    select jsonb_agg(x order by x->>'purchased_at' desc) from (
      select jsonb_build_object(
        'order_line_id', ol.id, 'order_id', o.id, 'order_number', o.number, 'channel', o.channel,
        'status', o.status, 'location', l.name,
        'purchased_at', coalesce(o.confirmed_at, o.placed_at),
        'customer', coalesce(
           (select jsonb_build_object('id', c.id, 'name', c.full_name, 'phone', c.phone) from public.customers c where c.id = o.customer_id),
           case when o.contact <> '{}'::jsonb then jsonb_build_object('name', o.contact->>'full_name', 'phone', o.contact->>'phone') end),
        'product', ol.product_name, 'variant', ol.variant_title, 'quantity', ol.quantity,
        'serials', (select jsonb_agg(su.serial order by su.serial) from public.order_line_units u
                      join public.serial_units su on su.id = u.serial_unit_id where u.order_line_id = ol.id),
        'matched_serial', (select su.serial from public.serial_units su where su.id = h.unit_id),
        'warranty_months', ol.warranty_months,
        'warranty_expires_on', case when ol.warranty_months > 0
                                    then (coalesce(o.confirmed_at, o.placed_at) + make_interval(months => ol.warranty_months))::date end,
        'warranty_status', case when coalesce(ol.warranty_months, 0) = 0 then 'none'
                                when coalesce(o.confirmed_at, o.placed_at) + make_interval(months => ol.warranty_months) >= now() then 'active'
                                else 'expired' end,
        'returned_quantity', public._returned_quantity(ol.id),
        'claims', coalesce((select jsonb_agg(jsonb_build_object('id', wc.id, 'number', wc.number, 'status', wc.status, 'created_at', wc.created_at) order by wc.created_at)
                              from public.warranty_claims wc where wc.order_line_id = ol.id), '[]'::jsonb)) x
        from (select distinct on (line_id) line_id, unit_id from hits order by line_id, unit_id nulls last) h
        join public.order_lines ol on ol.id = h.line_id
        join public.orders o on o.id = ol.order_id
        join public.locations l on l.id = o.location_id
       where o.status in ('confirmed', 'completed')
       limit 100) s), '[]'::jsonb);
end $$;

create or replace function public.open_warranty_claim(
  p_organization_id uuid, p_order_line_id uuid, p_issue text, p_serial text default null) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  ol      public.order_lines%rowtype;
  o       public.orders%rowtype;
  v_unit  uuid;
  v_exp   date;
  v_id    uuid;
begin
  perform public.assert_module(p_organization_id, 'warranty');
  if not (public.has_permission(p_organization_id, 'orders.manage') or public.has_permission(p_organization_id, 'pos.sell')) then
    raise exception using errcode = '42501', message = 'PERMISSION_DENIED', detail = 'orders.manage';
  end if;
  select * into ol from public.order_lines where id = p_order_line_id and organization_id = p_organization_id;
  if not found then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'purchase';
  end if;
  select * into o from public.orders where id = ol.order_id;
  if o.status not in ('confirmed', 'completed') then
    raise exception using errcode = 'NC006', message = 'INVALID_STATE', detail = 'that order was not completed';
  end if;
  if p_serial is not null then
    select su.id into v_unit from public.order_line_units u join public.serial_units su on su.id = u.serial_unit_id
     where u.order_line_id = ol.id and upper(su.serial) = upper(btrim(p_serial));
    if v_unit is null then
      raise exception using errcode = 'NC004', message = 'SERIAL_UNAVAILABLE', detail = 'that serial number was not sold on this purchase';
    end if;
  elsif exists (select 1 from public.order_line_units where order_line_id = ol.id) then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'give the serial number of the unit being claimed';
  end if;
  if p_issue is null or length(btrim(p_issue)) < 3 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'describe the fault';
  end if;

  v_exp := case when ol.warranty_months > 0 then (coalesce(o.confirmed_at, o.placed_at) + make_interval(months => ol.warranty_months))::date end;
  insert into public.warranty_claims (organization_id, number, order_line_id, serial_unit_id, customer_id, issue, within_warranty, expires_on)
  values (p_organization_id, public.next_document_number(p_organization_id, 'warranty_claim', 'WC-'), ol.id, v_unit, o.customer_id,
          btrim(p_issue), v_exp is not null and v_exp >= current_date, v_exp)
  returning id into v_id;
  insert into public.warranty_claim_events (organization_id, claim_id, status, note)
  values (p_organization_id, v_id, 'open', btrim(p_issue));
  return public.warranty_claim(v_id);
end $$;

create or replace function public.update_warranty_claim(
  p_claim_id uuid, p_status public.warranty_claim_status, p_note text default null, p_resolution text default null) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  c public.warranty_claims%rowtype;
begin
  select * into c from public.warranty_claims where id = p_claim_id for update;
  if not found then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'claim';
  end if;
  perform public.assert_permission(c.organization_id, 'orders.manage');
  if c.status = 'closed' then
    raise exception using errcode = 'NC006', message = 'INVALID_STATE', detail = 'this claim is closed';
  end if;
  if p_status in ('replaced', 'refunded', 'rejected', 'closed') and coalesce(btrim(coalesce(p_resolution, c.resolution)), '') = '' then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'record how the claim was resolved';
  end if;
  update public.warranty_claims set status = p_status, resolution = coalesce(nullif(btrim(p_resolution), ''), resolution) where id = c.id;
  insert into public.warranty_claim_events (organization_id, claim_id, status, note)
  values (c.organization_id, c.id, p_status, nullif(btrim(p_note), ''));
  return public.warranty_claim(c.id);
end $$;

create or replace function public.warranty_claim(p_claim_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  c public.warranty_claims%rowtype;
begin
  select * into c from public.warranty_claims where id = p_claim_id;
  if not found or not (public.has_permission(c.organization_id, 'orders.view') or public.has_permission(c.organization_id, 'pos.sell')) then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'claim';
  end if;
  return (select jsonb_build_object(
    'claim_id', c.id, 'number', c.number, 'status', c.status, 'issue', c.issue, 'resolution', c.resolution,
    'within_warranty', c.within_warranty, 'expires_on', c.expires_on, 'created_at', c.created_at,
    'order_id', o.id, 'order_number', o.number, 'product', ol.product_name, 'variant', ol.variant_title,
    'serial', (select serial from public.serial_units where id = c.serial_unit_id),
    'customer', coalesce((select jsonb_build_object('id', cu.id, 'name', cu.full_name, 'phone', cu.phone) from public.customers cu where cu.id = c.customer_id),
                         case when o.contact <> '{}'::jsonb then jsonb_build_object('name', o.contact->>'full_name', 'phone', o.contact->>'phone') end),
    'history', (select jsonb_agg(jsonb_build_object('status', e.status, 'note', e.note, 'at', e.created_at,
                                                    'by', (select email from auth.users u where u.id = e.created_by)) order by e.id)
                  from public.warranty_claim_events e where e.claim_id = c.id))
    from public.order_lines ol join public.orders o on o.id = ol.order_id where ol.id = c.order_line_id);
end $$;

-- What a return would refund, without taking it (a rolled-back draft through the
-- real calculation), plus what can still be returned on each line.
create or replace function public.preview_return(p_order_id uuid, p_lines jsonb default null) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  o        public.orders%rowtype;
  v_id     uuid;
  v_result jsonb;
begin
  select * into o from public.orders where id = p_order_id;
  if not found or not (public.has_permission(o.organization_id, 'orders.view') or public.has_permission(o.organization_id, 'pos.sell')) then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'order';
  end if;
  v_result := jsonb_build_object(
    'order_id', o.id, 'order_number', o.number, 'channel', o.channel, 'status', o.status,
    'customer_id', o.customer_id, 'placed_at', coalesce(o.confirmed_at, o.placed_at),
    'within_return_period', public._within_return_window(o),
    'refundable', o.amount_paid - o.amount_refunded,
    'lines', coalesce((select jsonb_agg(jsonb_build_object(
               'order_line_id', ol.id, 'name', ol.product_name, 'variant', ol.variant_title, 'quantity', ol.quantity,
               'line_total', ol.line_total, 'returnable', ol.quantity - public._returned_quantity(ol.id),
               'serials', (select jsonb_agg(su.serial order by su.serial) from public.order_line_units u
                             join public.serial_units su on su.id = u.serial_unit_id
                            where u.order_line_id = ol.id
                              and not exists (select 1 from public.return_lines x join public.returns rr on rr.id = x.return_id
                                               where x.serial_unit_id = su.id and rr.status <> 'cancelled')))
             order by ol.position) from public.order_lines ol where ol.order_id = o.id), '[]'::jsonb));
  if p_lines is null or jsonb_array_length(p_lines) = 0 then
    return v_result || jsonb_build_object('refund_total', 0);
  end if;
  begin
    v_id := public._new_return(o, 'requested', 'admin_order', null, null, null);
    perform public._add_return_lines(v_id, p_lines, true);
    v_result := v_result || jsonb_build_object('refund_total', (select refund_total from public.returns where id = v_id));
    raise exception using errcode = 'NCQ00', message = 'PREVIEW_ROLLBACK';
  exception when sqlstate 'NCQ00' then
    null;
  end;
  return v_result;
end $$;

create or replace function public.set_product_warranty(p_product_id uuid, p_months int, p_terms text default null) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_org uuid;
begin
  select organization_id into v_org from public.products where id = p_product_id;
  if v_org is null then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'product';
  end if;
  perform public.assert_permission(v_org, 'catalog.manage');
  perform public.assert_module(v_org, 'warranty');
  if p_months is not null and (p_months < 0 or p_months > 120) then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'warranty is 0 to 120 months';
  end if;
  update public.products set warranty_months = p_months, warranty_terms = nullif(btrim(p_terms), '') where id = p_product_id;
end $$;

-- ---------------------------------------------------------------------------
-- Settings: return period
-- ---------------------------------------------------------------------------
create or replace function public.update_organization_settings(p_organization_id uuid, p_changes jsonb)
returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_allowed constant text[] := array['checkout_hold_minutes', 'checkout_max_line_quantity', 'discount_limits',
                                     'receipt_footer', 'contact_email', 'contact_phone', 'low_stock_default',
                                     'delivery_enabled', 'pickup_enabled', 'delivery_fee', 'free_delivery_over',
                                     'allow_cash_on_delivery', 'bank_transfer_details', 'bank_transfer_hold_hours',
                                     'return_days', 'loyalty_points_per_100', 'loyalty_point_value', 'loyalty_min_redeem'];
  v_settings jsonb;
  v_key text;
begin
  perform public.assert_permission(p_organization_id, 'settings.manage');
  for v_key in select jsonb_object_keys(coalesce(p_changes->'settings', '{}'::jsonb)) loop
    if not (v_key = any (v_allowed)) then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = format('unknown setting %s', v_key);
    end if;
  end loop;
  if p_changes ? 'name' and coalesce(btrim(p_changes->>'name'), '') = '' then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'the business needs a name';
  end if;
  if coalesce((p_changes->'settings'->>'checkout_hold_minutes')::int, 15) not between 1 and 120 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'checkout hold is 1 to 120 minutes';
  end if;
  if coalesce((p_changes->'settings'->>'bank_transfer_hold_hours')::int, 24) not between 1 and 168 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'bank transfer hold is 1 to 168 hours';
  end if;
  if coalesce((p_changes->'settings'->>'return_days')::int, 7) not between 0 and 365 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'the return period is 0 to 365 days';
  end if;
  if coalesce((p_changes->'settings'->>'delivery_fee')::numeric, 0) < 0
     or coalesce((p_changes->'settings'->>'free_delivery_over')::numeric, 0) < 0 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'delivery amounts cannot be negative';
  end if;
  if exists (select 1 from jsonb_each_text(coalesce(p_changes->'settings'->'discount_limits', '{}'::jsonb)) d
              where d.key::text not in ('owner','admin','manager','cashier','stock_keeper','viewer')
                 or d.value::numeric < 0 or d.value::numeric > 100) then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'discount limits are 0-100 per role';
  end if;
  update public.organizations
     set name = coalesce(nullif(btrim(p_changes->>'name'), ''), name),
         prices_include_tax = coalesce((p_changes->>'prices_include_tax')::boolean, prices_include_tax),
         timezone = coalesce(nullif(p_changes->>'timezone', ''), timezone),
         settings = jsonb_strip_nulls(settings || coalesce(p_changes->'settings', '{}'::jsonb))
   where id = p_organization_id
  returning settings into v_settings;
  return v_settings;
end $$;

-- ---------------------------------------------------------------------------
-- Security
-- ---------------------------------------------------------------------------
alter table public.returns enable row level security;
alter table public.return_lines enable row level security;
alter table public.warranty_claims enable row level security;
alter table public.warranty_claim_events enable row level security;

grant select on public.returns, public.return_lines, public.warranty_claims, public.warranty_claim_events to authenticated;
grant all on public.returns, public.return_lines, public.warranty_claims, public.warranty_claim_events to service_role;
revoke all on public.returns, public.return_lines, public.warranty_claims, public.warranty_claim_events from anon;
revoke insert, update, delete, truncate on public.returns, public.return_lines, public.warranty_claims, public.warranty_claim_events from authenticated;

create policy returns_read on public.returns for select
  using (public.has_permission(organization_id, 'orders.view') or public.owns_order(order_id));
create policy return_lines_read on public.return_lines for select
  using (public.has_permission(organization_id, 'orders.view')
         or exists (select 1 from public.returns r where r.id = return_id and public.owns_order(r.order_id)));
create policy warranty_claims_read on public.warranty_claims for select
  using (public.has_permission(organization_id, 'orders.view'));
create policy warranty_claim_events_read on public.warranty_claim_events for select
  using (public.has_permission(organization_id, 'orders.view'));

-- Function grants, maintained by rule rather than by list from here on:
--   * names starting with '_' are internal and never granted
--   * platform-only functions are named below
--   * trigger functions are skipped
--   * everything else is callable by signed-in users (each checks its own permission)
--   * the anonymous storefront gets an explicit allowlist
create or replace function public._regrant_api() returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  f record;
  v_platform constant text[] := array['create_organization', 'apply_plan', 'set_organization_module',
                                      'expire_reservations', 'record_gateway_payment',
                                      -- building blocks the commands call; not endpoints
                                      'next_document_number', 'assert_permission', 'assert_module',
                                      'assert_location_access'];
  v_anon constant text[] := array['is_platform_admin', 'role_permissions', 'is_member', 'has_permission',
                                  'has_location_access', 'module_enabled', 'owns_order', 'slugify',
                                  'storefront_organization', 'storefront_settings', 'storefront_availability',
                                  'storefront_categories', 'storefront_catalog', 'storefront_product',
                                  'cart_get', 'cart_set_item', 'cart_clear', 'quote_order', 'checkout',
                                  'get_order_by_token', 'start_checkout', 'request_return'];
begin
  execute 'revoke execute on all functions in schema public from public, anon, authenticated';
  execute 'grant execute on all functions in schema public to service_role';
  for f in
    select p.oid::regprocedure as sig, p.proname
      from pg_proc p join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'public' and p.prokind = 'f'
       and p.prorettype <> 'trigger'::regtype
       and p.proname !~ '^_'
       and not (p.proname = any (v_platform))
  loop
    execute format('grant execute on function %s to authenticated', f.sig);
    if f.proname = any (v_anon) then
      execute format('grant execute on function %s to anon', f.sig);
    end if;
  end loop;
end $$;

select public._regrant_api();

-- ======================================================================
-- 0013_purchasing_transfers.sql
-- ======================================================================
-- 0013_purchasing_transfers.sql
-- Phase 7: suppliers, purchase orders and receiving against them; stock
-- transfers between locations (requested -> approved -> dispatched -> received).
--
-- Every unit that moves still goes through inventory_movements, so the ledger,
-- holds, lots and serials stay exact. Approving a transfer holds the stock at
-- the source; dispatching takes it out (in transit); receiving puts it in at the
-- destination at the same cost.

set check_function_bodies = off;

create type public.po_status as enum ('draft', 'ordered', 'partially_received', 'received', 'closed', 'cancelled');
create type public.transfer_status as enum ('requested', 'approved', 'dispatched', 'received', 'cancelled');

-- ---------------------------------------------------------------------------
-- Suppliers
-- ---------------------------------------------------------------------------
create table public.suppliers (
  id                 uuid primary key default gen_random_uuid(),
  organization_id    uuid not null references public.organizations(id) on delete cascade,
  name               text not null check (length(btrim(name)) > 0),
  contact_name       text,
  phone              text,
  email              text,
  address            jsonb not null default '{}'::jsonb,
  payment_terms_days int check (payment_terms_days is null or payment_terms_days between 0 and 365),
  notes              text,
  is_active          boolean not null default true,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  unique (organization_id, id)
);
create unique index suppliers_name_uq on public.suppliers (organization_id, lower(name));
create trigger suppliers_touch before update on public.suppliers for each row execute function public.touch_updated_at();

create or replace function public.suppliers_enforce_module() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  perform public.assert_module(new.organization_id, 'purchasing');
  return new;
end $$;
create trigger suppliers_module_guard before insert on public.suppliers
  for each row execute function public.suppliers_enforce_module();

-- ---------------------------------------------------------------------------
-- Purchase orders
-- ---------------------------------------------------------------------------
create table public.purchase_orders (
  id              uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete cascade,
  number          text not null,
  supplier_id     uuid not null,
  location_id     uuid not null,
  status          public.po_status not null default 'draft',
  expected_on     date,
  supplier_reference text,
  note            text,
  total           numeric(14,2) not null default 0,
  created_by      uuid default auth.uid(),
  created_at      timestamptz not null default now(),
  ordered_at      timestamptz,
  closed_at       timestamptz,
  updated_at      timestamptz not null default now(),
  unique (organization_id, number),
  unique (organization_id, id),
  foreign key (organization_id, supplier_id) references public.suppliers (organization_id, id),
  foreign key (organization_id, location_id) references public.locations (organization_id, id)
);
create index purchase_orders_org_idx on public.purchase_orders (organization_id, created_at desc);
create trigger purchase_orders_touch before update on public.purchase_orders for each row execute function public.touch_updated_at();
create trigger purchase_orders_audit after insert or update on public.purchase_orders for each row execute function public.audit_row();

create table public.purchase_order_lines (
  id                uuid primary key default gen_random_uuid(),
  organization_id   uuid not null,
  purchase_order_id uuid not null,
  variant_id        uuid not null,
  quantity_ordered  numeric(14,3) not null check (quantity_ordered > 0),
  quantity_received numeric(14,3) not null default 0 check (quantity_received >= 0),
  unit_cost         numeric(14,4) not null check (unit_cost >= 0),
  position          int not null default 0,
  unique (purchase_order_id, variant_id),
  unique (organization_id, id),
  foreign key (organization_id, purchase_order_id) references public.purchase_orders (organization_id, id) on delete cascade,
  foreign key (organization_id, variant_id) references public.product_variants (organization_id, id),
  check (quantity_received <= quantity_ordered)
);

alter table public.stock_receipts
  add column purchase_order_id uuid,
  add column supplier_id uuid,
  add foreign key (organization_id, purchase_order_id) references public.purchase_orders (organization_id, id),
  add foreign key (organization_id, supplier_id) references public.suppliers (organization_id, id);

-- ---------------------------------------------------------------------------
-- Transfers
-- ---------------------------------------------------------------------------
create table public.stock_transfers (
  id               uuid primary key default gen_random_uuid(),
  organization_id  uuid not null references public.organizations(id) on delete cascade,
  number           text not null,
  from_location_id uuid not null,
  to_location_id   uuid not null,
  status           public.transfer_status not null default 'requested',
  note             text,
  requested_by     uuid default auth.uid(),
  requested_at     timestamptz not null default now(),
  approved_by      uuid, approved_at timestamptz,
  dispatched_by    uuid, dispatched_at timestamptz,
  received_by      uuid, received_at timestamptz,
  receive_note     text,
  unique (organization_id, number),
  unique (organization_id, id),
  foreign key (organization_id, from_location_id) references public.locations (organization_id, id),
  foreign key (organization_id, to_location_id) references public.locations (organization_id, id),
  check (from_location_id <> to_location_id)
);
create index stock_transfers_org_idx on public.stock_transfers (organization_id, requested_at desc);

create table public.stock_transfer_lines (
  id                uuid primary key default gen_random_uuid(),
  organization_id   uuid not null,
  transfer_id       uuid not null,
  variant_id        uuid not null,
  quantity          numeric(14,3) not null check (quantity > 0),
  serials           text[],
  quantity_received numeric(14,3),
  unique (transfer_id, variant_id),
  unique (organization_id, id),
  foreign key (organization_id, transfer_id) references public.stock_transfers (organization_id, id) on delete cascade,
  foreign key (organization_id, variant_id) references public.product_variants (organization_id, id)
);

-- ---------------------------------------------------------------------------
-- Engine: consuming holds with a chosen serial status
-- ---------------------------------------------------------------------------
-- A sale marks units 'sold'; a transfer dispatch marks them 'in_transit'.
drop function public._consume_reservations(text, uuid, public.movement_type);
create or replace function public._consume_reservations(
  p_source_type   text,
  p_source_id     uuid,
  p_movement_type public.movement_type,
  p_serial_final  public.serial_status default 'sold') returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  r public.stock_reservations%rowtype;
begin
  for r in
    select * from public.stock_reservations
     where source_type = p_source_type and source_id = p_source_id and status = 'active'
     order by location_id, variant_id, id
  loop
    perform public._lock_stock_row(r.organization_id, r.location_id, r.variant_id);
    if (select sr.status from public.stock_reservations sr where sr.id = r.id for update) <> 'active' then
      raise exception using errcode = 'NC006', message = 'INVALID_STATE', detail = 'reservation is no longer active';
    end if;

    update public.stock_levels set reserved = reserved - r.quantity
     where location_id = r.location_id and variant_id = r.variant_id;
    if r.batch_id is not null then
      update public.batch_stock set reserved = reserved - r.quantity
       where location_id = r.location_id and batch_id = r.batch_id;
    end if;
    if r.serial_unit_id is not null then
      update public.serial_units set status = p_serial_final where id = r.serial_unit_id;
    end if;

    insert into public.inventory_movements
      (organization_id, location_id, variant_id, batch_id, serial_unit_id, movement_type, quantity, source_type, source_id)
    values (r.organization_id, r.location_id, r.variant_id, r.batch_id, r.serial_unit_id,
            p_movement_type, -r.quantity, p_source_type, p_source_id);

    update public.stock_reservations set status = 'consumed', closed_at = now() where id = r.id;
  end loop;
end $$;

-- ---------------------------------------------------------------------------
-- Purchasing commands
-- ---------------------------------------------------------------------------
-- Creates or updates a draft PO. p_po = {id?, supplier_id, location_id, expected_on?,
-- supplier_reference?, note?, lines: [{variant_id, quantity, unit_cost}]}
create or replace function public.save_purchase_order(p_organization_id uuid, p_po jsonb) returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_id    uuid := nullif(p_po->>'id', '')::uuid;
  v_po    public.purchase_orders%rowtype;
  e       jsonb;
  v_i     int := 0;
begin
  perform public.assert_module(p_organization_id, 'purchasing');
  perform public.assert_permission(p_organization_id, 'purchasing.manage');
  if not exists (select 1 from public.suppliers where id = (p_po->>'supplier_id')::uuid and organization_id = p_organization_id and is_active) then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'supplier';
  end if;
  if not exists (select 1 from public.locations where id = (p_po->>'location_id')::uuid and organization_id = p_organization_id and is_active) then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'delivery location';
  end if;
  if jsonb_typeof(p_po->'lines') <> 'array' or jsonb_array_length(p_po->'lines') = 0 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'a purchase order needs at least one line';
  end if;

  if v_id is null then
    insert into public.purchase_orders (organization_id, number, supplier_id, location_id, expected_on, supplier_reference, note)
    values (p_organization_id, public.next_document_number(p_organization_id, 'purchase_order', 'PO-'),
            (p_po->>'supplier_id')::uuid, (p_po->>'location_id')::uuid, nullif(p_po->>'expected_on', '')::date,
            nullif(btrim(p_po->>'supplier_reference'), ''), nullif(btrim(p_po->>'note'), ''))
    returning id into v_id;
  else
    select * into v_po from public.purchase_orders where id = v_id and organization_id = p_organization_id for update;
    if not found then
      raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'purchase order';
    end if;
    if v_po.status <> 'draft' then
      raise exception using errcode = 'NC006', message = 'INVALID_STATE', detail = 'only a draft purchase order can be edited';
    end if;
    update public.purchase_orders
       set supplier_id = (p_po->>'supplier_id')::uuid, location_id = (p_po->>'location_id')::uuid,
           expected_on = nullif(p_po->>'expected_on', '')::date, supplier_reference = nullif(btrim(p_po->>'supplier_reference'), ''),
           note = nullif(btrim(p_po->>'note'), '')
     where id = v_id;
    delete from public.purchase_order_lines where purchase_order_id = v_id;
  end if;

  for e in select x from jsonb_array_elements(p_po->'lines') x loop
    v_i := v_i + 1;
    if not exists (select 1 from public.product_variants where id = (e->>'variant_id')::uuid and organization_id = p_organization_id) then
      raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'variant';
    end if;
    if coalesce((e->>'quantity')::numeric, 0) <= 0 or coalesce((e->>'unit_cost')::numeric, -1) < 0 then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'each line needs a quantity and a cost';
    end if;
    begin
      insert into public.purchase_order_lines (organization_id, purchase_order_id, variant_id, quantity_ordered, unit_cost, position)
      values (p_organization_id, v_id, (e->>'variant_id')::uuid, (e->>'quantity')::numeric, (e->>'unit_cost')::numeric, v_i);
    exception when unique_violation then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'an item appears twice - combine the lines';
    end;
  end loop;

  update public.purchase_orders
     set total = (select coalesce(sum(round(quantity_ordered * unit_cost, 2)), 0) from public.purchase_order_lines where purchase_order_id = v_id)
   where id = v_id;
  return v_id;
end $$;

create or replace function public.place_purchase_order(p_po_id uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  po public.purchase_orders%rowtype;
begin
  select * into po from public.purchase_orders where id = p_po_id for update;
  if not found then raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'purchase order'; end if;
  perform public.assert_permission(po.organization_id, 'purchasing.manage');
  if po.status <> 'draft' then
    raise exception using errcode = 'NC006', message = 'INVALID_STATE', detail = 'this purchase order has already been placed';
  end if;
  update public.purchase_orders set status = 'ordered', ordered_at = now() where id = po.id;
end $$;

-- Cancel (nothing received yet) or close short (some received, no more coming).
create or replace function public.close_purchase_order(p_po_id uuid, p_reason text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  po public.purchase_orders%rowtype;
begin
  select * into po from public.purchase_orders where id = p_po_id for update;
  if not found then raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'purchase order'; end if;
  perform public.assert_permission(po.organization_id, 'purchasing.manage');
  if po.status in ('received', 'closed', 'cancelled') then
    raise exception using errcode = 'NC006', message = 'INVALID_STATE', detail = format('this purchase order is already %s', po.status);
  end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'say why';
  end if;
  update public.purchase_orders
     set status = case when po.status = 'partially_received' then 'closed' else 'cancelled' end::public.po_status,
         closed_at = now(), note = concat_ws(E'\n', note, 'Closed: ' || btrim(p_reason))
   where id = po.id;
end $$;

-- Goods in against a PO. p_lines = [{po_line_id, quantity, unit_cost?, serials?, lot_code?, expires_on?}]
create or replace function public.receive_purchase_order(p_po_id uuid, p_lines jsonb, p_reference text default null, p_note text default null)
returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  po        public.purchase_orders%rowtype;
  pl        public.purchase_order_lines%rowtype;
  e         jsonb;
  v_qty     numeric;
  v_receipt uuid;
  v_number  text;
begin
  select * into po from public.purchase_orders where id = p_po_id for update;
  if not found then raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'purchase order'; end if;
  perform public.assert_permission(po.organization_id, 'inventory.receive');
  perform public.assert_location_access(po.organization_id, po.location_id);
  if po.status not in ('ordered', 'partially_received') then
    raise exception using errcode = 'NC006', message = 'INVALID_STATE',
      detail = case po.status when 'draft' then 'place the order before receiving against it' else format('this purchase order is %s', po.status) end;
  end if;
  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'nothing to receive';
  end if;

  v_number := public.next_document_number(po.organization_id, 'receipt', 'RCV-');
  insert into public.stock_receipts (organization_id, location_id, number, reference, note, purchase_order_id, supplier_id)
  values (po.organization_id, po.location_id, v_number, coalesce(p_reference, po.supplier_reference), p_note, po.id, po.supplier_id)
  returning id into v_receipt;

  for e in select x from jsonb_array_elements(p_lines) x order by x->>'po_line_id' loop
    v_qty := (e->>'quantity')::numeric;
    continue when coalesce(v_qty, 0) = 0;
    select * into pl from public.purchase_order_lines where id = (e->>'po_line_id')::uuid and purchase_order_id = po.id for update;
    if not found then
      raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'that line is not on this purchase order';
    end if;
    if v_qty < 0 or v_qty > pl.quantity_ordered - pl.quantity_received then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
        detail = format('%s outstanding on this line', pl.quantity_ordered - pl.quantity_received);
    end if;
    perform public._stock_in_line(po.organization_id, po.location_id, pl.variant_id, v_qty, 'receipt',
      coalesce((e->>'unit_cost')::numeric, pl.unit_cost), 'stock_receipt', v_receipt,
      case when e ? 'serials' then array(select jsonb_array_elements_text(e->'serials')) end,
      nullif(btrim(e->>'lot_code'), ''), (e->>'expires_on')::date, po.number);
    update public.purchase_order_lines set quantity_received = quantity_received + v_qty where id = pl.id;
  end loop;

  update public.purchase_orders
     set status = case when not exists (select 1 from public.purchase_order_lines
                                         where purchase_order_id = po.id and quantity_received < quantity_ordered)
                       then 'received' else 'partially_received' end::public.po_status,
         closed_at = case when not exists (select 1 from public.purchase_order_lines
                                            where purchase_order_id = po.id and quantity_received < quantity_ordered)
                          then now() end
   where id = po.id;

  return jsonb_build_object('receipt_id', v_receipt, 'number', v_number,
                            'status', (select status from public.purchase_orders where id = po.id));
end $$;

-- What to buy: items at or under their low-stock level, with the last supplier and cost.
create or replace function public.reorder_suggestions(p_organization_id uuid, p_location_id uuid default null)
returns table (variant_id uuid, product_name text, variant_title text, sku text, location_id uuid, location_name text,
               available numeric, low_stock_level numeric, on_order numeric, suggested numeric,
               last_supplier_id uuid, last_supplier text, last_cost numeric)
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  v_default numeric;
begin
  perform public.assert_permission(p_organization_id, 'purchasing.manage');
  select coalesce((settings->>'low_stock_default')::numeric, 3) into v_default from public.organizations where id = p_organization_id;
  return query
    with levels as (
      select s.variant_id, s.location_id, s.on_hand - s.reserved as available, coalesce(s.low_stock_threshold, v_default) as lvl
        from public.stock_levels s
       where s.organization_id = p_organization_id and (p_location_id is null or s.location_id = p_location_id)),
    open_po as (
      select po.location_id, pl.variant_id, sum(pl.quantity_ordered - pl.quantity_received) as qty
        from public.purchase_order_lines pl join public.purchase_orders po on po.id = pl.purchase_order_id
       where po.organization_id = p_organization_id and po.status in ('draft', 'ordered', 'partially_received')
       group by 1, 2),
    last_buy as (
      select distinct on (pl.variant_id) pl.variant_id, po.supplier_id, pl.unit_cost
        from public.purchase_order_lines pl join public.purchase_orders po on po.id = pl.purchase_order_id
       where po.organization_id = p_organization_id and po.status <> 'cancelled'
       order by pl.variant_id, po.created_at desc)
    select l.variant_id, p.name, v.title, v.sku, l.location_id, loc.name, l.available, l.lvl,
           coalesce(o.qty, 0), greatest(ceil(l.lvl * 2 - l.available - coalesce(o.qty, 0)), 0),
           lb.supplier_id, sup.name, lb.unit_cost
      from levels l
      join public.product_variants v on v.id = l.variant_id and v.is_active
      join public.products p on p.id = v.product_id and p.status = 'active'
      join public.locations loc on loc.id = l.location_id
      left join open_po o on o.variant_id = l.variant_id and o.location_id = l.location_id
      left join last_buy lb on lb.variant_id = l.variant_id
      left join public.suppliers sup on sup.id = lb.supplier_id
     where l.available <= l.lvl and l.available + coalesce(o.qty, 0) <= l.lvl
     order by p.name, v.position;
end $$;

-- ---------------------------------------------------------------------------
-- Transfer commands
-- ---------------------------------------------------------------------------
-- p_lines = [{variant_id, quantity, serials?}]
create or replace function public.request_transfer(p_from uuid, p_to uuid, p_lines jsonb, p_note text default null) returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_org uuid;
  v_id  uuid;
  e     jsonb;
  v_mode public.tracking_mode;
begin
  select organization_id into v_org from public.locations where id = p_from and is_active;
  if v_org is null or not exists (select 1 from public.locations where id = p_to and organization_id = v_org and is_active) then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'location';
  end if;
  perform public.assert_module(v_org, 'transfers');
  perform public.assert_permission(v_org, 'transfers.request');
  if p_from = p_to then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'choose two different locations';
  end if;
  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'a transfer needs at least one item';
  end if;

  insert into public.stock_transfers (organization_id, number, from_location_id, to_location_id, note)
  values (v_org, public.next_document_number(v_org, 'transfer', 'TR-'), p_from, p_to, nullif(btrim(p_note), ''))
  returning id into v_id;

  for e in select x from jsonb_array_elements(p_lines) x loop
    select p.tracking_mode into v_mode from public.product_variants v join public.products p on p.id = v.product_id
     where v.id = (e->>'variant_id')::uuid and v.organization_id = v_org;
    if not found then raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'variant'; end if;
    if coalesce((e->>'quantity')::numeric, 0) <= 0 then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'quantities must be positive';
    end if;
    if e ? 'serials' and (v_mode <> 'serial' or jsonb_array_length(e->'serials') <> (e->>'quantity')::numeric) then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'serial numbers only for serial-tracked items, one per unit';
    end if;
    begin
      insert into public.stock_transfer_lines (organization_id, transfer_id, variant_id, quantity, serials)
      values (v_org, v_id, (e->>'variant_id')::uuid, (e->>'quantity')::numeric,
              case when e ? 'serials' then array(select btrim(x) from jsonb_array_elements_text(e->'serials') x) end);
    exception when unique_violation then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'an item appears twice - combine the lines';
    end;
  end loop;
  return v_id;
end $$;

-- Approval holds the stock at the source so it can't be sold before it leaves.
create or replace function public.approve_transfer(p_transfer_id uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  t public.stock_transfers%rowtype;
  l record;
begin
  select * into t from public.stock_transfers where id = p_transfer_id for update;
  if not found then raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'transfer'; end if;
  perform public.assert_permission(t.organization_id, 'transfers.approve');
  if t.status <> 'requested' then
    raise exception using errcode = 'NC006', message = 'INVALID_STATE', detail = format('this transfer is %s', t.status);
  end if;
  for l in select * from public.stock_transfer_lines where transfer_id = t.id order by variant_id loop
    perform public._reserve_line(t.organization_id, t.from_location_id, l.variant_id, l.quantity, 'transfer', t.id, null, l.serials, null);
  end loop;
  update public.stock_transfers set status = 'approved', approved_by = auth.uid(), approved_at = now() where id = t.id;
end $$;

-- The goods leave: out of source stock, serial units in transit.
create or replace function public.dispatch_transfer(p_transfer_id uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  t public.stock_transfers%rowtype;
begin
  select * into t from public.stock_transfers where id = p_transfer_id for update;
  if not found then raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'transfer'; end if;
  perform public.assert_permission(t.organization_id, 'inventory.adjust');
  perform public.assert_location_access(t.organization_id, t.from_location_id);
  if t.status <> 'approved' then
    raise exception using errcode = 'NC006', message = 'INVALID_STATE', detail = 'a transfer is approved before it is dispatched';
  end if;
  perform public._consume_reservations('transfer', t.id, 'transfer_out', 'in_transit');
  update public.stock_transfers set status = 'dispatched', dispatched_by = auth.uid(), dispatched_at = now() where id = t.id;
end $$;

-- The goods arrive. p_lines (optional) = [{line_id, quantity_received, serials?}];
-- omitted means everything arrived. Anything short needs a note; it stays out of
-- stock (lost or damaged in transit) and missing serial units are written off.
create or replace function public.receive_transfer(p_transfer_id uuid, p_lines jsonb default null, p_note text default null) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  t        public.stock_transfers%rowtype;
  l        public.stock_transfer_lines%rowtype;
  m        record;
  e        jsonb;
  v_recv   numeric;
  v_left   numeric;
  v_take   numeric;
  v_serials text[];
  v_short  boolean := false;
begin
  select * into t from public.stock_transfers where id = p_transfer_id for update;
  if not found then raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'transfer'; end if;
  perform public.assert_permission(t.organization_id, 'inventory.receive');
  perform public.assert_location_access(t.organization_id, t.to_location_id);
  if t.status <> 'dispatched' then
    raise exception using errcode = 'NC006', message = 'INVALID_STATE', detail = 'only a dispatched transfer can be received';
  end if;

  for l in select * from public.stock_transfer_lines where transfer_id = t.id order by variant_id loop
    e := (select x from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb)) x where x->>'line_id' = l.id::text);
    v_recv := coalesce((e->>'quantity_received')::numeric, l.quantity);
    if v_recv < 0 or v_recv > l.quantity then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = format('between 0 and %s arrived', l.quantity);
    end if;
    if v_recv < l.quantity then v_short := true; end if;
    v_serials := case when e ? 'serials' then array(select upper(btrim(x)) from jsonb_array_elements_text(e->'serials') x) end;
    v_left := v_recv;

    for m in
      select im.serial_unit_id, im.batch_id, -im.quantity as qty, im.unit_cost, su.serial
        from public.inventory_movements im left join public.serial_units su on su.id = im.serial_unit_id
       where im.source_type = 'transfer' and im.source_id = t.id and im.variant_id = l.variant_id and im.movement_type = 'transfer_out'
       order by im.id
    loop
      if m.serial_unit_id is not null then
        if (v_serials is null and v_left >= 1) or upper(m.serial) = any (coalesce(v_serials, '{}')) then
          update public.serial_units set status = 'available', location_id = t.to_location_id where id = m.serial_unit_id;
          insert into public.inventory_movements (organization_id, location_id, variant_id, serial_unit_id, movement_type, quantity, unit_cost, source_type, source_id, note)
          values (t.organization_id, t.to_location_id, l.variant_id, m.serial_unit_id, 'transfer_in', 1, m.unit_cost, 'transfer', t.id, t.number);
          v_left := v_left - 1;
        else
          update public.serial_units set status = 'written_off' where id = m.serial_unit_id;
        end if;
      else
        v_take := least(m.qty, v_left);
        if v_take > 0 then
          insert into public.inventory_movements (organization_id, location_id, variant_id, batch_id, movement_type, quantity, unit_cost, source_type, source_id, note)
          values (t.organization_id, t.to_location_id, l.variant_id, m.batch_id, 'transfer_in', v_take, m.unit_cost, 'transfer', t.id, t.number);
          v_left := v_left - v_take;
        end if;
      end if;
    end loop;
    if v_serials is not null and v_left <> 0 then
      raise exception using errcode = 'NC004', message = 'SERIAL_UNAVAILABLE', detail = 'the serials received do not match what was dispatched';
    end if;
    update public.stock_transfer_lines set quantity_received = v_recv where id = l.id;
  end loop;

  if v_short and coalesce(btrim(p_note), '') = '' then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'less arrived than was sent - say what happened';
  end if;
  update public.stock_transfers
     set status = 'received', received_by = auth.uid(), received_at = now(), receive_note = nullif(btrim(p_note), '')
   where id = t.id;
end $$;

create or replace function public.cancel_transfer(p_transfer_id uuid, p_reason text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  t public.stock_transfers%rowtype;
  r record;
begin
  select * into t from public.stock_transfers where id = p_transfer_id for update;
  if not found then raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'transfer'; end if;
  perform public.assert_permission(t.organization_id, 'transfers.approve');
  if t.status not in ('requested', 'approved') then
    raise exception using errcode = 'NC006', message = 'INVALID_STATE', detail = 'goods already on the way cannot be cancelled - receive them';
  end if;
  for r in select id from public.stock_reservations where source_type = 'transfer' and source_id = t.id and status = 'active' order by location_id, variant_id, id loop
    perform public._release_reservation(r.id, 'released');
  end loop;
  update public.stock_transfers set status = 'cancelled', note = concat_ws(E'\n', note, 'Cancelled: ' || coalesce(p_reason, '')) where id = t.id;
end $$;

-- ---------------------------------------------------------------------------
-- Security
-- ---------------------------------------------------------------------------
alter table public.suppliers enable row level security;
alter table public.purchase_orders enable row level security;
alter table public.purchase_order_lines enable row level security;
alter table public.stock_transfers enable row level security;
alter table public.stock_transfer_lines enable row level security;

grant select on public.suppliers, public.purchase_orders, public.purchase_order_lines, public.stock_transfers, public.stock_transfer_lines to authenticated;
grant insert, update on public.suppliers to authenticated;
grant all on public.suppliers, public.purchase_orders, public.purchase_order_lines, public.stock_transfers, public.stock_transfer_lines to service_role;
revoke all on public.suppliers, public.purchase_orders, public.purchase_order_lines, public.stock_transfers, public.stock_transfer_lines from anon;
revoke insert, update, delete, truncate on public.purchase_orders, public.purchase_order_lines, public.stock_transfers, public.stock_transfer_lines from authenticated;

create policy suppliers_read on public.suppliers for select
  using (public.has_permission(organization_id, 'purchasing.manage') or public.has_permission(organization_id, 'inventory.receive'));
create policy suppliers_insert on public.suppliers for insert with check (public.has_permission(organization_id, 'purchasing.manage'));
create policy suppliers_update on public.suppliers for update
  using (public.has_permission(organization_id, 'purchasing.manage')) with check (public.has_permission(organization_id, 'purchasing.manage'));
create policy purchase_orders_read on public.purchase_orders for select
  using (public.has_permission(organization_id, 'purchasing.manage') or public.has_permission(organization_id, 'inventory.receive'));
create policy purchase_order_lines_read on public.purchase_order_lines for select
  using (public.has_permission(organization_id, 'purchasing.manage') or public.has_permission(organization_id, 'inventory.receive'));
create policy stock_transfers_read on public.stock_transfers for select using (public.has_permission(organization_id, 'inventory.view'));
create policy stock_transfer_lines_read on public.stock_transfer_lines for select using (public.has_permission(organization_id, 'inventory.view'));

select public._regrant_api();

-- ======================================================================
-- 0014_promotions_loyalty.sql
-- ======================================================================
-- 0014_promotions_loyalty.sql
-- Phase 8: promotions and coupons, gift cards, loyalty points, and non-stock
-- products (services, fees, gift cards) that never touch the stock ledger.
--
-- Pricing: promotions are worked out inside _write_order_lines (0008), so the
-- storefront quote, the till quote, checkout and the sale all agree. The best
-- promotion applies per line (never on top of a manual discount), plus at most
-- one order-level promotion (never on top of a manual order discount).
-- Promotional discounts do not count against a cashier's discount limit.
--
-- NOTE on enum values: Supabase runs a pasted script in one transaction, where a
-- value added by ALTER TYPE ... ADD VALUE cannot be used yet. The new values
-- below are only ever referenced inside function bodies, which run later.

set check_function_bodies = off;

alter type public.tracking_mode add value if not exists 'non_stock';
alter type public.payment_method add value if not exists 'gift_card';
alter type public.payment_method add value if not exists 'loyalty_points';

create type public.promotion_kind as enum ('percent_off', 'amount_off', 'buy_x_get_y');
create type public.promotion_scope as enum ('products', 'order');

-- ---------------------------------------------------------------------------
-- Gift card products
-- ---------------------------------------------------------------------------
alter table public.products add column is_gift_card boolean not null default false;

create or replace function public.products_gift_card_guard() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if new.is_gift_card then
    perform public.assert_module(new.organization_id, 'loyalty');
    if new.tracking_mode <> 'non_stock' then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'a gift card is a non-stock product';
    end if;
    new.tax_exempt := true;  -- a gift card is money, not goods
  end if;
  return new;
end $$;
create trigger products_gift_card_guard before insert or update of is_gift_card, tracking_mode on public.products
  for each row execute function public.products_gift_card_guard();

-- ---------------------------------------------------------------------------
-- Promotions
-- ---------------------------------------------------------------------------
create table public.promotions (
  id              uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete cascade,
  name            text not null check (length(btrim(name)) > 0),
  kind            public.promotion_kind not null,
  scope           public.promotion_scope not null,
  value           numeric(14,2) not null default 0 check (value >= 0),
  buy_quantity    int check (buy_quantity is null or buy_quantity >= 1),
  get_quantity    int check (get_quantity is null or get_quantity >= 1),
  min_subtotal    numeric(14,2) check (min_subtotal is null or min_subtotal >= 0),
  product_ids     uuid[] not null default '{}',
  category_ids    uuid[] not null default '{}',
  brand_ids       uuid[] not null default '{}',
  coupon_code     text check (coupon_code is null or coupon_code ~ '^[A-Z0-9_-]{3,32}$'),
  channels        public.sales_channel[],
  starts_at       timestamptz,
  ends_at         timestamptz,
  usage_limit     int check (usage_limit is null or usage_limit >= 1),
  usage_count     int not null default 0,
  is_active       boolean not null default true,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  unique (organization_id, id),
  check (kind <> 'percent_off' or value <= 100),
  check (kind <> 'buy_x_get_y' or (buy_quantity is not null and get_quantity is not null and scope = 'products')),
  check (ends_at is null or starts_at is null or ends_at > starts_at)
);
create unique index promotions_coupon_uq on public.promotions (organization_id, coupon_code) where coupon_code is not null;
create trigger promotions_touch before update on public.promotions for each row execute function public.touch_updated_at();
create trigger promotions_audit after insert or update on public.promotions for each row execute function public.audit_row();

alter table public.orders
  add column coupon_code          text,
  add column promo_discount_total numeric(14,2) not null default 0;
alter table public.order_lines add column promo_discount numeric(14,2) not null default 0;

create table public.order_promotions (
  organization_id uuid not null,
  order_id        uuid not null,
  promotion_id    uuid not null,
  amount          numeric(14,2) not null,
  primary key (order_id, promotion_id),
  foreign key (organization_id, order_id) references public.orders (organization_id, id) on delete cascade,
  foreign key (organization_id, promotion_id) references public.promotions (organization_id, id)
);

-- Promotions a line or an order could take right now.
create or replace function public._live_promotions(p_org uuid, p_channel public.sales_channel, p_coupon text)
returns setof public.promotions
language sql stable security definer set search_path = public, pg_temp as $$
  select p.* from public.promotions p
   where p.organization_id = p_org and p.is_active and public.module_enabled(p_org, 'promotions')
     and (p.starts_at is null or p.starts_at <= now()) and (p.ends_at is null or p.ends_at > now())
     and (p.channels is null or p_channel = any (p.channels))
     and (p.usage_limit is null or p.usage_count < p.usage_limit)
     and (p.coupon_code is null or p.coupon_code = p_coupon)
$$;

-- ---------------------------------------------------------------------------
-- Gift cards
-- ---------------------------------------------------------------------------
create table public.gift_cards (
  id              uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete cascade,
  code            text not null,
  initial_value   numeric(14,2) not null check (initial_value > 0),
  balance         numeric(14,2) not null default 0 check (balance >= 0),
  status          text not null default 'active' check (status in ('active', 'void')),
  expires_on      date,
  customer_id     uuid,
  order_line_id   uuid,
  note            text,
  created_by      uuid default auth.uid(),
  created_at      timestamptz not null default now(),
  unique (organization_id, code),
  unique (organization_id, id),
  foreign key (organization_id, customer_id) references public.customers (organization_id, id),
  foreign key (organization_id, order_line_id) references public.order_lines (organization_id, id)
);

create table public.gift_card_ledger (
  id              bigint generated always as identity primary key,
  organization_id uuid not null,
  gift_card_id    uuid not null,
  amount          numeric(14,2) not null check (amount <> 0),
  reason          text not null,
  order_id        uuid,
  created_by      uuid default auth.uid(),
  created_at      timestamptz not null default now(),
  foreign key (organization_id, gift_card_id) references public.gift_cards (organization_id, id)
);

create or replace function public.gift_card_apply() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v public.gift_cards%rowtype;
begin
  select * into v from public.gift_cards where id = new.gift_card_id for update;
  if new.amount < 0 and (v.status <> 'active' or (v.expires_on is not null and v.expires_on < current_date)) then
    raise exception using errcode = 'NC006', message = 'INVALID_STATE', detail = 'this gift card is not active';
  end if;
  if v.balance + new.amount < 0 then
    raise exception using errcode = 'NC007', message = 'INSUFFICIENT_GIFT_CARD',
      detail = json_build_object('balance', v.balance, 'requested', -new.amount)::text;
  end if;
  update public.gift_cards set balance = balance + new.amount where id = v.id;
  return new;
end $$;
create trigger gift_card_ledger_apply before insert on public.gift_card_ledger for each row execute function public.gift_card_apply();
create trigger gift_card_ledger_append_only before update or delete on public.gift_card_ledger for each row execute function public.prevent_mutation();

-- XXXX-XXXX-XXXX-XXXX from an alphabet without look-alikes (no 0/O, 1/I/L).
create or replace function public._new_gift_card_code(p_org uuid) returns text
language plpgsql volatile security definer set search_path = public, pg_temp as $$
declare
  v_alpha constant text := 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
  v_bytes bytea;
  v_code  text;
begin
  loop
    v_bytes := extensions.gen_random_bytes(16);
    v_code := '';
    for i in 0..15 loop
      v_code := v_code || substr(v_alpha, (get_byte(v_bytes, i) % length(v_alpha)) + 1, 1);
      if i in (3, 7, 11) then v_code := v_code || '-'; end if;
    end loop;
    exit when not exists (select 1 from public.gift_cards where organization_id = p_org and code = v_code);
  end loop;
  return v_code;
end $$;

create or replace function public._issue_gift_card(p_org uuid, p_amount numeric, p_reason text, p_customer uuid, p_order_line uuid, p_order uuid)
returns public.gift_cards
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v public.gift_cards%rowtype;
begin
  insert into public.gift_cards (organization_id, code, initial_value, customer_id, order_line_id, note)
  values (p_org, public._new_gift_card_code(p_org), p_amount, p_customer, p_order_line, p_reason)
  returning * into v;
  insert into public.gift_card_ledger (organization_id, gift_card_id, amount, reason, order_id)
  values (p_org, v.id, p_amount, p_reason, p_order);
  select * into v from public.gift_cards where id = v.id;
  return v;
end $$;

-- ---------------------------------------------------------------------------
-- Loyalty points
-- ---------------------------------------------------------------------------
alter table public.customers
  add column loyalty_points int not null default 0,
  add constraint customers_loyalty_nonneg check (loyalty_points >= 0);

create table public.loyalty_ledger (
  id              bigint generated always as identity primary key,
  organization_id uuid not null,
  customer_id     uuid not null,
  points          int not null check (points <> 0),
  reason          text not null,
  source_type     text not null,
  source_id       uuid,
  created_by      uuid default auth.uid(),
  created_at      timestamptz not null default now(),
  foreign key (organization_id, customer_id) references public.customers (organization_id, id)
);
create index loyalty_ledger_customer_idx on public.loyalty_ledger (customer_id, created_at desc);
create unique index loyalty_ledger_earn_once on public.loyalty_ledger (source_id) where source_type = 'order_earned';

create or replace function public.loyalty_apply() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_points int;
begin
  select loyalty_points into v_points from public.customers where id = new.customer_id for update;
  if v_points + new.points < 0 then
    raise exception using errcode = 'NC007', message = 'INSUFFICIENT_POINTS',
      detail = json_build_object('balance', v_points, 'requested', -new.points)::text;
  end if;
  update public.customers set loyalty_points = loyalty_points + new.points where id = new.customer_id;
  return new;
end $$;
create trigger loyalty_ledger_apply before insert on public.loyalty_ledger for each row execute function public.loyalty_apply();
create trigger loyalty_ledger_append_only before update or delete on public.loyalty_ledger for each row execute function public.prevent_mutation();

-- settings.loyalty_points_per_100 (default 1): points earned per 100 spent.
-- settings.loyalty_point_value (default 1): currency value of one point when spent.
-- settings.loyalty_min_redeem (default 0): fewest points spent at once.
create or replace function public._loyalty_setting(p_org uuid, p_key text, p_default numeric) returns numeric
language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce((settings->>p_key)::numeric, p_default) from public.organizations where id = p_org
$$;

-- What spend earns points: the order total less delivery, gift cards bought and
-- whatever was paid with points.
create or replace function public._award_loyalty(p_order uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  o        public.orders%rowtype;
  v_amount numeric;
  v_points int;
begin
  select * into o from public.orders where id = p_order;
  if o.customer_id is null or o.status not in ('confirmed', 'completed') or not public.module_enabled(o.organization_id, 'loyalty') then
    return;
  end if;
  if exists (select 1 from public.loyalty_ledger where source_type = 'order_earned' and source_id = o.id) then
    return;
  end if;
  v_amount := o.total - o.shipping_total
            - coalesce((select sum(ol.line_total) from public.order_lines ol
                          join public.product_variants v on v.id = ol.variant_id join public.products p on p.id = v.product_id
                         where ol.order_id = o.id and p.is_gift_card), 0)
            - coalesce((select sum(py.amount) from public.payments py
                         where py.order_id = o.id and py.kind = 'payment' and py.method = 'loyalty_points' and py.status = 'captured'), 0);
  v_points := floor(greatest(v_amount, 0) / 100 * public._loyalty_setting(o.organization_id, 'loyalty_points_per_100', 1));
  if v_points > 0 then
    insert into public.loyalty_ledger (organization_id, customer_id, points, reason, source_type, source_id)
    values (o.organization_id, o.customer_id, v_points, 'Earned on ' || o.number, 'order_earned', o.id);
  end if;
end $$;

-- A return takes back what that part of the sale earned (never below zero).
create or replace function public._return_loyalty(p_return uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  r        public.returns%rowtype;
  o        public.orders%rowtype;
  v_points int;
  v_have   int;
begin
  select * into r from public.returns where id = p_return;
  select * into o from public.orders where id = r.order_id;
  if o.customer_id is null or not exists (select 1 from public.loyalty_ledger where source_type = 'order_earned' and source_id = o.id) then
    return;
  end if;
  v_points := floor(r.refund_total / 100 * public._loyalty_setting(o.organization_id, 'loyalty_points_per_100', 1));
  select loyalty_points into v_have from public.customers where id = o.customer_id for update;
  v_points := least(v_points, v_have);
  if v_points > 0 then
    insert into public.loyalty_ledger (organization_id, customer_id, points, reason, source_type, source_id)
    values (o.organization_id, o.customer_id, -v_points, 'Returned ' || r.number, 'return', r.id);
  end if;
end $$;

-- Gift cards bought on a confirmed order are issued once, one card per unit.
create or replace function public._issue_order_gift_cards(p_order uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  o public.orders%rowtype;
  l record;
begin
  select * into o from public.orders where id = p_order;
  if o.status not in ('confirmed', 'completed') then return; end if;
  for l in
    select ol.* from public.order_lines ol
      join public.product_variants v on v.id = ol.variant_id join public.products p on p.id = v.product_id
     where ol.order_id = o.id and p.is_gift_card
       and not exists (select 1 from public.gift_cards g where g.order_line_id = ol.id)
  loop
    for i in 1..(l.quantity::int) loop
      perform public._issue_gift_card(o.organization_id, l.unit_price, 'Sold on ' || o.number, o.customer_id, l.id, o.id);
    end loop;
  end loop;
end $$;

-- Everything that happens once an order is confirmed (sale at the counter, or
-- an online order's payment arriving).
create or replace function public._after_confirm(p_order uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  perform public._issue_order_gift_cards(p_order);
  perform public._award_loyalty(p_order);
end $$;

-- ---------------------------------------------------------------------------
-- Commands
-- ---------------------------------------------------------------------------
-- p_promo = {id?, name, kind, scope, value, buy_quantity?, get_quantity?, min_subtotal?,
--            product_ids?, category_ids?, brand_ids?, coupon_code?, channels?, starts_at?,
--            ends_at?, usage_limit?, is_active?}
create or replace function public.save_promotion(p_organization_id uuid, p_promo jsonb) returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_id   uuid := nullif(p_promo->>'id', '')::uuid;
  v_code text := nullif(upper(btrim(coalesce(p_promo->>'coupon_code', ''))), '');
  v_row  public.promotions%rowtype;
begin
  perform public.assert_module(p_organization_id, 'promotions');
  perform public.assert_permission(p_organization_id, 'catalog.manage');
  v_row.organization_id := p_organization_id;
  v_row.name := btrim(p_promo->>'name');
  v_row.kind := (p_promo->>'kind')::public.promotion_kind;
  v_row.scope := coalesce(p_promo->>'scope', 'products')::public.promotion_scope;
  v_row.value := coalesce((p_promo->>'value')::numeric, 0);
  v_row.buy_quantity := (p_promo->>'buy_quantity')::int;
  v_row.get_quantity := (p_promo->>'get_quantity')::int;
  v_row.min_subtotal := (p_promo->>'min_subtotal')::numeric;
  v_row.product_ids := coalesce(array(select jsonb_array_elements_text(p_promo->'product_ids'))::uuid[], '{}');
  v_row.category_ids := coalesce(array(select jsonb_array_elements_text(p_promo->'category_ids'))::uuid[], '{}');
  v_row.brand_ids := coalesce(array(select jsonb_array_elements_text(p_promo->'brand_ids'))::uuid[], '{}');
  v_row.coupon_code := v_code;
  v_row.channels := case when jsonb_typeof(p_promo->'channels') = 'array' and jsonb_array_length(p_promo->'channels') > 0
                         then array(select jsonb_array_elements_text(p_promo->'channels'))::public.sales_channel[] end;
  v_row.starts_at := nullif(p_promo->>'starts_at', '')::timestamptz;
  v_row.ends_at := nullif(p_promo->>'ends_at', '')::timestamptz;
  v_row.usage_limit := (p_promo->>'usage_limit')::int;
  v_row.is_active := coalesce((p_promo->>'is_active')::boolean, true);
  if v_row.kind <> 'buy_x_get_y' and v_row.value <= 0 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'give the discount a value';
  end if;

  begin
    if v_id is null then
      insert into public.promotions (organization_id, name, kind, scope, value, buy_quantity, get_quantity, min_subtotal, product_ids,
                                     category_ids, brand_ids, coupon_code, channels, starts_at, ends_at, usage_limit, is_active)
      values (v_row.organization_id, v_row.name, v_row.kind, v_row.scope, v_row.value, v_row.buy_quantity, v_row.get_quantity,
              v_row.min_subtotal, v_row.product_ids, v_row.category_ids, v_row.brand_ids, v_row.coupon_code, v_row.channels,
              v_row.starts_at, v_row.ends_at, v_row.usage_limit, v_row.is_active)
      returning id into v_id;
    else
      update public.promotions
         set name = v_row.name, kind = v_row.kind, scope = v_row.scope, value = v_row.value, buy_quantity = v_row.buy_quantity,
             get_quantity = v_row.get_quantity, min_subtotal = v_row.min_subtotal, product_ids = v_row.product_ids,
             category_ids = v_row.category_ids, brand_ids = v_row.brand_ids, coupon_code = v_row.coupon_code, channels = v_row.channels,
             starts_at = v_row.starts_at, ends_at = v_row.ends_at, usage_limit = v_row.usage_limit, is_active = v_row.is_active
       where id = v_id and organization_id = p_organization_id;
      if not found then raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'promotion'; end if;
    end if;
  exception
    when unique_violation then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = format('the code %s is already used by another promotion', v_code);
    when check_violation then
      raise exception using errcode = 'NC003', message = 'INVALID_INPUT',
        detail = 'check the promotion: percent 0-100, buy/get quantities for buy-X-get-Y (products only), codes 3-32 letters/digits, end after start';
  end;
  return v_id;
end $$;

-- Balance and history of a gift card (the till checks it before taking it).
create or replace function public.gift_card_lookup(p_organization_id uuid, p_code text) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  g public.gift_cards%rowtype;
begin
  perform public.assert_module(p_organization_id, 'loyalty');
  if not (public.has_permission(p_organization_id, 'pos.sell') or public.has_permission(p_organization_id, 'orders.view')) then
    raise exception using errcode = '42501', message = 'PERMISSION_DENIED', detail = 'pos.sell';
  end if;
  select * into g from public.gift_cards where organization_id = p_organization_id and code = upper(btrim(p_code));
  if not found then
    raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'no gift card has that code';
  end if;
  return jsonb_build_object('gift_card_id', g.id, 'code', g.code, 'balance', g.balance, 'initial_value', g.initial_value,
    'status', case when g.status = 'void' then 'void' when g.expires_on < current_date then 'expired'
                   when g.balance = 0 then 'used' else 'active' end,
    'expires_on', g.expires_on, 'created_at', g.created_at,
    'history', (select jsonb_agg(jsonb_build_object('amount', l.amount, 'reason', l.reason, 'at', l.created_at) order by l.id)
                  from public.gift_card_ledger l where l.gift_card_id = g.id));
end $$;

-- A card given away (goodwill, a prize, a replacement) rather than sold.
create or replace function public.issue_gift_card(p_organization_id uuid, p_amount numeric, p_reason text, p_customer_id uuid default null)
returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  g public.gift_cards%rowtype;
begin
  perform public.assert_module(p_organization_id, 'loyalty');
  perform public.assert_permission(p_organization_id, 'orders.manage');
  if p_amount is null or p_amount <= 0 or coalesce(btrim(p_reason), '') = '' then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'an amount and a reason are required';
  end if;
  g := public._issue_gift_card(p_organization_id, p_amount, btrim(p_reason), p_customer_id, null, null);
  return public.gift_card_lookup(p_organization_id, g.code);
end $$;

create or replace function public.void_gift_card(p_organization_id uuid, p_code text, p_reason text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  perform public.assert_permission(p_organization_id, 'orders.manage');
  update public.gift_cards set status = 'void', note = concat_ws(E'\n', note, 'Void: ' || p_reason)
   where organization_id = p_organization_id and code = upper(btrim(p_code)) and status = 'active';
  if not found then raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'no active gift card has that code'; end if;
end $$;

create or replace function public.adjust_loyalty_points(p_customer_id uuid, p_points int, p_reason text) returns int
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_org uuid;
begin
  select organization_id into v_org from public.customers where id = p_customer_id;
  if v_org is null then raise exception using errcode = 'NC005', message = 'NOT_FOUND', detail = 'customer'; end if;
  perform public.assert_module(v_org, 'loyalty');
  perform public.assert_permission(v_org, 'orders.manage');
  if coalesce(p_points, 0) = 0 or coalesce(btrim(p_reason), '') = '' then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'points and a reason are required';
  end if;
  insert into public.loyalty_ledger (organization_id, customer_id, points, reason, source_type)
  values (v_org, p_customer_id, p_points, btrim(p_reason), 'adjustment');
  return (select loyalty_points from public.customers where id = p_customer_id);
end $$;

-- ---------------------------------------------------------------------------
-- Security
-- ---------------------------------------------------------------------------
alter table public.promotions enable row level security;
alter table public.order_promotions enable row level security;
alter table public.gift_cards enable row level security;
alter table public.gift_card_ledger enable row level security;
alter table public.loyalty_ledger enable row level security;

grant select on public.promotions, public.order_promotions, public.gift_cards, public.gift_card_ledger, public.loyalty_ledger to authenticated;
grant all on public.promotions, public.order_promotions, public.gift_cards, public.gift_card_ledger, public.loyalty_ledger to service_role;
revoke all on public.promotions, public.order_promotions, public.gift_cards, public.gift_card_ledger, public.loyalty_ledger from anon;
revoke insert, update, delete, truncate on public.promotions, public.order_promotions, public.gift_cards, public.gift_card_ledger, public.loyalty_ledger from authenticated;
-- The loyalty balance and gift-card flag move only through their own paths.
revoke update (loyalty_points) on public.customers from authenticated;

create policy promotions_read on public.promotions for select using (public.is_member(organization_id));
create policy order_promotions_read on public.order_promotions for select
  using (public.has_permission(organization_id, 'orders.view') or public.owns_order(order_id));
create policy gift_cards_read on public.gift_cards for select using (public.has_permission(organization_id, 'orders.view'));
create policy gift_card_ledger_read on public.gift_card_ledger for select using (public.has_permission(organization_id, 'orders.view'));
create policy loyalty_ledger_read on public.loyalty_ledger for select
  using (public.has_permission(organization_id, 'customers.view')
         or exists (select 1 from public.customers c where c.id = customer_id and c.auth_user_id = auth.uid()));

select public._regrant_api();

-- ======================================================================
-- 0015_analytics.sql
-- ======================================================================
-- 0015_analytics.sql
-- Reports across every channel, read live from the same ledgers the tills and
-- the store write. There are no copies or nightly jobs, so a report is always
-- current and always agrees with the orders behind it.
--
-- Definitions (the same in every report):
--   * A sale counts once its order is confirmed or completed, on the day it was
--     placed, in the business's own time zone.
--   * Net sales = what the goods sold for after every discount, excluding tax,
--     less returns (on the day of the return). Delivery fees are shown on their own.
--   * Gift cards sold are money held for the customer, not a sale: they are
--     counted separately and left out of sales, items and profit.
--   * Cost of goods = the cost recorded on each unit as it left stock. A return
--     put back on sale gives that cost back; one written off or damaged does not,
--     so the loss shows in profit. A return still awaiting inspection has not
--     given its cost back yet.
--   * A manager limited to some locations sees only those locations.
-- Every report needs `reports.view`.

-- ---------------------------------------------------------------------------
-- Indexes for reporting reads
-- ---------------------------------------------------------------------------
create index if not exists inventory_movements_org_type_time_idx
  on public.inventory_movements (organization_id, movement_type, created_at);
create index if not exists inventory_movements_variant_type_time_idx
  on public.inventory_movements (variant_id, movement_type, created_at);
create index if not exists orders_placed_by_idx on public.orders (organization_id, placed_by, placed_at);
create index if not exists order_promotions_promotion_idx on public.order_promotions (promotion_id);

-- ---------------------------------------------------------------------------
-- Scope helpers (never granted)
-- ---------------------------------------------------------------------------

-- The caller's locations: null means all of them.
create or replace function public._report_locations(p_org uuid) returns uuid[]
language sql stable security definer set search_path = public, pg_temp as $$
  select case when public.is_platform_admin() then null
              else (select m.location_ids from public.memberships m
                     where m.organization_id = p_org and m.user_id = auth.uid() and m.is_active) end
$$;

-- Checks the caller and the filters, and turns local dates into instants.
create or replace function public._report_begin(
  p_org uuid, p_from date, p_to date, p_location uuid,
  out w_start timestamptz, out w_end timestamptz, out tz text, out locs uuid[])
language plpgsql stable security definer set search_path = public, pg_temp as $$
begin
  perform public.assert_permission(p_org, 'reports.view');
  if p_location is not null then
    perform public.assert_location_access(p_org, p_location);
  end if;
  if p_from is null or p_to is null or p_to < p_from then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'choose a date range';
  end if;
  if p_to - p_from > 1100 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'a report covers at most three years';
  end if;
  select o.timezone into tz from public.organizations o where o.id = p_org;
  w_start := p_from::timestamp at time zone tz;
  w_end := (p_to + 1)::timestamp at time zone tz;
  locs := public._report_locations(p_org);
end $$;

-- Orders that count as sales in a window.
create or replace function public._report_orders(
  p_org uuid, p_start timestamptz, p_end timestamptz, p_locs uuid[], p_location uuid, p_channel public.sales_channel)
returns setof public.orders
language sql stable security definer set search_path = public, pg_temp as $$
  select o.* from public.orders o
   where o.organization_id = p_org and o.status in ('confirmed', 'completed')
     and o.placed_at >= p_start and o.placed_at < p_end
     and (p_locs is null or o.location_id = any (p_locs))
     and (p_location is null or o.location_id = p_location)
     and (p_channel is null or o.channel = p_channel)
$$;

-- One row per order line, with its share of the cost of the units that left stock.
create or replace function public._report_lines(
  p_org uuid, p_start timestamptz, p_end timestamptz, p_locs uuid[], p_location uuid, p_channel public.sales_channel)
returns table (order_id uuid, placed_at timestamptz, location_id uuid, channel public.sales_channel, customer_id uuid,
               placed_by uuid, line_id uuid, variant_id uuid, product_id uuid, category_id uuid, brand_id uuid,
               is_gift_card boolean, quantity numeric, gross numeric, discount numeric, promo numeric,
               net numeric, tax numeric, cost numeric)
language sql stable security definer set search_path = public, pg_temp as $$
  with o as (select * from public._report_orders(p_org, p_start, p_end, p_locs, p_location, p_channel)),
  l as (select ol.id as lid, ol.order_id as oid, ol.variant_id as vid, ol.quantity as qty, ol.line_subtotal, ol.discount_amount,
               ol.promo_discount, ol.line_total, ol.tax_amount, o.placed_at as placed, o.location_id as loc, o.channel as ch,
               o.customer_id as cust, o.placed_by as by_user, p.id as pid, p.category_id as cid, p.brand_id as bid, p.is_gift_card as gift
          from o join public.order_lines ol on ol.order_id = o.id
          join public.product_variants v on v.id = ol.variant_id
          join public.products p on p.id = v.product_id),
  c as (select m.source_id as oid, m.variant_id as vid, sum(-m.quantity * coalesce(m.unit_cost, 0)) as cost
          from public.inventory_movements m
         where m.organization_id = p_org and m.source_type = 'order' and m.movement_type = 'sale'
           and m.source_id in (select id from o)
         group by 1, 2),
  q as (select oid, vid, sum(qty) as qty from l group by 1, 2)
  select l.oid, l.placed, l.loc, l.ch, l.cust, l.by_user, l.lid, l.vid, l.pid, l.cid, l.bid, l.gift,
         l.qty, l.line_subtotal, l.discount_amount, l.promo_discount, l.line_total - l.tax_amount, l.tax_amount,
         coalesce(round(c.cost * l.qty / nullif(q.qty, 0), 2), 0)
    from l
    left join q on q.oid = l.oid and q.vid = l.vid
    left join c on c.oid = l.oid and c.vid = l.vid
$$;

-- One row per returned line in a window, valued excluding tax.
create or replace function public._report_returns(
  p_org uuid, p_start timestamptz, p_end timestamptz, p_locs uuid[], p_location uuid, p_channel public.sales_channel)
returns table (return_id uuid, requested_at timestamptz, order_id uuid, location_id uuid, channel public.sales_channel,
               variant_id uuid, product_id uuid, category_id uuid, brand_id uuid, quantity numeric,
               value numeric, refund numeric, cost_back numeric, created_by uuid)
language sql stable security definer set search_path = public, pg_temp as $$
  select r.id, r.requested_at, o.id, o.location_id, o.channel, rl.variant_id, p.id, p.category_id, p.brand_id, rl.quantity,
         coalesce(round(rl.line_refund * (ol.line_total - ol.tax_amount) / nullif(ol.line_total, 0), 2), 0),
         rl.line_refund,
         case when rl.disposition = 'restock' then round(rl.quantity * coalesce(rl.unit_cost, 0), 2) else 0 end,
         r.created_by
    from public.returns r
    join public.return_lines rl on rl.return_id = r.id
    join public.order_lines ol on ol.id = rl.order_line_id
    join public.orders o on o.id = r.order_id
    join public.product_variants v on v.id = rl.variant_id
    join public.products p on p.id = v.product_id
   where r.organization_id = p_org and r.status <> 'cancelled'
     and r.requested_at >= p_start and r.requested_at < p_end
     and (p_locs is null or o.location_id = any (p_locs))
     and (p_location is null or o.location_id = p_location)
     and (p_channel is null or o.channel = p_channel)
$$;

-- The headline numbers for a window.
create or replace function public._report_totals(
  p_org uuid, p_start timestamptz, p_end timestamptz, p_locs uuid[], p_location uuid, p_channel public.sales_channel)
returns jsonb
language sql stable security definer set search_path = public, pg_temp as $$
  with o as (select * from public._report_orders(p_org, p_start, p_end, p_locs, p_location, p_channel)),
  l as (select * from public._report_lines(p_org, p_start, p_end, p_locs, p_location, p_channel)),
  r as (select * from public._report_returns(p_org, p_start, p_end, p_locs, p_location, p_channel)),
  t as (
    select (select count(*) from o) as orders,
           (select coalesce(sum(total), 0) from o) as order_value,
           (select coalesce(sum(shipping_total), 0) from o) as shipping,
           (select count(distinct customer_id) from o) as customers,
           (select coalesce(sum(quantity), 0) from l where not is_gift_card) as items,
           (select coalesce(sum(gross), 0) from l where not is_gift_card) as gross,
           (select coalesce(sum(discount), 0) from l where not is_gift_card) as discounts,
           (select coalesce(sum(promo), 0) from l where not is_gift_card) as promo,
           (select coalesce(sum(net), 0) from l where not is_gift_card) as net,
           (select coalesce(sum(tax), 0) from l) as tax,
           (select coalesce(sum(cost), 0) from l where not is_gift_card) as cost,
           (select coalesce(sum(net), 0) from l where is_gift_card) as gift_cards_sold,
           (select coalesce(sum(value), 0) from r) as returns,
           (select coalesce(sum(quantity), 0) from r) as returned_items,
           (select coalesce(sum(cost_back), 0) from r) as cost_back)
  select jsonb_build_object(
    'orders', orders, 'order_value', order_value, 'shipping', shipping, 'customers', customers,
    'items', items, 'gross', gross, 'discounts', discounts, 'promo_discounts', promo, 'manual_discounts', discounts - promo,
    'tax', tax, 'returns', returns, 'returned_items', returned_items,
    'net_sales', net - returns, 'cogs', cost - cost_back, 'gross_profit', net - returns - (cost - cost_back),
    'margin', case when net - returns > 0 then round((net - returns - (cost - cost_back)) * 100 / (net - returns), 1) end,
    'average_sale', case when orders > 0 then round(order_value / orders, 2) end,
    'items_per_sale', case when orders > 0 then round(items / orders, 2) end,
    'gift_cards_sold', gift_cards_sold)
  from t
$$;

-- ---------------------------------------------------------------------------
-- Reports
-- ---------------------------------------------------------------------------

-- Sales overview: totals against the previous period of the same length, a
-- series by day, week or month, the split by channel, location and payment
-- method, and a weekday-by-hour grid.
create or replace function public.report_sales(
  p_organization_id uuid, p_from date, p_to date, p_location_id uuid default null,
  p_channel public.sales_channel default null, p_interval text default 'day')
returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  w         record;
  p         record;
  v_days    int := p_to - p_from + 1;
  v_step    interval;
  v_result  jsonb;
begin
  select * into w from public._report_begin(p_organization_id, p_from, p_to, p_location_id);
  if p_interval not in ('day', 'week', 'month') then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'group by day, week or month';
  end if;
  v_step := ('1 ' || p_interval)::interval;
  select * into p from public._report_begin(p_organization_id, p_from - v_days, p_from - 1, p_location_id);

  with l as (select * from public._report_lines(p_organization_id, w.w_start, w.w_end, w.locs, p_location_id, p_channel) where not is_gift_card),
  r as (select * from public._report_returns(p_organization_id, w.w_start, w.w_end, w.locs, p_location_id, p_channel)),
  o as (select * from public._report_orders(p_organization_id, w.w_start, w.w_end, w.locs, p_location_id, p_channel)),
  buckets as (
    select g::date as bucket
      from generate_series(date_trunc(p_interval, p_from::timestamp), p_to::timestamp, v_step) g),
  ls as (select date_trunc(p_interval, (placed_at at time zone w.tz))::date as bucket, order_id, net, cost from l),
  rs as (select date_trunc(p_interval, (requested_at at time zone w.tz))::date as bucket, value, cost_back from r)
  select jsonb_build_object(
    'range', jsonb_build_object('from', p_from, 'to', p_to, 'previous_from', p_from - v_days, 'previous_to', p_from - 1,
                                'interval', p_interval, 'timezone', w.tz),
    'totals', public._report_totals(p_organization_id, w.w_start, w.w_end, w.locs, p_location_id, p_channel),
    'previous', public._report_totals(p_organization_id, p.w_start, p.w_end, p.locs, p_location_id, p_channel),
    'series', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'bucket', b.bucket, 'orders', coalesce(la.orders, 0),
               'net_sales', coalesce(la.net, 0) - coalesce(ra.value, 0),
               'gross_profit', coalesce(la.profit, 0) - coalesce(ra.profit, 0))
             order by b.bucket), '[]'::jsonb)
        from buckets b
        left join (select bucket, count(distinct order_id) as orders, sum(net) as net, sum(net - cost) as profit
                     from ls group by bucket) la on la.bucket = b.bucket
        left join (select bucket, sum(value) as value, sum(value - cost_back) as profit
                     from rs group by bucket) ra on ra.bucket = b.bucket),
    'by_channel', (
      select coalesce(jsonb_agg(jsonb_build_object('channel', x.channel, 'orders', x.orders, 'net_sales', x.net_sales)
                                order by x.net_sales desc), '[]'::jsonb)
        from (select c.channel,
                     (select count(*) from o where o.channel = c.channel) as orders,
                     coalesce((select sum(net) from l where l.channel = c.channel), 0)
                       - coalesce((select sum(value) from r where r.channel = c.channel), 0) as net_sales
                from (select distinct channel from o union select distinct channel from r) c) x),
    'by_location', (
      select coalesce(jsonb_agg(jsonb_build_object('location_id', x.id, 'name', x.name, 'orders', x.orders, 'net_sales', x.net_sales)
                                order by x.net_sales desc), '[]'::jsonb)
        from (select loc.id, loc.name,
                     (select count(*) from o where o.location_id = loc.id) as orders,
                     coalesce((select sum(net) from l where l.location_id = loc.id), 0)
                       - coalesce((select sum(value) from r where r.location_id = loc.id), 0) as net_sales
                from public.locations loc
               where loc.id in (select location_id from o union select location_id from r)) x),
    'by_method', (
      select coalesce(jsonb_agg(jsonb_build_object('method', x.method, 'taken', x.taken, 'refunded', x.refunded, 'net', x.taken - x.refunded)
                                order by x.taken - x.refunded desc), '[]'::jsonb)
        from (select pm.method,
                     coalesce(sum(pm.amount) filter (where pm.kind = 'payment'), 0) as taken,
                     coalesce(sum(pm.amount) filter (where pm.kind = 'refund'), 0) as refunded
                from public.payments pm join public.orders ord on ord.id = pm.order_id
               where pm.organization_id = p_organization_id and pm.status = 'captured'
                 and pm.created_at >= w.w_start and pm.created_at < w.w_end
                 and (w.locs is null or ord.location_id = any (w.locs))
                 and (p_location_id is null or ord.location_id = p_location_id)
                 and (p_channel is null or ord.channel = p_channel)
               group by pm.method) x),
    'by_hour', (
      select coalesce(jsonb_agg(jsonb_build_object('weekday', x.dow, 'hour', x.hr, 'orders', x.orders, 'net_sales', x.net)
                                order by x.dow, x.hr), '[]'::jsonb)
        from (select extract(isodow from (placed_at at time zone w.tz))::int as dow,
                     extract(hour from (placed_at at time zone w.tz))::int as hr,
                     count(distinct order_id) as orders, sum(net) as net
                from l group by 1, 2) x))
  into v_result;
  return v_result;
end $$;

-- Products, variants, categories or brands, ranked by net sales.
create or replace function public.report_products(
  p_organization_id uuid, p_from date, p_to date, p_location_id uuid default null,
  p_channel public.sales_channel default null, p_group text default 'product', p_limit int default 100)
returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  w        record;
  v_result jsonb;
begin
  select * into w from public._report_begin(p_organization_id, p_from, p_to, p_location_id);
  if p_group not in ('product', 'variant', 'category', 'brand') then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'group by product, variant, category or brand';
  end if;

  with l as (select * from public._report_lines(p_organization_id, w.w_start, w.w_end, w.locs, p_location_id, p_channel) where not is_gift_card),
  r as (select * from public._report_returns(p_organization_id, w.w_start, w.w_end, w.locs, p_location_id, p_channel)),
  lk as (select case p_group when 'product' then product_id when 'variant' then variant_id
                             when 'category' then category_id else brand_id end as k, * from l),
  rk as (select case p_group when 'product' then product_id when 'variant' then variant_id
                             when 'category' then category_id else brand_id end as k, * from r),
  g as (
    select k,
           sum(quantity) as quantity, count(distinct order_id) as orders, sum(net) as net, sum(cost) as cost,
           sum(discount) as discounts
      from lk group by k),
  gr as (select k, sum(quantity) as quantity, sum(value) as value, sum(cost_back) as cost_back from rk group by k),
  keys as (select k from g union select k from gr),
  rws as (
    select keys.k,
           coalesce(g.quantity, 0) as quantity, coalesce(g.orders, 0) as orders, coalesce(g.discounts, 0) as discounts,
           coalesce(g.net, 0) - coalesce(gr.value, 0) as net_sales,
           coalesce(g.cost, 0) - coalesce(gr.cost_back, 0) as cogs,
           coalesce(gr.quantity, 0) as returned
      from keys
      left join g on g.k is not distinct from keys.k
      left join gr on gr.k is not distinct from keys.k),
  total as (select sum(net_sales) as net from rws)
  select jsonb_build_object(
    'group', p_group,
    'net_sales', coalesce((select net from total), 0),
    'count', (select count(*) from rws),
    'rows', coalesce((
      select jsonb_agg(x.j order by x.net_sales desc, x.name)
        from (
          select rws.net_sales, coalesce(nm.name, '') as name, jsonb_build_object(
                   'id', rws.k, 'name', coalesce(nm.name, case p_group when 'category' then 'No category' when 'brand' then 'No brand' else '?' end),
                   'detail', nm.detail,
                   'quantity', rws.quantity, 'orders', rws.orders, 'discounts', rws.discounts,
                   'net_sales', rws.net_sales, 'cogs', rws.cogs, 'gross_profit', rws.net_sales - rws.cogs,
                   'margin', case when rws.net_sales > 0 then round((rws.net_sales - rws.cogs) * 100 / rws.net_sales, 1) end,
                   'returned', rws.returned,
                   'return_rate', case when rws.quantity > 0 then round(rws.returned * 100 / rws.quantity, 1) end,
                   'share', case when (select net from total) > 0 then round(rws.net_sales * 100 / (select net from total), 1) end) as j
            from rws
            left join lateral (
              select case p_group
                       when 'product'  then (select p.name from public.products p where p.id = rws.k)
                       when 'variant'  then (select p.name || case when v.title <> 'Default' then ' · ' || v.title else '' end
                                               from public.product_variants v join public.products p on p.id = v.product_id where v.id = rws.k)
                       when 'category' then (select c.name from public.categories c where c.id = rws.k)
                       else (select b.name from public.brands b where b.id = rws.k) end as name,
                     case when p_group = 'variant' then (select v.sku from public.product_variants v where v.id = rws.k) end as detail
            ) nm on true
           order by rws.net_sales desc
           limit greatest(coalesce(p_limit, 100), 1)) x), '[]'::jsonb))
  into v_result;
  return v_result;
end $$;

-- Stock value, cover and slow movers. p_days is the look-back for "sold" and
-- for "not sold since" (dead stock).
create or replace function public.report_inventory(
  p_organization_id uuid, p_location_id uuid default null, p_days int default 30)
returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  v_locs   uuid[];
  v_since  timestamptz;
  v_result jsonb;
begin
  perform public.assert_permission(p_organization_id, 'reports.view');
  if p_location_id is not null then
    perform public.assert_location_access(p_organization_id, p_location_id);
  end if;
  if p_days is null or p_days < 1 or p_days > 730 then
    raise exception using errcode = 'NC003', message = 'INVALID_INPUT', detail = 'look back between 1 and 730 days';
  end if;
  v_locs := public._report_locations(p_organization_id);
  v_since := now() - make_interval(days => p_days);

  with s as (
    select s.variant_id, sum(s.on_hand) as on_hand, sum(s.reserved) as reserved,
           sum(s.on_hand * s.avg_unit_cost) as value
      from public.stock_levels s
     where s.organization_id = p_organization_id
       and (v_locs is null or s.location_id = any (v_locs))
       and (p_location_id is null or s.location_id = p_location_id)
     group by s.variant_id),
  m as (
    select mv.variant_id,
           sum(case when mv.movement_type = 'sale' then -mv.quantity when mv.movement_type = 'sale_return' then -mv.quantity else 0 end)
             filter (where mv.created_at >= v_since) as sold,
           max(mv.created_at) filter (where mv.movement_type = 'sale') as last_sold_at,
           min(mv.created_at) filter (where mv.quantity > 0) as first_in_at
      from public.inventory_movements mv
     where mv.organization_id = p_organization_id
       and mv.variant_id in (select variant_id from s)
       and (v_locs is null or mv.location_id = any (v_locs))
       and (p_location_id is null or mv.location_id = p_location_id)
     group by mv.variant_id),
  items as (
    select v.id as variant_id, p.name as product, v.title as variant, v.sku, c.name as category,
           s.on_hand, s.reserved, round(s.value, 2) as value, round(s.on_hand * v.price, 2) as retail_value,
           coalesce(m.sold, 0) as sold, m.last_sold_at, m.first_in_at,
           case when coalesce(m.sold, 0) > 0 then round(s.on_hand / (m.sold / p_days::numeric), 0) end as days_cover,
           coalesce(s.on_hand > 0 and coalesce(m.last_sold_at < v_since, true) and m.first_in_at < v_since, false) as dead
      from s
      join public.product_variants v on v.id = s.variant_id
      join public.products p on p.id = v.product_id
      left join public.categories c on c.id = p.category_id
      left join m on m.variant_id = s.variant_id
     where p.tracking_mode <> 'non_stock')
  select jsonb_build_object(
    'days', p_days,
    'totals', (select jsonb_build_object(
                 'variants', count(*) filter (where on_hand > 0), 'units', coalesce(sum(on_hand), 0),
                 'value', coalesce(sum(value), 0), 'retail_value', coalesce(sum(retail_value), 0),
                 'dead_variants', count(*) filter (where dead), 'dead_value', coalesce(sum(value) filter (where dead), 0),
                 'out_of_stock', count(*) filter (where on_hand <= 0))
                 from items),
    'by_category', coalesce((
      select jsonb_agg(jsonb_build_object('category', x.category, 'units', x.units, 'value', x.value, 'retail_value', x.retail) order by x.value desc)
        from (select coalesce(category, 'No category') as category, sum(on_hand) as units, sum(value) as value, sum(retail_value) as retail
                from items where on_hand > 0 group by 1) x), '[]'::jsonb),
    'items', coalesce((
      select jsonb_agg(to_jsonb(x) order by x.value desc nulls last, x.product)
        from (select * from items where on_hand > 0 or sold > 0 order by value desc nulls last limit 2000) x), '[]'::jsonb))
  into v_result;
  return v_result;
end $$;

-- Customers: new against returning, walk-ins, repeat buyers and the top spenders.
create or replace function public.report_customers(
  p_organization_id uuid, p_from date, p_to date, p_location_id uuid default null,
  p_channel public.sales_channel default null, p_limit int default 20)
returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  w        record;
  v_result jsonb;
begin
  select * into w from public._report_begin(p_organization_id, p_from, p_to, p_location_id);

  with o as (select * from public._report_orders(p_organization_id, w.w_start, w.w_end, w.locs, p_location_id, p_channel)),
  c as (
    select o.customer_id, count(*) as orders, sum(o.total) as spent, max(o.placed_at) as last_at,
           -- New: their first counted order anywhere in the business falls in this window.
           not exists (select 1 from public.orders e
                        where e.customer_id = o.customer_id and e.status in ('confirmed', 'completed')
                          and e.placed_at < w.w_start) as is_new
      from o where o.customer_id is not null group by o.customer_id)
  select jsonb_build_object(
    'totals', jsonb_build_object(
      'orders', (select count(*) from o),
      'walk_in_orders', (select count(*) from o where customer_id is null),
      'walk_in_value', (select coalesce(sum(total), 0) from o where customer_id is null),
      'customers', (select count(*) from c),
      'new_customers', (select count(*) from c where is_new),
      'returning_customers', (select count(*) from c where not is_new),
      'new_value', (select coalesce(sum(spent), 0) from c where is_new),
      'returning_value', (select coalesce(sum(spent), 0) from c where not is_new),
      'repeat_customers', (select count(*) from c where orders > 1),
      'average_spend', (select round(avg(spent), 2) from c)),
    'top', coalesce((
      select jsonb_agg(jsonb_build_object('customer_id', x.customer_id, 'name', x.full_name, 'phone', x.phone,
                                          'orders', x.orders, 'spent', x.spent, 'last_order_at', x.last_at,
                                          'is_new', x.is_new, 'loyalty_points', x.loyalty_points) order by x.spent desc)
        from (select c.*, cu.full_name, cu.phone, cu.loyalty_points
                from c join public.customers cu on cu.id = c.customer_id
               order by c.spent desc limit greatest(coalesce(p_limit, 20), 1)) x), '[]'::jsonb))
  into v_result;
  return v_result;
end $$;

-- What promotions and manual discounts gave away, and what they sold.
create or replace function public.report_promotions(
  p_organization_id uuid, p_from date, p_to date, p_location_id uuid default null,
  p_channel public.sales_channel default null)
returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  w        record;
  v_result jsonb;
begin
  select * into w from public._report_begin(p_organization_id, p_from, p_to, p_location_id);

  with o as (select * from public._report_orders(p_organization_id, w.w_start, w.w_end, w.locs, p_location_id, p_channel)),
  l as (select * from public._report_lines(p_organization_id, w.w_start, w.w_end, w.locs, p_location_id, p_channel))
  select jsonb_build_object(
    'promo_discounts', (select coalesce(sum(promo), 0) from l),
    'manual_discounts', (select coalesce(sum(discount - promo), 0) from l),
    'orders_with_promotion', (select count(distinct op.order_id) from public.order_promotions op where op.order_id in (select id from o)),
    'orders_with_manual_discount', (select count(distinct order_id) from l where discount > promo),
    'promotions', coalesce((
      select jsonb_agg(jsonb_build_object('promotion_id', x.id, 'name', x.name, 'kind', x.kind, 'coupon_code', x.coupon_code,
                                          'orders', x.orders, 'discount', x.discount, 'order_value', x.order_value,
                                          'is_active', x.is_active) order by x.discount desc)
        from (select pm.id, pm.name, pm.kind, pm.coupon_code, pm.is_active,
                     count(*) as orders, sum(op.amount) as discount, sum(ord.total) as order_value
                from public.order_promotions op
                join o ord on ord.id = op.order_id
                join public.promotions pm on pm.id = op.promotion_id
               group by pm.id) x), '[]'::jsonb))
  into v_result;
  return v_result;
end $$;

-- Who sold what: sales, discounts given and returns taken, per person. Online
-- and app orders placed by customers are grouped as self-service.
create or replace function public.report_staff(
  p_organization_id uuid, p_from date, p_to date, p_location_id uuid default null,
  p_channel public.sales_channel default null)
returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  w        record;
  v_result jsonb;
begin
  select * into w from public._report_begin(p_organization_id, p_from, p_to, p_location_id);

  with o as (select * from public._report_orders(p_organization_id, w.w_start, w.w_end, w.locs, p_location_id, p_channel)),
  l as (select * from public._report_lines(p_organization_id, w.w_start, w.w_end, w.locs, p_location_id, p_channel)),
  r as (select return_id, created_by, sum(refund) as refund
          from public._report_returns(p_organization_id, w.w_start, w.w_end, w.locs, p_location_id, p_channel)
         group by 1, 2),
  -- Staff are members; anyone else who placed an order is a customer serving themselves.
  who as (
    select distinct x.uid, (m.user_id is not null) as staff
      from (select placed_by as uid from o union select created_by from r) x
      left join public.memberships m on m.organization_id = p_organization_id and m.user_id = x.uid),
  s as (
    select case when who.staff then who.uid end as uid,
           (select count(*) from o where o.placed_by = who.uid) as orders,
           (select coalesce(sum(total), 0) from o where o.placed_by = who.uid) as order_value,
           (select coalesce(sum(net), 0) from l where l.placed_by = who.uid and not l.is_gift_card) as net,
           (select coalesce(sum(quantity), 0) from l where l.placed_by = who.uid and not l.is_gift_card) as items,
           (select coalesce(sum(discount - promo), 0) from l where l.placed_by = who.uid) as manual_discounts,
           (select count(*) from r where r.created_by = who.uid) as returns,
           (select coalesce(sum(refund), 0) from r where r.created_by = who.uid) as refunded
      from who),
  g as (
    select uid, sum(orders) as orders, sum(order_value) as order_value, sum(net) as net, sum(items) as items,
           sum(manual_discounts) as manual_discounts, sum(returns) as returns, sum(refunded) as refunded
      from s group by uid)
  select coalesce(jsonb_agg(jsonb_build_object(
           'user_id', g.uid,
           'name', case when g.uid is null then 'Customers (self-service)' else (select u.email::text from auth.users u where u.id = g.uid) end,
           'role', (select m.role from public.memberships m where m.organization_id = p_organization_id and m.user_id = g.uid),
           'orders', g.orders, 'order_value', g.order_value, 'net_sales', g.net, 'items', g.items,
           'average_sale', case when g.orders > 0 then round(g.order_value / g.orders, 2) end,
           'manual_discounts', g.manual_discounts,
           'discount_rate', case when g.net + g.manual_discounts > 0 then round(g.manual_discounts * 100 / (g.net + g.manual_discounts), 1) end,
           'returns', g.returns, 'refunded', g.refunded) order by g.order_value desc), '[]'::jsonb)
    from g
  into v_result;
  return jsonb_build_object('staff', v_result);
end $$;

select public._regrant_api();

-- ======================================================================
-- 0016_mobile_app.sql
-- ======================================================================
-- 0016_mobile_app.sql
-- The customer app (module `mobile_app`) runs on the same API as the online
-- store: the same catalogue, quotes, checkout and order pages, with its own
-- channel so reports and channel-only promotions can tell it apart. The store
-- lookups answer when either the website or the app is switched on (see 0001
-- and 0010). This adds the signed-in shopper's account in one call.

-- The signed-in shopper's account at one business: profile, points, store
-- credit and every order they have placed in any channel, at the counter
-- included once the till has them as the customer.
create or replace function public.my_account(p_organization_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  c public.customers%rowtype;
begin
  if auth.uid() is null or auth.role() is distinct from 'authenticated' then
    raise exception using errcode = '42501', message = 'PERMISSION_DENIED', detail = 'sign in first';
  end if;
  if not (public.module_enabled(p_organization_id, 'storefront') or public.module_enabled(p_organization_id, 'mobile_app')) then
    raise exception using errcode = 'NC002', message = 'MODULE_DISABLED', detail = 'mobile_app';
  end if;
  select * into c from public.customers where organization_id = p_organization_id and auth_user_id = auth.uid();

  return jsonb_build_object(
    'email', (select u.email from auth.users u where u.id = auth.uid()),
    'profile', case when c.id is not null then
      jsonb_build_object('customer_id', c.id, 'full_name', c.full_name, 'phone', c.phone, 'email', c.email) end,
    'store_credit', coalesce(c.store_credit_balance, 0),
    'loyalty', case when c.id is not null and public.module_enabled(p_organization_id, 'loyalty') then jsonb_build_object(
      'points', c.loyalty_points,
      'point_value', public._loyalty_setting(p_organization_id, 'loyalty_point_value', 1),
      'points_per_100', public._loyalty_setting(p_organization_id, 'loyalty_points_per_100', 1),
      'min_redeem', public._loyalty_setting(p_organization_id, 'loyalty_min_redeem', 0),
      'history', coalesce((
        select jsonb_agg(jsonb_build_object('points', l.points, 'reason', l.reason, 'at', l.created_at) order by l.created_at desc)
          from (select * from public.loyalty_ledger where customer_id = c.id order by created_at desc limit 30) l), '[]'::jsonb)) end,
    'orders', coalesce((
      select jsonb_agg(jsonb_build_object(
               'order_id', o.id, 'number', o.number, 'channel', o.channel, 'status', o.status,
               'payment_status', o.payment_status, 'fulfilment_method', o.fulfilment_method,
               'total', o.total, 'placed_at', o.placed_at, 'access_token', o.access_token,
               'items', (select coalesce(sum(ol.quantity), 0) from public.order_lines ol where ol.order_id = o.id),
               'first_item', (select ol.product_name from public.order_lines ol where ol.order_id = o.id order by ol.position limit 1))
             order by o.placed_at desc)
        from (select * from public.orders
               where customer_id = c.id and status <> 'expired'
               order by placed_at desc limit 50) o), '[]'::jsonb));
end $$;

select public._regrant_api();
